window.SHEETS=[{"id": "fortigate-cli-essentials", "title": "FortiGate CLI essentials", "vendor": "Fortinet", "category": "Cybersecurity", "description": "The everyday commands for finding your way around a FortiGate.", "rows": [["get system status", "Identify firmware and device information"], ["get system performance status", "Inspect CPU, memory and uptime"], ["get system interface", "Inspect interface information"], ["get system arp", "Inspect learned IPv4 neighbors"], ["get router info routing-table all", "Inspect active routes"], ["get system ha status", "Inspect high availability state"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-02", "walkthrough": ["Record the model, firmware and current VDOM so later output is interpreted in the right context.", "Capture CPU, memory, uptime and traffic/session indicators during the incident and again after a measured interval. A brief utilization spike and sustained pressure are different findings; compare with the same appliance under normal load.", "Find the affected interfaces, addresses and administrative state. Compare the WAN and LAN sides with the intended topology.", "Match the directly connected next hop to its IP and MAC address. Entries can age out when idle; a missing entry alone does not prove a fault. Compare the relevant interface and generate only an approved test before sampling again.", "Identify the best matching destination prefix, next hop and outgoing interface. Check the return path on the peer separately.", "Check whether the appliance is standalone or part of an HA cluster. Compare member roles and synchronization status with the intended design."], "scope": "FortiOS 7.4 inspection reference. Confirm your firmware, privileges and active VDOM; command availability varies by platform.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "Users report intermittent internet access", "symptom": "A branch firewall appears slow during a busy period. Establish its identity, resource state and forwarding path.", "steps": [{"action": "get system status", "purpose": "Identify firmware and device information", "detail": "Record the model, firmware and current VDOM so later output is interpreted in the right context."}, {"action": "get system performance status", "purpose": "Inspect CPU, memory and uptime", "detail": "Compare CPU and memory with the incident window and a known baseline; capture at least two samples."}, {"action": "get system interface", "purpose": "Inspect interface information", "detail": "Find the affected interfaces, addresses and administrative state. Compare the WAN and LAN sides with the intended topology."}, {"action": "get router info routing-table all", "purpose": "Inspect active routes", "detail": "Identify the best matching destination prefix, next hop and outgoing interface. Check the return path on the peer separately."}], "interpretation": "A high resource reading during the incident suggests load deserves investigation; a missing expected route points toward forwarding. Either result needs correlation before making a change.", "verification": "Record firmware, affected interfaces and a timed baseline; compare a second sample and verify the route and user experience after the approved fix."}}, {"id": "cisco-ios-essentials", "title": "Cisco IOS essentials", "vendor": "Cisco", "category": "Networking", "description": "Get oriented, inspect interfaces, and understand your device.", "rows": [["show version", "Identify software and device information"], ["show ip interface brief", "Check interface addresses and status"], ["show interfaces", "Inspect interface counters"], ["show running-config", "Review active configuration"], ["show inventory", "List hardware inventory"], ["show logging", "Review buffered system events"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 6, "product": "Cisco", "updated": "2026-11-02", "walkthrough": ["Record the device model and IOS or IOS XE release before comparing commands with documentation.", "Find the management interface and compare its IP address, Status and Protocol with the expected state.", "Inspect the affected port’s detailed line protocol, errors and recent counters. A cumulative counter needs a timed comparison.", "Review only the relevant management interface and addressing configuration. Protect the output because it can contain sensitive settings.", "Record chassis, module and transceiver identities so the incident is tied to the correct hardware. Inventory presence does not establish operational health. Serial numbers can be sensitive; retain them in the internal ticket only.", "Compare interface or routing messages with the incident time. Logging configuration and buffer retention determine which events are available."], "scope": "Cisco IOS / IOS XE inspection reference. Confirm device model, release and EXEC privileges; switch-specific commands may not exist on routers.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A switch management address stops responding", "symptom": "A previously reachable switch is not answering on its management address.", "steps": [{"action": "show version", "purpose": "Identify software and device information", "detail": "Record the device model and IOS or IOS XE release before comparing commands with documentation."}, {"action": "show ip interface brief", "purpose": "Check interface addresses and status", "detail": "Find the management interface and compare its IP address, Status and Protocol with the expected state."}, {"action": "show interfaces", "purpose": "Inspect interface counters", "detail": "Inspect the affected port’s detailed line protocol, errors and recent counters. A cumulative counter needs a timed comparison."}, {"action": "show running-config", "purpose": "Review active configuration", "detail": "Review only the relevant management interface and addressing configuration. Protect the output because it can contain sensitive settings."}], "interpretation": "An administratively down interface, an operationally down link and a reachable interface with the wrong address are different findings. Compare the configuration to the expected management network.", "verification": "Retest access from the approved management subnet and confirm that the interface remains up. Capture only the configuration needed for the ticket."}}, {"id": "fortigate-routing-arp", "title": "FortiGate routing & ARP", "vendor": "Fortinet", "category": "Networking", "description": "Follow a packet from its next hop to the routing table.", "rows": [["get router info routing-table all", "Inspect active routes"], ["get system arp", "Resolve local neighbors"], ["diagnose ip arp list", "Inspect detailed ARP entries"], ["diagnose ip route list", "Inspect kernel routes"], ["get router info routing-table details <destination-ip>", "Inspect the route selected for one destination"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-02", "walkthrough": ["Compare other active routes for the same destination or a more-specific prefix.", "Match the directly connected next hop to its IP and MAC address. Entries can age out when idle; a missing entry alone does not prove a fault. Compare the relevant interface and generate only an approved test before sampling again.", "Inspect ARP details and the relevant interface; an unresolved neighbor suggests a local link or peer issue, not necessarily a remote routing problem.", "Inspect the kernel forwarding entries for the affected destination and compare them with the routing-table output. Note prefix, interface and gateway. Differences require checking the active VDOM and routing context before drawing conclusions.", "Replace the placeholder with the destination address. Compare the selected route, outgoing interface and gateway with the expected forward path."], "scope": "FortiOS 7.4 inspection reference. Confirm your firmware, privileges and active VDOM; command availability varies by platform.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "Traffic cannot reach a remote subnet", "symptom": "A client reaches local systems but fails to reach a service on another subnet.", "steps": [{"action": "get router info routing-table details <destination-ip>", "purpose": "Inspect the route selected for one destination", "detail": "Replace <destination-ip> with the affected destination. Note the chosen prefix, gateway and interface."}, {"action": "get router info routing-table all", "purpose": "Inspect active routes", "detail": "Compare other active routes for the same destination or a more-specific prefix."}, {"action": "get system arp", "purpose": "Resolve local neighbors", "detail": "Find the next-hop address in the ARP table when it is directly connected; absence can mean it has not recently been contacted."}, {"action": "diagnose ip arp list", "purpose": "Inspect detailed ARP entries", "detail": "Inspect ARP details and the relevant interface; an unresolved neighbor suggests a local link or peer issue, not necessarily a remote routing problem."}], "interpretation": "A missing or unexpected route directs attention to routing. A directly connected next hop without a resolved ARP entry points to the local link or neighbor.", "verification": "Repeat the route lookup and neighbor check, then test the approved service in both directions."}}, {"id": "cisco-interface-diagnostics", "title": "Cisco interface diagnostics", "vendor": "Cisco", "category": "Networking", "description": "Find link failures and read the counters that matter.", "rows": [["show ip interface brief", "Summarize interface state"], ["show interfaces status", "Inspect switch port status"], ["show interfaces counters errors", "Inspect switch errors"], ["show interfaces description", "Inspect configured descriptions"], ["show interfaces", "Inspect detailed interface state"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 6, "product": "Cisco", "updated": "2026-11-02", "walkthrough": ["Identify the affected interface and compare IP address, administrative state and protocol.", "Check switch-port state and negotiated link attributes on the relevant port.", "Capture error counters twice with timestamps; rising CRC or input errors are stronger evidence than one old nonzero value.", "Use descriptions to identify the intended connection, then verify the peer and cabling because labels can be stale.", "Read input errors, output errors, drops and link transitions for the affected port. Compare two samples because counters may include old events."], "scope": "Cisco IOS / IOS XE inspection reference. Confirm device model, release and EXEC privileges; switch-specific commands may not exist on routers.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A switch port drops connectivity intermittently", "symptom": "One wired client disconnects while nearby clients remain online.", "steps": [{"action": "show ip interface brief", "purpose": "Summarize interface state", "detail": "Identify the affected interface and compare IP address, administrative state and protocol."}, {"action": "show interfaces status", "purpose": "Inspect switch port status", "detail": "Check switch-port state and negotiated link attributes on the relevant port."}, {"action": "show interfaces counters errors", "purpose": "Inspect switch errors", "detail": "Capture error counters twice with timestamps; rising CRC or input errors are stronger evidence than one old nonzero value."}, {"action": "show interfaces description", "purpose": "Inspect configured descriptions", "detail": "Use descriptions to identify the intended connection, then verify the peer and cabling because labels can be stale."}], "interpretation": "A down link indicates a physical or peer issue; increasing errors while the link is up suggest a link-quality or negotiation issue. Compare two samples.", "verification": "After the approved repair, check link state and error trends again and have the user retest the application."}}, {"id": "fortigate-vpn-health", "title": "FortiGate VPN health", "vendor": "Fortinet", "category": "Cybersecurity", "description": "Inspect IPsec tunnel health and security associations.", "rows": [["get vpn ipsec tunnel summary", "Summarize tunnel state"], ["diagnose vpn tunnel list", "Inspect IPsec tunnel details"], ["diagnose vpn ike gateway list", "Inspect IKE gateways"], ["diagnose vpn ipsec status", "Inspect IPsec status"], ["get router info routing-table all", "Verify routes toward the remote network"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-02", "walkthrough": ["Locate the tunnel by peer or name and record its status and counters.", "Inspect phase 2 selectors and security associations for the actual source and destination subnets.", "Confirm the expected IKE gateway and remote peer; a missing gateway or unexpected peer narrows the problem.", "Inspect IPsec processing statistics and compare two timed samples during an approved test. Global counters may include multiple tunnels; correlate them with the named tunnel details instead of treating them as proof about one connection.", "A live tunnel needs a route and matching policy as well as an active security association. Compare the selected egress interface with the expected VPN path."], "scope": "FortiOS 7.4 inspection reference. Confirm your firmware, privileges and active VDOM; command availability varies by platform.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "An IPsec tunnel is up but a service is unreachable", "symptom": "A branch-to-branch application has stopped working even though a VPN appears present.", "steps": [{"action": "get vpn ipsec tunnel summary", "purpose": "Summarize tunnel state", "detail": "Locate the tunnel by peer or name and record its status and counters."}, {"action": "diagnose vpn tunnel list", "purpose": "Inspect IPsec tunnel details", "detail": "Inspect phase 2 selectors and security associations for the actual source and destination subnets."}, {"action": "diagnose vpn ike gateway list", "purpose": "Inspect IKE gateways", "detail": "Confirm the expected IKE gateway and remote peer; a missing gateway or unexpected peer narrows the problem."}, {"action": "get router info routing-table all", "purpose": "Verify routes toward the remote network", "detail": "Find the route to the remote service and confirm the egress interface points toward the expected VPN; also check the return path."}], "interpretation": "An established tunnel alone is insufficient: compare phase 2 selectors, route, firewall policy and the return path. Counters changing in one direction can guide the next check.", "verification": "Retest the specific application from an approved source and confirm bidirectional traffic counters on the intended tunnel."}}, {"id": "cisco-vlans-trunks", "title": "Cisco VLANs & trunks", "vendor": "Cisco", "category": "Networking", "description": "Understand access VLANs, tagged links, and Layer 2 boundaries.", "rows": [["show vlan brief", "Inspect VLAN membership"], ["show interfaces trunk", "Inspect trunk status"], ["show interfaces switchport", "Inspect switchport settings"], ["show spanning-tree", "Inspect spanning tree state"], ["show mac address-table", "Inspect learned MAC addresses"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 6, "product": "Cisco", "updated": "2026-11-02", "walkthrough": ["Find the endpoint access port and its assigned VLAN. A defined VLAN alone does not prove that it reaches the gateway.", "On both ends of the uplink compare trunk state and the allowed and active VLAN lists.", "Inspect the access port and uplink switchport mode, including native VLAN where relevant.", "Identify the root bridge, VLAN or instance and the uplink port roles. A blocked alternate path can be correct loop prevention. Investigate an unexpected root or role against the topology rather than trying to force a blocked port into forwarding.", "Compare the learned VLAN and port against the endpoint location. An inactive endpoint may age out, so an absent entry is not conclusive by itself."], "scope": "Cisco IOS / IOS XE inspection reference. Confirm device model, release and EXEC privileges; switch-specific commands may not exist on routers.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A new VLAN works locally but not across switches", "symptom": "A workstation and gateway are on different switches and the VLAN does not pass the uplink.", "steps": [{"action": "show vlan brief", "purpose": "Inspect VLAN membership", "detail": "Find the endpoint access port and its assigned VLAN. A defined VLAN alone does not prove that it reaches the gateway."}, {"action": "show interfaces trunk", "purpose": "Inspect trunk status", "detail": "On both ends of the uplink compare trunk state and the allowed and active VLAN lists."}, {"action": "show interfaces switchport", "purpose": "Inspect switchport settings", "detail": "Inspect the access port and uplink switchport mode, including native VLAN where relevant."}, {"action": "show mac address-table", "purpose": "Inspect learned MAC addresses", "detail": "Look for the endpoint MAC in the correct VLAN and note the learned port; an inactive endpoint can age out."}], "interpretation": "Check that the access port is in the intended VLAN and the VLAN is allowed and active on the trunk. MAC learning on the expected port helps localize the path.", "verification": "Recheck both ends of the trunk, learned MAC addresses and the gateway test after the approved configuration change."}}, {"id": "fortigate-ha-system-health", "title": "FortiGate HA & system health", "vendor": "Fortinet", "category": "Cybersecurity", "description": "Check cluster membership and baseline appliance health.", "rows": [["get system ha status", "Inspect cluster members"], ["get system performance status", "Inspect resource usage"], ["diagnose sys ntp status", "Inspect time synchronization"], ["get system status", "Identify firmware"], ["diagnose system ha status", "Inspect HA diagnostic status"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-02", "walkthrough": ["Record the cluster members, roles and synchronization status without initiating a failover.", "Capture CPU, memory, uptime and traffic/session indicators during the incident and again after a measured interval. A brief utilization spike and sustained pressure are different findings; compare with the same appliance under normal load.", "Check time synchronization on the member under investigation; compare time sources and timestamps.", "Record firmware and appliance identity so both members can be compared.", "Compare cluster state and member details with the expected primary and secondary roles. Check both units before drawing conclusions about synchronization."], "scope": "FortiOS 7.4 inspection reference. Confirm your firmware, privileges and active VDOM; command availability varies by platform.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "The standby firewall shows a health concern", "symptom": "An HA member has an alert following a maintenance window.", "steps": [{"action": "get system ha status", "purpose": "Inspect cluster members", "detail": "Record the cluster members, roles and synchronization status without initiating a failover."}, {"action": "diagnose sys ntp status", "purpose": "Inspect time synchronization", "detail": "Check time synchronization on the member under investigation; compare time sources and timestamps."}, {"action": "get system status", "purpose": "Identify firmware", "detail": "Record firmware and appliance identity so both members can be compared."}, {"action": "diagnose system ha status", "purpose": "Inspect HA diagnostic status", "detail": "Read diagnostic HA details and compare member health with the expected cluster state."}], "interpretation": "Compare roles, synchronization and time across members. A mismatch in member state or clock is evidence to investigate; it does not justify an immediate failover.", "verification": "Confirm both members return to the intended cluster state and record the result without forcing a production failover."}}, {"id": "cisco-routing-basics", "title": "Cisco routing basics", "vendor": "Cisco", "category": "Networking", "description": "Read connected, static, and learned routes with confidence.", "rows": [["show ip route", "Inspect IPv4 routes"], ["show ip protocols", "Inspect routing protocols"], ["show ip arp", "Inspect IPv4 neighbors"], ["show ip interface brief", "Inspect interface status"], ["show ip route <destination-ip>", "Inspect the route to a destination"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 6, "product": "Cisco", "updated": "2026-11-02", "walkthrough": ["Locate the destination prefix and note the selected route source, next hop and outgoing interface.", "Identify active routing protocols, advertised networks and known routing sources. Compare the expected protocol and neighbor information with the design. This summary does not prove that a particular destination was installed in the forwarding table.", "If the next hop is directly connected, compare its IP and MAC mapping with the local segment.", "Confirm the outgoing interface has the expected address and operational state. An up interface does not prove end-to-end reachability.", "Replace the placeholder with an IPv4 destination. Review the selected prefix, next hop and interface, then check the return route independently."], "scope": "Cisco IOS / IOS XE inspection reference. Confirm device model, release and EXEC privileges; switch-specific commands may not exist on routers.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A router has a route but traffic still fails", "symptom": "A routed service is unreachable from one source network.", "steps": [{"action": "show ip route", "purpose": "Inspect IPv4 routes", "detail": "Locate the destination prefix and note the selected route source, next hop and outgoing interface."}, {"action": "show ip route <destination-ip>", "purpose": "Inspect the route to a destination", "detail": "Substitute the specific destination address and confirm the most-specific matching route."}, {"action": "show ip arp", "purpose": "Inspect IPv4 neighbors", "detail": "If the next hop is directly connected, compare its IP and MAC mapping with the local segment."}, {"action": "show ip interface brief", "purpose": "Inspect interface status", "detail": "Confirm the outgoing interface has the expected address and operational state. An up interface does not prove end-to-end reachability."}], "interpretation": "The most specific route and outgoing interface establish the forward path only. Check next-hop resolution and the destination’s return route separately.", "verification": "Repeat the destination lookup and perform a scoped service test from the affected source after the approved correction."}}, {"id": "fortigate-session-inspection", "title": "FortiGate session inspection", "vendor": "Fortinet", "category": "Cybersecurity", "description": "Connect policy decisions with live traffic sessions.", "rows": [["get system session status", "Inspect session totals"], ["diagnose sys session stat", "Inspect session statistics"], ["diagnose sys session list", "Inspect session entries"], ["get system performance status", "Inspect appliance load"], ["get router info routing-table all", "Check the route alongside session information"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-02", "walkthrough": ["Check current session totals and record the sample time. Compare a second sample during the incident with the normal session count for this appliance; a high count alone does not identify which traffic is responsible.", "Compare session statistics with an established baseline for this appliance.", "Inspect the relevant source, destination, translated addresses, policy and interfaces. Filter appropriately for your release before listing a large table.", "Capture CPU, memory, uptime and traffic/session indicators during the incident and again after a measured interval. A brief utilization spike and sustained pressure are different findings; compare with the same appliance under normal load.", "Use the active route table to establish the expected egress path. Existing sessions can persist across changes, so record timing before comparing observations."], "scope": "FortiOS 7.4 inspection reference. Confirm your firmware, privileges and active VDOM; command availability varies by platform.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A policy was changed but a connection behaves unexpectedly", "symptom": "A single client continues to see an old behavior after a firewall policy change.", "steps": [{"action": "get system session status", "purpose": "Inspect session totals", "detail": "Check current session totals and record the sample time. Compare a second sample during the incident with the normal session count for this appliance; a high count alone does not identify which traffic is responsible."}, {"action": "diagnose sys session stat", "purpose": "Inspect session statistics", "detail": "Compare session statistics with an established baseline for this appliance."}, {"action": "diagnose sys session list", "purpose": "Inspect session entries", "detail": "Inspect the relevant source, destination, translated addresses, policy and interfaces. Filter appropriately for your release before listing a large table."}, {"action": "get router info routing-table all", "purpose": "Check the route alongside session information", "detail": "Compare the active route for the same destination; record the time because an existing session may reflect an earlier forwarding decision."}], "interpretation": "Compare the session’s endpoints, interface and timing with the intended policy and route. Existing sessions can outlive a configuration change.", "verification": "Capture the evidence and follow the approved change procedure before clearing any session; retest a new connection afterwards."}}, {"id": "cisco-neighbor-discovery", "title": "Cisco neighbor discovery", "vendor": "Cisco", "category": "Networking", "description": "Map the devices directly connected to your switch.", "rows": [["show cdp neighbors", "List Cisco discovery neighbors"], ["show cdp neighbors detail", "Inspect neighbor details"], ["show lldp neighbors", "List LLDP neighbors"], ["show lldp neighbors detail", "Inspect LLDP details"], ["show interfaces description", "Map port descriptions to the topology"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 6, "product": "Cisco", "updated": "2026-11-02", "walkthrough": ["Identify the local uplink and advertised Cisco neighbor on that port.", "Inspect neighbor details, including remote port and device identity, and compare with the topology record.", "Check LLDP where enabled on both sides; a missing LLDP entry can reflect configuration or peer support.", "Compare the remote chassis identity and port ID with the local uplink and cabling record. LLDP advertisements describe what the neighbor reports; stale entries or disabled discovery can complicate interpretation, so confirm the physical path separately.", "Compare interface descriptions with discovered neighbors and the physical cabling plan. Descriptions are manually maintained and can be stale."], "scope": "Cisco IOS / IOS XE inspection reference. Confirm device model, release and EXEC privileges; switch-specific commands may not exist on routers.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "The switch uplink connects to an unexpected device", "symptom": "A topology diagram and port label disagree about an uplink.", "steps": [{"action": "show cdp neighbors", "purpose": "List Cisco discovery neighbors", "detail": "Identify the local uplink and advertised Cisco neighbor on that port."}, {"action": "show cdp neighbors detail", "purpose": "Inspect neighbor details", "detail": "Inspect neighbor details, including remote port and device identity, and compare with the topology record."}, {"action": "show lldp neighbors", "purpose": "List LLDP neighbors", "detail": "Check LLDP where enabled on both sides; a missing LLDP entry can reflect configuration or peer support."}, {"action": "show interfaces description", "purpose": "Map port descriptions to the topology", "detail": "Compare the manually maintained interface description with the discovered neighbor and physical cabling record."}], "interpretation": "Match local and remote port identifiers, then compare them with the cable record. Missing discovery data can mean the peer has the protocol disabled.", "verification": "Update the inventory only after confirming the physical path; compare the neighbor again after any approved cabling change."}}, {"id": "linux-network-essentials", "title": "Linux network essentials", "vendor": "Linux", "category": "IT fundamentals", "description": "A small toolkit for inspecting a Linux host’s network.", "rows": [["ip address show", "Inspect interface addresses"], ["ip route show", "Inspect routing table"], ["ip neigh show", "Inspect neighbors"], ["ss -tuln", "Inspect listening TCP and UDP sockets"], ["ip -s link show", "Inspect interface counters"]], "source": "https://man7.org/linux/man-pages/man8/ip.8.html", "level": "Beginner", "time": 6, "product": "Linux", "updated": "2026-11-02", "walkthrough": ["Identify the interface carrying the affected traffic and compare its address and prefix with the intended subnet.", "Find the default or more-specific route and note its gateway and source interface.", "Inspect the neighbor state for a directly connected gateway; incomplete or failed resolution suggests a local path issue.", "Read the local address and port for TCP listeners and bound UDP sockets. A loopback-only listener cannot accept remote traffic. UDP does not establish a TCP-style listening session, and a bound socket alone does not prove the application is responding.", "Compare errors and drops on the affected link over time. The counters describe interface activity and do not independently identify an application fault."], "scope": "Linux with iproute2. Some process and interface details require elevated read privileges.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A Linux server cannot reach its gateway", "symptom": "A server has lost connectivity after a network change.", "steps": [{"action": "ip address show", "purpose": "Inspect interface addresses", "detail": "Identify the interface carrying the affected traffic and compare its address and prefix with the intended subnet."}, {"action": "ip route show", "purpose": "Inspect routing table", "detail": "Find the default or more-specific route and note its gateway and source interface."}, {"action": "ip neigh show", "purpose": "Inspect neighbors", "detail": "Inspect the neighbor state for a directly connected gateway; incomplete or failed resolution suggests a local path issue."}, {"action": "ip -s link show", "purpose": "Inspect interface counters", "detail": "Compare link errors and drops across two timed samples to see whether counters are increasing."}], "interpretation": "Verify the intended address and route first. A missing or incomplete neighbor entry for a directly connected gateway suggests local link or neighbor resolution trouble.", "verification": "Repeat the address, route and neighbor checks and test the approved destination after the network issue is corrected."}}, {"id": "cloud-network-fundamentals", "title": "Cloud network fundamentals", "vendor": "Vendor neutral", "category": "Cloud", "description": "Connect subnets, routes, security rules, and DNS into one model.", "rows": [["CIDR", "An address prefix defines a network range"], ["Subnet", "A segment of a virtual network"], ["Route table", "Maps destination prefixes to next hops"], ["Security group", "Controls permitted traffic for associated resources"], ["Private DNS", "Resolves internal service names"], ["Network ACL", "A subnet-level traffic control in some cloud platforms"]], "source": "https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html", "level": "Beginner", "time": 6, "product": "Vendor neutral", "updated": "2026-11-02", "walkthrough": ["Compare source and destination prefixes to establish whether traffic is local or requires a routed path.", "Identify the source and destination subnets, address ranges and the service endpoint.", "Trace each applicable route table and next hop, including the return direction.", "Compare the relevant stateful security rules with the required source, destination, protocol and port.", "Resolve the service name from the workload’s environment and compare the result with the intended private address.", "Check the platform’s direction, rule ordering and stateful or stateless behavior. Security group and network ACL semantics are provider-specific."], "scope": "Provider-neutral networking concepts. This sheet contains reference concepts rather than executable shell commands.", "prerequisites": "Confirm the target device and software release using approved access. Replace angle-bracket placeholders with local values; do not paste placeholders literally. Record the incident time and affected traffic path before collecting output.", "case": {"title": "A private workload cannot reach an internal service", "symptom": "Two workloads in different subnets should communicate over a private address.", "steps": [{"action": "CIDR", "purpose": "An address prefix defines a network range", "detail": "Compare source and destination prefixes to establish whether traffic is local or requires a routed path."}, {"action": "Subnet", "purpose": "A segment of a virtual network", "detail": "Identify the source and destination subnets, address ranges and the service endpoint."}, {"action": "Route table", "purpose": "Maps destination prefixes to next hops", "detail": "Trace each applicable route table and next hop, including the return direction."}, {"action": "Security group", "purpose": "Controls permitted traffic for associated resources", "detail": "Compare the relevant stateful security rules with the required source, destination, protocol and port."}, {"action": "Private DNS", "purpose": "Resolves internal service names", "detail": "Resolve the service name from the workload’s environment and compare the result with the intended private address."}], "interpretation": "Trace the source subnet, route, network access rules and name resolution in both directions. Provider security controls have different stateful and rule-order semantics.", "verification": "Document the actual path and confirm the service and return traffic after an authorized correction."}}, {"id": "windows-network-troubleshooting", "title": "Windows network troubleshooting", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Inspect addressing, DNS resolution and TCP reachability with PowerShell.", "scope": "Windows 10/11 and Windows Server with NetTCPIP and DnsClient modules.", "prerequisites": "Open PowerShell on the affected host. Replace server.example.com with an approved test host; TCP tests send probes.", "source": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/", "sourceLabel": "Windows official documentation", "rows": [["Get-NetIPConfiguration", "Inspect addresses and gateways"], ["Get-NetAdapter", "Inspect adapter state and link speed"], ["Resolve-DnsName server.example.com", "Resolve a host name"], ["Test-NetConnection server.example.com -Port 443", "Test a specific TCP service"], ["Get-DnsClientServerAddress", "List configured DNS servers by interface"]], "walkthrough": ["Find the adapter carrying the affected traffic. Compare its address, default gateway and DNS servers with the intended subnet. Disconnected adapters may appear alongside the active one.", "Match the interface name to the physical or virtual adapter. A disconnected interface points to a link or virtual-switch issue before DNS becomes relevant.", "Replace the example name with your target. Check the answer and record whether the response is NXDOMAIN, a timeout or an unexpected address; these indicate different failure paths.", "Check TcpTestSucceeded and the selected source address. A successful test confirms a TCP connection, not application authentication or TLS correctness.", "Match the server addresses to the adapter used by the affected connection. A configured server can still be unreachable or return an unexpected answer."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A Windows workstation cannot open an internal site", "symptom": "The browser fails to reach an internal HTTPS application, while the user is connected to the network.", "steps": [{"action": "Get-NetAdapter", "purpose": "Inspect adapter state and link speed", "detail": "Match the interface name to the physical or virtual adapter. A disconnected interface points to a link or virtual-switch issue before DNS becomes relevant."}, {"action": "Get-NetIPConfiguration", "purpose": "Inspect addresses and gateways", "detail": "Find the adapter carrying the affected traffic. Compare its address, default gateway and DNS servers with the intended subnet. Disconnected adapters may appear alongside the active one."}, {"action": "Resolve-DnsName server.example.com", "purpose": "Resolve a host name", "detail": "Replace the example name with your target. Check the answer and record whether the response is NXDOMAIN, a timeout or an unexpected address; these indicate different failure paths."}, {"action": "Test-NetConnection server.example.com -Port 443", "purpose": "Test a specific TCP service", "detail": "Check TcpTestSucceeded and the selected source address. A successful test confirms a TCP connection, not application authentication or TLS correctness."}, {"action": "Get-DnsClientServerAddress", "purpose": "List configured DNS servers by interface", "detail": "Match the server addresses to the adapter used by the affected connection. A configured server can still be unreachable or return an unexpected answer."}], "interpretation": "A failed DNS lookup differs from successful name resolution followed by a failed TCP connection. Compare the selected adapter and DNS server with the expected configuration.", "verification": "Repeat name resolution and the TCP 443 test using the intended service name, then retest in the application."}}, {"id": "windows-services-and-event-logs", "title": "Windows services and event logs", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Build a focused picture of service state and recent system errors.", "scope": "Windows PowerShell 5.1 or supported PowerShell on Windows.", "prerequisites": "Use an account permitted to read the selected event log. These commands do not start or stop services.", "source": "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent", "sourceLabel": "Windows official documentation", "rows": [["Get-Service", "List service states"], ["Get-Service -Name Spooler", "Inspect a specific service"], ["Get-WinEvent -FilterHashtable @{LogName='System'; Level=2; StartTime=(Get-Date).AddHours(-2)} -MaxEvents 30", "Read recent system errors"], ["Get-Process | Sort-Object CPU -Descending | Select-Object -First 10", "Inspect cumulative CPU usage"], ["Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,LastBootUpTime", "Inspect operating-system version and boot time"]], "walkthrough": ["Find the affected service and its actual status. A stopped service may be intentional; compare against its startup policy and the application runbook.", "This example checks Print Spooler. Substitute the service name, not its display label. Record status before considering any restart.", "Correlate provider, event ID and timestamp with the incident. No matches is different from access denied or a missing log; preserve the distinction.", "CPU here is accumulated processor time since each process started. It is not a live utilization percentage; confirm a suspected spike with Performance Monitor.", "Compare the last boot time with the incident timeline. A restart can explain a brief interruption but does not by itself identify the trigger."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "An application service stopped during the night", "symptom": "A service is stopped and users report that an application was unavailable in the morning.", "steps": [{"action": "Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,LastBootUpTime", "purpose": "Inspect operating-system version and boot time", "detail": "Compare the last boot time with the incident timeline. A restart can explain a brief interruption but does not by itself identify the trigger."}, {"action": "Get-Service -Name Spooler", "purpose": "Inspect a specific service", "detail": "This example checks Print Spooler. Substitute the service name, not its display label. Record status before considering any restart."}, {"action": "Get-WinEvent -FilterHashtable @{LogName='System'; Level=2; StartTime=(Get-Date).AddHours(-2)} -MaxEvents 30", "purpose": "Read recent system errors", "detail": "Correlate provider, event ID and timestamp with the incident. No matches is different from access denied or a missing log; preserve the distinction."}, {"action": "Get-Process | Sort-Object CPU -Descending | Select-Object -First 10", "purpose": "Inspect cumulative CPU usage", "detail": "CPU here is accumulated processor time since each process started. It is not a live utilization percentage; confirm a suspected spike with Performance Monitor."}], "interpretation": "Align the boot time, service state and system-event timestamps. Cumulative process CPU is not current CPU utilization and a stopped service may be intentional.", "verification": "After the approved service recovery, confirm its state and examine new events; avoid treating a restart alone as the root cause."}}, {"id": "active-directory-users-and-groups", "title": "Active Directory users and groups", "product": "Active Directory", "vendor": "Active Directory", "category": "Identity & Microsoft 365", "description": "Inspect domain identity, user status and group membership using RSAT.", "scope": "On-premises Active Directory Domain Services; ActiveDirectory PowerShell module.", "prerequisites": "Install RSAT through your approved software process. Use a domain-connected administrative workstation and an account with directory read access.", "source": "https://learn.microsoft.com/en-us/powershell/module/activedirectory/", "sourceLabel": "Active Directory official documentation", "rows": [["Get-ADDomain", "Identify the current domain"], ["Get-ADUser -Identity 'jdoe' -Properties Enabled,LockedOut,PasswordLastSet", "Inspect a user account"], ["Get-ADPrincipalGroupMembership -Identity 'jdoe'", "List principal group memberships"], ["Get-ADGroupMember -Identity 'Helpdesk'", "Inspect direct group members"], ["Get-ADUser -Identity 'jdoe' -Properties MemberOf", "Inspect direct group references on an account"]], "walkthrough": ["Confirm DNSRoot, distinguished name and domain controllers. Querying the wrong domain can look like a missing user.", "Replace jdoe with a real sAMAccountName. Compare Enabled and LockedOut separately; neither field alone proves that sign-in will succeed.", "Review returned groups against expected access. This list is not a complete effective-access calculation across ACLs, claims and all resource domains.", "Replace the example group. This returns direct membership; nested groups need separate inspection or the -Recursive parameter.", "Replace jdoe with the account. MemberOf describes direct membership references; evaluate nested groups and resource permissions separately."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A user cannot access a shared resource", "symptom": "A user can sign in but reports that a newly granted shared-resource permission is not working.", "steps": [{"action": "Get-ADDomain", "purpose": "Identify the current domain", "detail": "Confirm DNSRoot, distinguished name and domain controllers. Querying the wrong domain can look like a missing user."}, {"action": "Get-ADUser -Identity 'jdoe' -Properties Enabled,LockedOut,PasswordLastSet", "purpose": "Inspect a user account", "detail": "Replace jdoe with a real sAMAccountName. Compare Enabled and LockedOut separately; neither field alone proves that sign-in will succeed."}, {"action": "Get-ADPrincipalGroupMembership -Identity 'jdoe'", "purpose": "List principal group memberships", "detail": "Review returned groups against expected access. This list is not a complete effective-access calculation across ACLs, claims and all resource domains."}, {"action": "Get-ADGroupMember -Identity 'Helpdesk'", "purpose": "Inspect direct group members", "detail": "Replace the example group. This returns direct membership; nested groups need separate inspection or the -Recursive parameter."}, {"action": "Get-ADUser -Identity 'jdoe' -Properties MemberOf", "purpose": "Inspect direct group references on an account", "detail": "Replace jdoe with the account. MemberOf describes direct membership references; evaluate nested groups and resource permissions separately."}], "interpretation": "Confirm the user and domain, account state and relevant direct or nested groups. Group membership is only one input to effective permissions and a fresh sign-in may be relevant.", "verification": "Verify the intended resource access with the user after the approved group or permission change and review propagation where applicable."}}, {"id": "active-directory-replication-health", "title": "Active Directory replication health", "product": "Active Directory", "vendor": "Active Directory", "category": "Identity & Microsoft 365", "description": "Compare domain-controller replication and locate recent failures.", "scope": "AD DS with RSAT ActiveDirectory module and repadmin available.", "prerequisites": "Run from an authorized domain administration workstation with network reachability to domain controllers. Collect results before changing replication topology.", "source": "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationfailure", "sourceLabel": "Active Directory official documentation", "rows": [["Get-ADDomainController -Filter *", "List domain controllers"], ["Get-ADReplicationFailure -Target 'corp.example.com' -Scope Domain", "Inspect recorded replication failures"], ["repadmin /replsummary", "Summarize replication failures"], ["repadmin /showrepl", "Inspect local controller replication partners"], ["Get-ADReplicationPartnerMetadata -Target 'corp-DC01'", "Inspect replication partner metadata"]], "walkthrough": ["Compare host names and site assignments with your topology. Confirm whether an affected controller is reachable before interpreting replication failures.", "Replace the example domain. Record the partner, error code, first failure time and failure count. Empty output does not independently certify overall directory health.", "Compare failed attempts and largest delta across sources and destinations. Investigate persistent deltas against the configured site-link schedule.", "Run on the controller you are investigating or specify the intended controller per repadmin help. Correlate last successful replication with the incident window.", "Replace corp-DC01 with the affected domain controller. Compare last attempt and last success for each inbound partner and naming context."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "An account change appears on only one domain controller", "symptom": "An administrator changed an attribute but another site still shows the previous value.", "steps": [{"action": "Get-ADDomainController -Filter *", "purpose": "List domain controllers", "detail": "Compare host names and site assignments with your topology. Confirm whether an affected controller is reachable before interpreting replication failures."}, {"action": "repadmin /replsummary", "purpose": "Summarize replication failures", "detail": "Compare failed attempts and largest delta across sources and destinations. Investigate persistent deltas against the configured site-link schedule."}, {"action": "repadmin /showrepl", "purpose": "Inspect local controller replication partners", "detail": "Run on the controller you are investigating or specify the intended controller per repadmin help. Correlate last successful replication with the incident window."}, {"action": "Get-ADReplicationPartnerMetadata -Target 'corp-DC01'", "purpose": "Inspect replication partner metadata", "detail": "Replace corp-DC01 with the affected domain controller. Compare last attempt and last success for each inbound partner and naming context."}, {"action": "Get-ADReplicationFailure -Target 'corp.example.com' -Scope Domain", "purpose": "Inspect recorded replication failures", "detail": "Replace the example domain. Record the partner, error code, first failure time and failure count. Empty output does not independently certify overall directory health."}], "interpretation": "Identify the affected controller, replication partner and last success. Use the actual error to investigate DNS, connectivity, authentication or topology instead of forcing replication blindly.", "verification": "Confirm subsequent successful replication and compare the affected attribute on the relevant controllers."}}, {"id": "microsoft-graph-connection-and-user-lookup", "title": "Microsoft Graph connection and user lookup", "product": "Microsoft Graph", "vendor": "Microsoft Graph", "category": "Identity & Microsoft 365", "description": "Connect to the correct tenant and inspect directory user records.", "scope": "Microsoft Graph PowerShell SDK v1.0 commands, delegated authentication.", "prerequisites": "Use approved Microsoft.Graph.Authentication and Microsoft.Graph.Users modules. User.Read.All needs administrator consent; use an already authorized app and account.", "source": "https://learn.microsoft.com/en-us/powershell/microsoftgraph/authentication-commands", "sourceLabel": "Microsoft Graph official documentation", "rows": [["Connect-MgGraph -Scopes 'User.Read.All' -ContextScope Process", "Authenticate for directory reads"], ["Get-MgContext", "Verify tenant and granted scopes"], ["Get-MgUser -UserId 'user@example.com' -Property Id,DisplayName,UserPrincipalName,AccountEnabled", "Read a specific user"], ["Disconnect-MgGraph", "End the Graph session"], ["Get-MgUser -Top 10", "Inspect a small user sample"]], "walkthrough": ["Complete interactive authentication for your approved tenant. The process scope avoids persisting this session context beyond the PowerShell process. Follow your administrator’s consent process if prompted.", "Check TenantId, Account and Scopes before running queries. Stop if the identity or tenant differs from your intended environment.", "Replace the example UPN. Requesting AccountEnabled explicitly avoids relying on the default property set. An authorization error is not evidence that the account is missing.", "Disconnect when the investigation is complete. Store only the minimum necessary findings; user identifiers and account states are organizational data.", "This returns a bounded sample with default properties. It is useful for verifying read access, but it is not a complete inventory or tenant count."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A Graph query returns an unexpected account result", "symptom": "An administrator is investigating whether a user exists in the intended tenant.", "steps": [{"action": "Connect-MgGraph -Scopes 'User.Read.All' -ContextScope Process", "purpose": "Authenticate for directory reads", "detail": "Complete interactive authentication for your approved tenant. The process scope avoids persisting this session context beyond the PowerShell process. Follow your administrator’s consent process if prompted."}, {"action": "Get-MgContext", "purpose": "Verify tenant and granted scopes", "detail": "Check TenantId, Account and Scopes before running queries. Stop if the identity or tenant differs from your intended environment."}, {"action": "Get-MgUser -UserId 'user@example.com' -Property Id,DisplayName,UserPrincipalName,AccountEnabled", "purpose": "Read a specific user", "detail": "Replace the example UPN. Requesting AccountEnabled explicitly avoids relying on the default property set. An authorization error is not evidence that the account is missing."}, {"action": "Disconnect-MgGraph", "purpose": "End the Graph session", "detail": "Disconnect when the investigation is complete. Store only the minimum necessary findings; user identifiers and account states are organizational data."}], "interpretation": "The tenant ID and granted scopes determine what the command can read. A permission failure, a wrong tenant and a missing user have different meanings.", "verification": "Run the bounded lookup in the verified tenant, record only necessary fields and disconnect the session."}}, {"id": "microsoft-graph-query-and-paging-basics", "title": "Microsoft Graph query and paging basics", "product": "Microsoft Graph", "vendor": "Microsoft Graph", "category": "Identity & Microsoft 365", "description": "Find users with server-side filters and handle complete result sets.", "scope": "Graph PowerShell Microsoft.Graph.Users; delegated User.Read.All.", "prerequisites": "Connect using the connection guide, verify Get-MgContext and use a tenant where directory reading is authorized.", "source": "https://learn.microsoft.com/en-us/powershell/module/microsoft.graph.users/get-mguser", "sourceLabel": "Microsoft Graph official documentation", "rows": [["Get-MgContext", "Confirm query context"], ["Get-MgUser -Filter \"startsWith(displayName,'Alex')\" -Top 10", "Find a bounded set of matching users"], ["Get-MgUser -All -Property Id,DisplayName,UserPrincipalName", "Retrieve all result pages"], ["Get-MgUser -UserId 'user@example.com' -Property Id,AssignedLicenses", "Inspect assigned license identifiers"], ["Get-MgUser -Top 10", "Inspect a small first page"]], "walkthrough": ["Confirm the tenant and User.Read.All scope. The query examples below read user records and do not alter the directory.", "Replace Alex with a relevant prefix. The filter is sent to Graph; Top 10 deliberately limits the returned sample and is not a tenant-wide count.", "Use only when a full user inventory is needed. -All traverses pages and can take time in large tenants; protect the resulting personal data.", "Replace the UPN and inspect AssignedLicenses. SKU IDs need mapping to tenant license products; an assigned license alone does not establish service provisioning health.", "Use a small sample to confirm connectivity and access before a tenant-wide query. Do not treat a limited result as a complete count."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A directory export appears incomplete", "symptom": "An administrator compares a small Graph result with an expected full user inventory.", "steps": [{"action": "Get-MgContext", "purpose": "Confirm query context", "detail": "Confirm the tenant and User.Read.All scope. The query examples below read user records and do not alter the directory."}, {"action": "Get-MgUser -Filter \"startsWith(displayName,'Alex')\" -Top 10", "purpose": "Find a bounded set of matching users", "detail": "Replace Alex with a relevant prefix. The filter is sent to Graph; Top 10 deliberately limits the returned sample and is not a tenant-wide count."}, {"action": "Get-MgUser -All -Property Id,DisplayName,UserPrincipalName", "purpose": "Retrieve all result pages", "detail": "Use only when a full user inventory is needed. -All traverses pages and can take time in large tenants; protect the resulting personal data."}, {"action": "Get-MgUser -Top 10", "purpose": "Inspect a small first page", "detail": "Use a small sample to confirm connectivity and access before a tenant-wide query. Do not treat a limited result as a complete count."}], "interpretation": "A bounded Top result is a sample. Use paging with -All for a full authorized inventory, and compare the selected properties and tenant context.", "verification": "Repeat the bounded comparison and, if required, perform the full inventory under the approved data-handling procedure."}}, {"id": "entra-id-sign-in-investigation", "title": "Entra ID sign-in investigation", "product": "Entra ID", "vendor": "Entra ID", "category": "Identity & Microsoft 365", "description": "Review recent sign-ins and distinguish authentication from policy failures.", "scope": "Microsoft Entra admin center sign-in logs. Labels can vary by portal release.", "prerequisites": "Use at least an appropriate log-reading role such as Reports Reader. Available history and fields depend on licensing and retention.", "source": "https://learn.microsoft.com/en-us/entra/identity/monitoring-health/howto-analyze-activity-logs", "sourceLabel": "Entra ID official documentation", "rows": [["Entra ID → Monitoring & health → Sign-in logs", "Open sign-in activity"], ["Filter by user, date and status", "Isolate the reported attempt"], ["Open event → Basic info / Authentication details", "Read the authentication outcome"], ["Open event → Conditional Access", "Inspect applied policy results"], ["Sign-in event → Troubleshooting + support", "Review the event’s diagnostic context"]], "walkthrough": ["Select the affected tenant first. Limit the time window and user so you do not mistake unrelated background sign-ins for the reported attempt.", "Record the timestamp and time zone, application and correlation ID. Ask the user for the precise attempt time if multiple failures exist.", "Compare the failure reason with individual authentication steps. A successful first factor may still be followed by an MFA or policy failure.", "Inspect each evaluated policy and grant control. Report-only results do not enforce a block; do not disable policies as a diagnostic shortcut.", "Compare the presented error and correlation ID with the authentication steps and applied policies. Escalate with the timestamp and tenant context."], "kind": "Console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A user is blocked from signing in to one application", "symptom": "A sign-in failure occurs after a policy rollout.", "steps": [{"action": "Entra ID → Monitoring & health → Sign-in logs", "purpose": "Open sign-in activity", "detail": "Select the affected tenant first. Limit the time window and user so you do not mistake unrelated background sign-ins for the reported attempt."}, {"action": "Filter by user, date and status", "purpose": "Isolate the reported attempt", "detail": "Record the timestamp and time zone, application and correlation ID. Ask the user for the precise attempt time if multiple failures exist."}, {"action": "Open event → Basic info / Authentication details", "purpose": "Read the authentication outcome", "detail": "Compare the failure reason with individual authentication steps. A successful first factor may still be followed by an MFA or policy failure."}, {"action": "Open event → Conditional Access", "purpose": "Inspect applied policy results", "detail": "Inspect each evaluated policy and grant control. Report-only results do not enforce a block; do not disable policies as a diagnostic shortcut."}, {"action": "Sign-in event → Troubleshooting + support", "purpose": "Review the event’s diagnostic context", "detail": "Compare the presented error and correlation ID with the authentication steps and applied policies. Escalate with the timestamp and tenant context."}], "interpretation": "Compare the failure reason, authentication steps and conditional-access policy result. A report-only policy has no enforcement effect.", "verification": "Retest the same application with the user after an approved policy or identity correction and compare the new sign-in event."}}, {"id": "entra-id-devices-and-tenant-overview", "title": "Entra ID devices and tenant overview", "product": "Entra ID", "vendor": "Entra ID", "category": "Identity & Microsoft 365", "description": "Inspect tenant context, device identities and join state without changing access.", "scope": "Microsoft Entra admin center and Windows dsregcmd.", "prerequisites": "Use directory read access appropriate for the tenant. Run dsregcmd /status as the affected signed-in Windows user.", "source": "https://learn.microsoft.com/en-us/entra/identity/devices/troubleshoot-device-dsregcmd", "sourceLabel": "Entra ID official documentation", "rows": [["Entra ID → Overview", "Confirm tenant identity"], ["Entra ID → Devices → All devices", "Locate the device object"], ["dsregcmd /status", "Inspect the local registration state"], ["Review Device State and SSO State sections", "Compare identity and sign-in state"], ["dsregcmd /status → Diagnostic Data", "Review registration diagnostics on the device"]], "walkthrough": ["Record the tenant ID and primary domain. Multiple tenants in the same browser session can lead to inspecting a similarly named but unrelated directory.", "Search the device name and compare its device ID. Check enabled state, join type and last activity; duplicate names do not imply duplicate identities.", "On the Windows device, compare AzureAdJoined, DomainJoined, TenantId and DeviceId with the portal. The command reads local registration state and does not join or leave the tenant.", "Device join and a user’s primary refresh token are separate observations. Record AzureAdPrt in the user context; a device object existing in Entra does not prove healthy SSO.", "Record the diagnostic output in the relevant user context and compare the tenant and device identity with the portal record. Redact sensitive identifiers before sharing."], "kind": "Command / console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A joined laptop fails an SSO check", "symptom": "A user reports repeated prompts on a Windows device expected to be registered.", "steps": [{"action": "Entra ID → Overview", "purpose": "Confirm tenant identity", "detail": "Record the tenant ID and primary domain. Multiple tenants in the same browser session can lead to inspecting a similarly named but unrelated directory."}, {"action": "Entra ID → Devices → All devices", "purpose": "Locate the device object", "detail": "Search the device name and compare its device ID. Check enabled state, join type and last activity; duplicate names do not imply duplicate identities."}, {"action": "dsregcmd /status", "purpose": "Inspect the local registration state", "detail": "On the Windows device, compare AzureAdJoined, DomainJoined, TenantId and DeviceId with the portal. The command reads local registration state and does not join or leave the tenant."}, {"action": "Review Device State and SSO State sections", "purpose": "Compare identity and sign-in state", "detail": "Device join and a user’s primary refresh token are separate observations. Record AzureAdPrt in the user context; a device object existing in Entra does not prove healthy SSO."}, {"action": "dsregcmd /status → Diagnostic Data", "purpose": "Review registration diagnostics on the device", "detail": "Record the diagnostic output in the relevant user context and compare the tenant and device identity with the portal record. Redact sensitive identifiers before sharing."}], "interpretation": "Match device and tenant IDs between the local output and portal. Device join state and the user’s primary refresh token are separate observations.", "verification": "In the affected user session, repeat the local status check and verify the application sign-in after the underlying issue is addressed."}}, {"id": "exchange-online-mailbox-inspection", "title": "Exchange Online mailbox inspection", "product": "Exchange Online", "vendor": "Exchange Online", "category": "Identity & Microsoft 365", "description": "Connect to Exchange Online and review mailbox identity and quotas.", "scope": "ExchangeOnlineManagement module; Exchange Online PowerShell.", "prerequisites": "Use an approved Exchange Online account with the required RBAC read permissions. Replace user@example.com with the target mailbox.", "source": "https://learn.microsoft.com/en-us/powershell/module/exchange/get-exomailbox", "sourceLabel": "Exchange Online official documentation", "rows": [["Connect-ExchangeOnline", "Open an authenticated Exchange session"], ["Get-EXOMailbox -Identity 'user@example.com'", "Inspect mailbox identity"], ["Get-EXOMailbox -Identity 'user@example.com' -Properties IssueWarningQuota,ProhibitSendQuota", "Read mailbox quota settings"], ["Disconnect-ExchangeOnline -Confirm:$false", "Close the PowerShell session"], ["Get-EXOMailboxStatistics -Identity 'user@example.com'", "Inspect mailbox size and item count"]], "walkthrough": ["Complete interactive authentication using your approved admin identity. Verify you are connecting to the intended organization before inspecting recipients.", "Compare primary SMTP address and recipient type with the reported mailbox. A mail-enabled user and an Exchange Online mailbox are different recipient types.", "Request the non-default quota properties explicitly. Compare configured quotas with actual mailbox size before concluding that quota enforcement is causing the issue.", "End the session after capturing necessary findings. This disconnects the administrative session; it does not disconnect mailbox users.", "Replace the example address with the intended mailbox. Compare the returned size with the configured warning and send quotas; permissions and property availability vary."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A mailbox user cannot send messages", "symptom": "A user reports that sending is blocked and an administrator suspects mailbox quota.", "steps": [{"action": "Connect-ExchangeOnline", "purpose": "Open an authenticated Exchange session", "detail": "Complete interactive authentication using your approved admin identity. Verify you are connecting to the intended organization before inspecting recipients."}, {"action": "Get-EXOMailbox -Identity 'user@example.com'", "purpose": "Inspect mailbox identity", "detail": "Compare primary SMTP address and recipient type with the reported mailbox. A mail-enabled user and an Exchange Online mailbox are different recipient types."}, {"action": "Get-EXOMailbox -Identity 'user@example.com' -Properties IssueWarningQuota,ProhibitSendQuota", "purpose": "Read mailbox quota settings", "detail": "Request the non-default quota properties explicitly. Compare configured quotas with actual mailbox size before concluding that quota enforcement is causing the issue."}, {"action": "Get-EXOMailboxStatistics -Identity 'user@example.com'", "purpose": "Inspect mailbox size and item count", "detail": "Replace the example address with the intended mailbox. Compare the returned size with the configured warning and send quotas; permissions and property availability vary."}, {"action": "Disconnect-ExchangeOnline -Confirm:$false", "purpose": "Close the PowerShell session", "detail": "End the session after capturing necessary findings. This disconnects the administrative session; it does not disconnect mailbox users."}], "interpretation": "Compare mailbox identity, actual size and configured send quota. A send failure can have other causes, including account or transport restrictions.", "verification": "Verify the mailbox statistics and a user-generated test message after the approved correction; close the admin session."}}, {"id": "exchange-online-message-tracing", "title": "Exchange Online message tracing", "product": "Exchange Online", "vendor": "Exchange Online", "category": "Identity & Microsoft 365", "description": "Trace a recent sender and examine the events for a specific message.", "scope": "Exchange Online Get-MessageTraceV2; ExchangeOnlineManagement 3.7.0 or later.", "prerequisites": "Connect-ExchangeOnline first with message-trace RBAC rights. Substitute the example addresses. This example limits the query to the last 24 hours.", "source": "https://learn.microsoft.com/en-us/powershell/module/exchange/get-messagetracev2", "sourceLabel": "Exchange Online official documentation", "rows": [["$end = Get-Date\n$start = $end.AddHours(-24)", "Define a bounded search window"], ["Get-MessageTraceV2 -SenderAddress 'sender@example.com' -StartDate $start -EndDate $end", "Find messages from a sender"], ["Get-MessageTraceDetailV2 -MessageTraceId '<trace-guid>' -RecipientAddress 'recipient@example.com'", "Inspect events for one recipient"], ["Disconnect-ExchangeOnline -Confirm:$false", "End the investigation session"], ["Get-MessageTraceV2 -RecipientAddress 'recipient@example.com' -StartDate $start -EndDate $end", "Trace a recent recipient"]], "walkthrough": ["Use the reported delivery time and check time zones. V2 tracing supports up to 90 days of history, with at most a 10-day range per query; this example uses one day.", "Inspect recipient, received time, status and MessageTraceId. A bounded result set may need further filtering; do not infer that the first returned message is the reported one.", "Replace the trace GUID with MessageTraceId from the previous result. Review the event sequence and any policy or transport explanation for that exact recipient.", "Record only required trace identifiers and the disposition. A delivered transport status does not prove a person read the message or that a client displayed it.", "Replace the address and use the bounded time window from the walkthrough. Compare MessageTraceId and timestamps with the reported message."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A sender says a message never arrived", "symptom": "A recipient reports a missing message sent within the last day.", "steps": [{"action": "$end = Get-Date\n$start = $end.AddHours(-24)", "purpose": "Define a bounded search window", "detail": "Use the reported delivery time and check time zones. V2 tracing supports up to 90 days of history, with at most a 10-day range per query; this example uses one day."}, {"action": "Get-MessageTraceV2 -SenderAddress 'sender@example.com' -StartDate $start -EndDate $end", "purpose": "Find messages from a sender", "detail": "Inspect recipient, received time, status and MessageTraceId. A bounded result set may need further filtering; do not infer that the first returned message is the reported one."}, {"action": "Get-MessageTraceDetailV2 -MessageTraceId '<trace-guid>' -RecipientAddress 'recipient@example.com'", "purpose": "Inspect events for one recipient", "detail": "Replace the trace GUID with MessageTraceId from the previous result. Review the event sequence and any policy or transport explanation for that exact recipient."}, {"action": "Get-MessageTraceV2 -RecipientAddress 'recipient@example.com' -StartDate $start -EndDate $end", "purpose": "Trace a recent recipient", "detail": "Replace the address and use the bounded time window from the walkthrough. Compare MessageTraceId and timestamps with the reported message."}, {"action": "Disconnect-ExchangeOnline -Confirm:$false", "purpose": "End the investigation session", "detail": "Record only required trace identifiers and the disposition. A delivered transport status does not prove a person read the message or that a client displayed it."}], "interpretation": "Match the sender, recipient, time and trace ID; use the event details for the specific recipient. Transport delivery does not prove the message was read.", "verification": "Record the final trace disposition and verify the recipient’s experience, then disconnect from Exchange Online."}}, {"id": "azure-subscription-and-resource-inventory", "title": "Azure subscription and resource inventory", "product": "Azure", "vendor": "Azure", "category": "Cloud", "description": "Check CLI context and inventory resources in the intended subscription.", "scope": "Azure CLI 2.x with Azure Resource Manager read permissions.", "prerequisites": "Install Azure CLI through your approved process. Sign in to your authorized tenant. Reader access is sufficient for most inventory queries.", "source": "https://learn.microsoft.com/en-us/cli/azure/account", "sourceLabel": "Azure official documentation", "rows": [["az login", "Authenticate interactively"], ["az account show --output table", "Inspect active subscription"], ["az account list --output table", "List available subscriptions"], ["az resource list --output table", "Inventory current-subscription resources"], ["az group list --output table", "List resource groups in the active subscription"]], "walkthrough": ["Choose the intended tenant and account during sign-in. Authentication does not guarantee access to every subscription.", "Confirm tenant ID, subscription ID and account. Stop before resource queries if the active subscription is not the intended one.", "Use the subscription identifiers to distinguish similarly named environments. To switch intentionally, use az account set --subscription <subscription-id>; this changes local CLI context.", "Inspect resource type, name and resource group. An empty inventory may mean the wrong context or limited RBAC visibility rather than no deployed resources.", "Confirm the active subscription first, then compare resource-group names and locations with the deployment inventory. RBAC limits what is visible."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A resource is missing from an Azure inventory", "symptom": "An engineer expects to find a resource but the CLI output is empty.", "steps": [{"action": "az login", "purpose": "Authenticate interactively", "detail": "Choose the intended tenant and account during sign-in. Authentication does not guarantee access to every subscription."}, {"action": "az account show --output table", "purpose": "Inspect active subscription", "detail": "Confirm tenant ID, subscription ID and account. Stop before resource queries if the active subscription is not the intended one."}, {"action": "az account list --output table", "purpose": "List available subscriptions", "detail": "Use the subscription identifiers to distinguish similarly named environments. To switch intentionally, use az account set --subscription <subscription-id>; this changes local CLI context."}, {"action": "az group list --output table", "purpose": "List resource groups in the active subscription", "detail": "Confirm the active subscription first, then compare resource-group names and locations with the deployment inventory. RBAC limits what is visible."}, {"action": "az resource list --output table", "purpose": "Inventory current-subscription resources", "detail": "Inspect resource type, name and resource group. An empty inventory may mean the wrong context or limited RBAC visibility rather than no deployed resources."}], "interpretation": "Confirm the account, tenant and active subscription before interpreting an empty resource list. RBAC can hide resources even in the correct subscription.", "verification": "Repeat the inventory after selecting the authorized subscription and compare resource group and name with the deployment record."}}, {"id": "azure-virtual-network-inspection", "title": "Azure virtual network inspection", "product": "Azure", "vendor": "Azure", "category": "Cloud", "description": "Inspect virtual networks, subnets and security group inventory.", "scope": "Azure CLI 2.x; Azure networking resource read access.", "prerequisites": "Run az login and verify az account show. Replace rg-example and vnet-example with your resource names.", "source": "https://learn.microsoft.com/en-us/cli/azure/network/vnet", "sourceLabel": "Azure official documentation", "rows": [["az network vnet list --output table", "List virtual networks"], ["az network vnet subnet list --resource-group rg-example --vnet-name vnet-example --output table", "Inspect subnets"], ["az network nsg list --output table", "List network security groups"], ["az network route-table list --output table", "Inventory custom route tables"], ["az network vnet show --resource-group rg-example --name vnet-example --output json", "Inspect one virtual network"]], "walkthrough": ["Compare VNet address spaces and resource groups. Overlapping address spaces matter for peering and connectivity, even when each VNet works in isolation.", "Replace both resource names. Check subnet ranges and associations against your topology; the list alone does not establish that a VM is attached as expected.", "Identify NSGs in the subscription. Existence is not enforcement: inspect subnet and NIC associations and effective rules for the affected endpoint.", "Inspect route tables associated with the affected subnet. These resource definitions do not include all effective system or learned routes on a VM NIC.", "Replace the resource group and VNet name. Review address space and subnet references, then compare the output with the intended environment."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A VM cannot reach a private service", "symptom": "A workload in a VNet cannot connect to another private endpoint.", "steps": [{"action": "az network vnet list --output table", "purpose": "List virtual networks", "detail": "Compare VNet address spaces and resource groups. Overlapping address spaces matter for peering and connectivity, even when each VNet works in isolation."}, {"action": "az network vnet subnet list --resource-group rg-example --vnet-name vnet-example --output table", "purpose": "Inspect subnets", "detail": "Replace both resource names. Check subnet ranges and associations against your topology; the list alone does not establish that a VM is attached as expected."}, {"action": "az network nsg list --output table", "purpose": "List network security groups", "detail": "Identify NSGs in the subscription. Existence is not enforcement: inspect subnet and NIC associations and effective rules for the affected endpoint."}, {"action": "az network route-table list --output table", "purpose": "Inventory custom route tables", "detail": "Inspect route tables associated with the affected subnet. These resource definitions do not include all effective system or learned routes on a VM NIC."}, {"action": "az network vnet show --resource-group rg-example --name vnet-example --output json", "purpose": "Inspect one virtual network", "detail": "Replace the resource group and VNet name. Review address space and subnet references, then compare the output with the intended environment."}], "interpretation": "Compare address spaces, subnet associations, NSGs and route tables. Listed resources are not the same as effective NIC rules or effective routes.", "verification": "Use the provider’s effective-route and connectivity tools for the affected endpoint, then retest the specific service after the approved fix."}}, {"id": "sophos-firewall-cli-health-checks", "title": "Sophos Firewall CLI health checks", "product": "Sophos", "vendor": "Sophos", "category": "Cybersecurity", "description": "Gather appliance version, uptime and resource diagnostics in Device Console.", "scope": "Sophos Firewall SFOS Device Console, diagnostics syntax documented for 23.0. Not Sophos UTM or Advanced Shell.", "prerequisites": "Connect through approved console or SSH access and select Device Console. Confirm command availability with built-in help for your SFOS release.", "source": "https://docs.sophos.com/nsg/sophos-firewall/23.0/Help/en-us/webhelp/onlinehelp/CommandLineHelp/DeviceConsole/SystemCommands/Diagnostics/index.html", "sourceLabel": "Sophos official documentation", "rows": [["system diagnostics show version-info", "Identify appliance and firmware"], ["system diagnostics show uptime", "Read system uptime"], ["system diagnostics show memory", "Inspect memory diagnostics"], ["system diagnostics show disk", "Inspect disk diagnostics"], ["system diagnostics show cpu", "Inspect CPU diagnostics"]], "walkthrough": ["Record the model, serial and firmware build. In an HA investigation compare both members before considering version-related behavior.", "Compare uptime with reported interruption times. Uptime is a clue about a restart; it does not explain why a restart happened.", "Capture the current memory picture and compare with a baseline for the same appliance. A single reading is insufficient to identify a leak.", "Review storage figures and errors alongside logs. Do not remove files from Advanced Shell based only on a utilization reading.", "Compare the current reading with the same appliance’s baseline and time of the reported issue. A single sample does not establish sustained load."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A firewall seems slow at peak time", "symptom": "An administrator sees intermittent delays and needs a baseline from the Device Console.", "steps": [{"action": "system diagnostics show version-info", "purpose": "Identify appliance and firmware", "detail": "Record the model, serial and firmware build. In an HA investigation compare both members before considering version-related behavior."}, {"action": "system diagnostics show uptime", "purpose": "Read system uptime", "detail": "Compare uptime with reported interruption times. Uptime is a clue about a restart; it does not explain why a restart happened."}, {"action": "system diagnostics show cpu", "purpose": "Inspect CPU diagnostics", "detail": "Compare the current reading with the same appliance’s baseline and time of the reported issue. A single sample does not establish sustained load."}, {"action": "system diagnostics show memory", "purpose": "Inspect memory diagnostics", "detail": "Capture the current memory picture and compare with a baseline for the same appliance. A single reading is insufficient to identify a leak."}, {"action": "system diagnostics show disk", "purpose": "Inspect disk diagnostics", "detail": "Review storage figures and errors alongside logs. Do not remove files from Advanced Shell based only on a utilization reading."}], "interpretation": "Record firmware, uptime, CPU, memory and disk around the symptom. A single reading cannot prove a memory leak or a restart cause.", "verification": "Collect a second timed sample and correlate with the relevant event logs before proposing changes."}}, {"id": "sophos-firewall-traffic-investigation", "title": "Sophos Firewall traffic investigation", "product": "Sophos", "vendor": "Sophos", "category": "Cybersecurity", "description": "Use log filters to connect a connection failure with firewall decisions.", "scope": "Sophos Firewall SFOS web admin console; labels vary by version.", "prerequisites": "Use a read-capable administrator account and a known source, destination and incident time. Availability of traffic records depends on rule logging.", "source": "https://docs.sophos.com/nsg/sophos-firewall/21.5/Help/en-us/webhelp/onlinehelp/AdministratorHelp/Logs/", "sourceLabel": "Sophos official documentation", "rows": [["Log viewer → Firewall", "Open firewall traffic logs"], ["Filter source IP, destination IP and destination port", "Isolate a traffic flow"], ["Inspect action, rule ID and reason", "Read the firewall decision"], ["Compare with VPN and system events", "Correlate adjacent failures"], ["Log viewer → filter by rule ID", "Review events for the matching firewall rule"]], "walkthrough": ["Set the time window for the reported failure. Confirm that the relevant firewall rule is configured to log traffic before treating an empty log as evidence of no traffic.", "Use the translated and original addresses as appropriate to the scenario. Match the exact protocol and port; ping is not a substitute for an application flow.", "Record the matching rule and drop reason. An allow record shows a policy decision at this device, not successful application authentication or the return route.", "If the destination is across a VPN, compare tunnel events and route state at the same timestamp. Preserve findings before proposing a scoped change.", "After identifying the rule from a traffic event, narrow the time window and compare source, destination and actions. Missing records can reflect logging settings."], "kind": "Console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A new application flow is blocked", "symptom": "A client cannot reach an application through Sophos Firewall after a rule change.", "steps": [{"action": "Log viewer → Firewall", "purpose": "Open firewall traffic logs", "detail": "Set the time window for the reported failure. Confirm that the relevant firewall rule is configured to log traffic before treating an empty log as evidence of no traffic."}, {"action": "Filter source IP, destination IP and destination port", "purpose": "Isolate a traffic flow", "detail": "Use the translated and original addresses as appropriate to the scenario. Match the exact protocol and port; ping is not a substitute for an application flow."}, {"action": "Inspect action, rule ID and reason", "purpose": "Read the firewall decision", "detail": "Record the matching rule and drop reason. An allow record shows a policy decision at this device, not successful application authentication or the return route."}, {"action": "Log viewer → filter by rule ID", "purpose": "Review events for the matching firewall rule", "detail": "After identifying the rule from a traffic event, narrow the time window and compare source, destination and actions. Missing records can reflect logging settings."}, {"action": "Compare with VPN and system events", "purpose": "Correlate adjacent failures", "detail": "If the destination is across a VPN, compare tunnel events and route state at the same timestamp. Preserve findings before proposing a scoped change."}], "interpretation": "A matching drop event and rule ID identify where to investigate. No event may mean logging was not enabled or the filter does not match the original or translated flow.", "verification": "Retest the same source, destination and port after an approved change and compare the corresponding log event."}}, {"id": "juniper-junos-cli-essentials", "title": "Juniper Junos CLI essentials", "product": "Juniper", "vendor": "Juniper", "category": "Networking", "description": "Get oriented in Junos operational mode and inspect the chassis.", "scope": "Junos OS operational mode, prompt ending in >. Output differs by platform.", "prerequisites": "Use an authorized read-only operational login. These show commands do not require entering configuration mode.", "source": "https://www.juniper.net/documentation/us/en/software/junos/cli-reference/index.html", "sourceLabel": "Juniper official documentation", "rows": [["show version", "Identify software and model"], ["show interfaces terse", "Inspect interface summary"], ["show chassis hardware", "Inspect hardware inventory"], ["show chassis alarms", "Read active chassis alarms"], ["show system uptime", "Inspect boot and system timing"]], "walkthrough": ["Record the Junos release and hardware model. Consult the command reference for that release before applying examples from another Juniper platform.", "Compare Admin and Link separately, then inspect protocol addresses on logical interfaces. Physical link up does not prove Layer 3 adjacency.", "Match installed modules and transceivers with the cabling plan. Empty or absent slots can be intentional; compare against expected inventory.", "Capture alarm severity, description and timestamp. Use model-specific guidance to distinguish environmental faults from expected conditions.", "Compare boot time and current system time with the incident. On supported Junos platforms this also provides useful timing context for recent configuration activity."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A Junos device becomes unreachable after maintenance", "symptom": "A monitoring system reports that a Juniper device is offline after planned work.", "steps": [{"action": "show version", "purpose": "Identify software and model", "detail": "Record the Junos release and hardware model. Consult the command reference for that release before applying examples from another Juniper platform."}, {"action": "show system uptime", "purpose": "Inspect boot and system timing", "detail": "Compare boot time and current system time with the incident. On supported Junos platforms this also provides useful timing context for recent configuration activity."}, {"action": "show interfaces terse", "purpose": "Inspect interface summary", "detail": "Compare Admin and Link separately, then inspect protocol addresses on logical interfaces. Physical link up does not prove Layer 3 adjacency."}, {"action": "show chassis hardware", "purpose": "Inspect hardware inventory", "detail": "Match installed modules and transceivers with the cabling plan. Empty or absent slots can be intentional; compare against expected inventory."}, {"action": "show chassis alarms", "purpose": "Read active chassis alarms", "detail": "Capture alarm severity, description and timestamp. Use model-specific guidance to distinguish environmental faults from expected conditions."}], "interpretation": "Compare software and uptime with the maintenance window, interface admin/link state and chassis alarms. A recent boot does not establish why it happened.", "verification": "Verify the management interface and monitoring from the authorized network and retain relevant alarm details."}}, {"id": "juniper-routes-and-neighbor-checks", "title": "Juniper routes and neighbor checks", "product": "Juniper", "vendor": "Juniper", "category": "Networking", "description": "Inspect routes, ARP entries and discovered neighbors in Junos.", "scope": "Junos operational mode; LLDP and routing-instance behavior depend on configuration.", "prerequisites": "Use an operational read account. Confirm whether the workload uses the default routing table or a separate routing instance.", "source": "https://www.juniper.net/documentation/us/en/software/junos/cli-reference/index.html", "sourceLabel": "Juniper official documentation", "rows": [["show route", "Inspect the routing table"], ["show arp no-resolve", "Inspect IPv4 neighbor mappings"], ["show lldp neighbors", "Read adjacent device information"], ["show interfaces extensive", "Inspect detailed interface counters"], ["show route summary", "Summarize route-table state"]], "walkthrough": ["Identify the active route marker, protocol and next hop. For non-default routing instances, inspect the correct table rather than assuming the global table applies.", "Compare learned neighbors with directly attached subnets. no-resolve avoids DNS name lookup and keeps the output focused on addresses.", "Map local and remote ports to the cabling plan. Empty output can mean LLDP is disabled or unsupported on either endpoint.", "Focus on the affected interface and compare error trends over time. This broad command can produce large output; use an interface-specific form after locating the port.", "Review table and protocol counts as a baseline. A summary cannot replace checking the exact prefix and selected next hop in the relevant routing instance."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A Junos router cannot reach an adjacent network", "symptom": "A remote prefix is unavailable from a Junos device.", "steps": [{"action": "show route", "purpose": "Inspect the routing table", "detail": "Identify the active route marker, protocol and next hop. For non-default routing instances, inspect the correct table rather than assuming the global table applies."}, {"action": "show route summary", "purpose": "Summarize route-table state", "detail": "Review table and protocol counts as a baseline. A summary cannot replace checking the exact prefix and selected next hop in the relevant routing instance."}, {"action": "show arp no-resolve", "purpose": "Inspect IPv4 neighbor mappings", "detail": "Compare learned neighbors with directly attached subnets. no-resolve avoids DNS name lookup and keeps the output focused on addresses."}, {"action": "show lldp neighbors", "purpose": "Read adjacent device information", "detail": "Map local and remote ports to the cabling plan. Empty output can mean LLDP is disabled or unsupported on either endpoint."}, {"action": "show interfaces extensive", "purpose": "Inspect detailed interface counters", "detail": "Focus on the affected interface and compare error trends over time. This broad command can produce large output; use an interface-specific form after locating the port."}], "interpretation": "Check the correct routing instance and active next hop, then compare neighbor resolution and physical interface state. LLDP absence alone is not a link test.", "verification": "Repeat the route and neighbor checks and retest the authorized destination after the underlying link or route issue is fixed."}}, {"id": "ubiquiti-unifi-device-connectivity", "title": "Ubiquiti UniFi device connectivity", "product": "Ubiquiti", "vendor": "Ubiquiti", "category": "Networking", "description": "Follow adoption and management connectivity through the UniFi console.", "scope": "UniFi Network application; excludes EdgeOS and airMAX CLI.", "prerequisites": "Use access to the correct UniFi site. Menu labels depend on the Network release. Avoid readopting or resetting devices while collecting evidence.", "source": "https://help.ui.com/hc/en-us/articles/7258465146519-Troubleshooting-UniFi-Device-Connectivity", "sourceLabel": "Ubiquiti official documentation", "rows": [["UniFi Network → Devices", "Locate the affected device"], ["Device details → IP address and uplink", "Inspect the management path"], ["Upstream switch → Ports → Port Manager", "Review VLAN and link settings"], ["Check console reachability and required ports", "Validate the management dependency"], ["UniFi Network → Settings → Networks", "Review the management network"]], "walkthrough": ["Confirm the site, MAC address, model and displayed status. An offline device may still be forwarding traffic while its management path is unavailable.", "Compare management IP, VLAN and upstream port with the intended topology. An APIPA address indicates that the device did not obtain the expected DHCP address.", "Compare native and tagged networks on the uplink with the management VLAN. Inspect settings without applying a new port profile during diagnosis.", "Use the official UniFi required-ports reference for your deployment. Test only relevant paths; do not broadly open inter-VLAN traffic to make adoption work.", "Compare the management network and VLAN with the upstream switch-port settings. Menu names can vary by Network version; inspect before making changes."], "kind": "Console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A UniFi access point appears offline", "symptom": "An access point forwards inconsistently and the UniFi console shows it offline.", "steps": [{"action": "UniFi Network → Devices", "purpose": "Locate the affected device", "detail": "Confirm the site, MAC address, model and displayed status. An offline device may still be forwarding traffic while its management path is unavailable."}, {"action": "Device details → IP address and uplink", "purpose": "Inspect the management path", "detail": "Compare management IP, VLAN and upstream port with the intended topology. An APIPA address indicates that the device did not obtain the expected DHCP address."}, {"action": "Upstream switch → Ports → Port Manager", "purpose": "Review VLAN and link settings", "detail": "Compare native and tagged networks on the uplink with the management VLAN. Inspect settings without applying a new port profile during diagnosis."}, {"action": "UniFi Network → Settings → Networks", "purpose": "Review the management network", "detail": "Compare the management network and VLAN with the upstream switch-port settings. Menu names can vary by Network version; inspect before making changes."}, {"action": "Check console reachability and required ports", "purpose": "Validate the management dependency", "detail": "Use the official UniFi required-ports reference for your deployment. Test only relevant paths; do not broadly open inter-VLAN traffic to make adoption work."}], "interpretation": "An unexpected or missing management address points toward DHCP or VLAN configuration; an expected address with an offline status calls for management-path checks.", "verification": "After the approved network correction, verify the device is online and reachable without resetting or readopting it unnecessarily."}}, {"id": "ubiquiti-unifi-switch-port-checks", "title": "Ubiquiti UniFi switch port checks", "product": "Ubiquiti", "vendor": "Ubiquiti", "category": "Networking", "description": "Inspect switch port state, VLAN assignment and PoE budget.", "scope": "UniFi Network managed switches; port capabilities vary by model.", "prerequisites": "Use an authorized UniFi Network administrator with visibility into the correct site. Record the device and port before inspecting settings.", "source": "https://help.ui.com/hc/en-us/articles/33402927617047-UniFi-Switch-Settings", "sourceLabel": "Ubiquiti official documentation", "rows": [["Devices → Switch → Ports → Port Manager", "Find the physical port"], ["Inspect link state and negotiated speed", "Check the physical link"], ["Review native VLAN and tagged VLAN management", "Check network assignment"], ["Review PoE state and device power budget", "Check power delivery"], ["Devices → Switch → Overview", "Review switch health and uplink"]], "walkthrough": ["Match the connected endpoint and port number with your cabling map. Do not rely solely on a remembered client name or stale discovery entry.", "Compare the negotiated rate with both endpoint capabilities. A lower rate can reflect cable faults, negotiation or a legitimate endpoint limitation.", "Verify the untagged network and allowed tagged networks against the endpoint role. An access device and an AP carrying multiple SSIDs need different VLAN behavior.", "For PoE-capable models, compare endpoint demand and remaining switch budget. Do not power-cycle a production endpoint merely to see whether it recovers.", "Compare the uplink, device status and recent health indicators with the affected port. A healthy switch overview does not rule out a single-port or endpoint issue."], "kind": "Console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A powered access point does not come online", "symptom": "A UniFi switch port should provide both network access and power to an access point.", "steps": [{"action": "Devices → Switch → Ports → Port Manager", "purpose": "Find the physical port", "detail": "Match the connected endpoint and port number with your cabling map. Do not rely solely on a remembered client name or stale discovery entry."}, {"action": "Inspect link state and negotiated speed", "purpose": "Check the physical link", "detail": "Compare the negotiated rate with both endpoint capabilities. A lower rate can reflect cable faults, negotiation or a legitimate endpoint limitation."}, {"action": "Review native VLAN and tagged VLAN management", "purpose": "Check network assignment", "detail": "Verify the untagged network and allowed tagged networks against the endpoint role. An access device and an AP carrying multiple SSIDs need different VLAN behavior."}, {"action": "Review PoE state and device power budget", "purpose": "Check power delivery", "detail": "For PoE-capable models, compare endpoint demand and remaining switch budget. Do not power-cycle a production endpoint merely to see whether it recovers."}, {"action": "Devices → Switch → Overview", "purpose": "Review switch health and uplink", "detail": "Compare the uplink, device status and recent health indicators with the affected port. A healthy switch overview does not rule out a single-port or endpoint issue."}], "interpretation": "Separate link negotiation, VLAN assignment and available PoE budget. A live link does not by itself prove the management VLAN or power budget is correct.", "verification": "Confirm power and link stability, the intended VLANs and the endpoint status after the approved repair."}}, {"id": "hpe-proliant-ilo-health-overview", "title": "HPE ProLiant iLO health overview", "product": "HPE", "vendor": "HPE", "category": "Infrastructure", "description": "Read ProLiant health and hardware events through iLO.", "scope": "HPE iLO 6 web interface on supported ProLiant servers; menus differ for iLO 4/5/7.", "prerequisites": "Use an iLO account with view permissions on the management network. Match the server serial number before investigating.", "source": "https://support.hpe.com/hpesc/public/docDisplay?docId=sd00002007en_us", "sourceLabel": "HPE official documentation", "rows": [["Information → Overview", "Confirm server identity and health"], ["Information → Integrated Management Log", "Inspect hardware events"], ["System Information → Fans / Temperatures", "Inspect cooling status"], ["System Information → Power", "Inspect power redundancy"], ["Information → iLO Event Log", "Review management-controller events"]], "walkthrough": ["Compare product name, serial number, power state and overall health with the asset record. Information for a powered-off server may reflect its last powered-on state.", "Read event severity and timestamps around the incident. Do not clear the IML before preserving the events needed for support.", "Compare failed sensors and thermal readings with the server-specific limits. Fan speed alone does not identify the failing component.", "Check power supply presence and status against the intended redundancy configuration. A disconnected redundant feed should be investigated before any physical maintenance.", "Compare iLO events with the Integrated Management Log and the incident time. Preserve logs before replacing components or clearing entries."], "kind": "Console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A ProLiant server reports degraded health", "symptom": "An operations dashboard reports degraded hardware health on a server.", "steps": [{"action": "Information → Overview", "purpose": "Confirm server identity and health", "detail": "Compare product name, serial number, power state and overall health with the asset record. Information for a powered-off server may reflect its last powered-on state."}, {"action": "Information → Integrated Management Log", "purpose": "Inspect hardware events", "detail": "Read event severity and timestamps around the incident. Do not clear the IML before preserving the events needed for support."}, {"action": "System Information → Fans / Temperatures", "purpose": "Inspect cooling status", "detail": "Compare failed sensors and thermal readings with the server-specific limits. Fan speed alone does not identify the failing component."}, {"action": "System Information → Power", "purpose": "Inspect power redundancy", "detail": "Check power supply presence and status against the intended redundancy configuration. A disconnected redundant feed should be investigated before any physical maintenance."}, {"action": "Information → iLO Event Log", "purpose": "Review management-controller events", "detail": "Compare iLO events with the Integrated Management Log and the incident time. Preserve logs before replacing components or clearing entries."}], "interpretation": "Match the serial number first, then correlate health, management events, temperature, fan and power observations. Preserve logs before replacing parts.", "verification": "Confirm the affected component and health state after authorized maintenance and retain relevant events for support."}}, {"id": "hpe-aruba-cx-switching-essentials", "title": "HPE Aruba CX switching essentials", "product": "HPE", "vendor": "HPE", "category": "Networking", "description": "Inspect AOS-CX switch interfaces and VLANs with platform-specific commands.", "scope": "HPE Aruba Networking AOS-CX 10.13. Not Comware or ArubaOS-Switch.", "prerequisites": "Use a switch account permitted to run show commands. Port naming and command availability depend on the CX model.", "source": "https://arubanetworking.hpe.com/techdocs/AOS-CX/10.13/PDF/monitoring_8400.pdf", "sourceLabel": "HPE official documentation", "rows": [["show version", "Identify the CX software release"], ["show interface brief", "Inspect interface summary"], ["show vlan", "Inspect configured VLANs"], ["show lldp neighbor-info", "Inspect discovered neighbors"], ["show system", "Inspect switch system information"]], "walkthrough": ["Confirm that the device runs AOS-CX. Do not reuse these commands unmodified on Comware or AOS-S switches.", "Use the displayed interface names to find the uplink or endpoint port. Compare administrative state, link state and speed with expected operation.", "Compare VLAN IDs and membership with both ends of each trunk. A VLAN being defined does not prove that it is carried on the affected link.", "Map local ports to remote devices and ports. LLDP requires compatible configuration on the peer, so absent discovery is not itself proof of a broken link.", "Record the system identity and compare the hardware and software context with the intended switch. Command output varies with AOS-CX platform and release."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "An Aruba CX switch port is up but the endpoint is isolated", "symptom": "A device connects physically but cannot reach its expected VLAN.", "steps": [{"action": "show version", "purpose": "Identify the CX software release", "detail": "Confirm that the device runs AOS-CX. Do not reuse these commands unmodified on Comware or AOS-S switches."}, {"action": "show interface brief", "purpose": "Inspect interface summary", "detail": "Use the displayed interface names to find the uplink or endpoint port. Compare administrative state, link state and speed with expected operation."}, {"action": "show vlan", "purpose": "Inspect configured VLANs", "detail": "Compare VLAN IDs and membership with both ends of each trunk. A VLAN being defined does not prove that it is carried on the affected link."}, {"action": "show lldp neighbor-info", "purpose": "Inspect discovered neighbors", "detail": "Map local ports to remote devices and ports. LLDP requires compatible configuration on the peer, so absent discovery is not itself proof of a broken link."}, {"action": "show system", "purpose": "Inspect switch system information", "detail": "Record the system identity and compare the hardware and software context with the intended switch. Command output varies with AOS-CX platform and release."}], "interpretation": "Confirm AOS-CX and inspect the port, VLAN membership and neighbor path. A VLAN existing on the switch does not prove it is carried across the uplink.", "verification": "Verify port and VLAN state at both ends and retest the endpoint after the approved change."}}, {"id": "dell-poweredge-idrac-health-checks", "title": "Dell PowerEdge iDRAC health checks", "product": "Dell", "vendor": "Dell", "category": "Infrastructure", "description": "Read PowerEdge identity, power state and hardware event history.", "scope": "iDRAC9 RACADM. Examples use local RACADM installed on the managed host.", "prerequisites": "Use an approved Dell RACADM installation with appropriate privileges. Remote RACADM connection options differ; never place passwords into shared command history.", "source": "https://downloads.dell.com/topicspdf/idrac_v4-22_cliguide_en-us.pdf", "sourceLabel": "Dell official documentation", "rows": [["racadm getsysinfo", "Inspect server and iDRAC identity"], ["racadm serveraction powerstatus", "Read server power state"], ["racadm getsel", "Read the System Event Log"], ["racadm lclog view", "Read Lifecycle Controller events"], ["racadm getversion", "Read controller firmware version"]], "walkthrough": ["Compare the service tag, model and management information with the asset under investigation. This helps prevent collecting results from the wrong host.", "The powerstatus action only reads the state. Do not substitute powercycle, hardreset or powerdown while diagnosing an active production host.", "Correlate hardware faults with the reported interruption and verify timestamps. Preserve SEL entries before any log clearing or component replacement.", "Compare configuration and lifecycle events with the incident timeline. A recent maintenance event can explain a hardware or firmware inventory change.", "Compare the controller firmware with the approved server baseline and support information. Version inspection does not apply an update."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A PowerEdge server unexpectedly went offline", "symptom": "A system owner asks whether a hardware event preceded an outage.", "steps": [{"action": "racadm getsysinfo", "purpose": "Inspect server and iDRAC identity", "detail": "Compare the service tag, model and management information with the asset under investigation. This helps prevent collecting results from the wrong host."}, {"action": "racadm serveraction powerstatus", "purpose": "Read server power state", "detail": "The powerstatus action only reads the state. Do not substitute powercycle, hardreset or powerdown while diagnosing an active production host."}, {"action": "racadm getsel", "purpose": "Read the System Event Log", "detail": "Correlate hardware faults with the reported interruption and verify timestamps. Preserve SEL entries before any log clearing or component replacement."}, {"action": "racadm lclog view", "purpose": "Read Lifecycle Controller events", "detail": "Compare configuration and lifecycle events with the incident timeline. A recent maintenance event can explain a hardware or firmware inventory change."}, {"action": "racadm getversion", "purpose": "Read controller firmware version", "detail": "Compare the controller firmware with the approved server baseline and support information. Version inspection does not apply an update."}], "interpretation": "Match the service tag, power status, system events and lifecycle events to the incident time. Reading power status is different from issuing a power action.", "verification": "Preserve the event history and verify system health after approved maintenance; do not reset a running host as a first diagnostic step."}}, {"id": "dell-poweredge-hardware-inventory", "title": "Dell PowerEdge hardware inventory", "product": "Dell", "vendor": "Dell", "category": "Infrastructure", "description": "Capture firmware and hardware inventory before planning maintenance.", "scope": "iDRAC9 local RACADM; inventory detail depends on platform and collection state.", "prerequisites": "Use an authorized local RACADM session with inventory read permissions. These commands do not schedule firmware updates.", "source": "https://downloads.dell.com/topicspdf/idrac_v4-22_cliguide_en-us.pdf", "sourceLabel": "Dell official documentation", "rows": [["racadm getsysinfo", "Identify the system"], ["racadm getversion", "Read firmware versions"], ["racadm hwinventory", "Inspect component inventory"], ["racadm jobqueue view", "Inspect queued management jobs"], ["racadm getsel", "Inspect hardware event records"]], "walkthrough": ["Record the service tag and model so that any subsequent support lookup uses the correct hardware family.", "Compare reported firmware versions with your approved baseline. Do not assume that every component shares the same release version.", "Review NIC, storage controller and other component identifiers. Inventory may reflect the most recent collection; compare with lifecycle events after hardware changes.", "Check whether existing jobs are pending before proposing maintenance. Viewing the queue does not cancel jobs or restart the host.", "Compare component inventory with recent hardware events and the maintenance timeline. Preserve event records for troubleshooting before clearing logs."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A server maintenance plan needs a reliable inventory", "symptom": "An administrator must compare firmware and hardware before a scheduled change.", "steps": [{"action": "racadm getsysinfo", "purpose": "Identify the system", "detail": "Record the service tag and model so that any subsequent support lookup uses the correct hardware family."}, {"action": "racadm getversion", "purpose": "Read firmware versions", "detail": "Compare reported firmware versions with your approved baseline. Do not assume that every component shares the same release version."}, {"action": "racadm hwinventory", "purpose": "Inspect component inventory", "detail": "Review NIC, storage controller and other component identifiers. Inventory may reflect the most recent collection; compare with lifecycle events after hardware changes."}, {"action": "racadm getsel", "purpose": "Inspect hardware event records", "detail": "Compare component inventory with recent hardware events and the maintenance timeline. Preserve event records for troubleshooting before clearing logs."}, {"action": "racadm jobqueue view", "purpose": "Inspect queued management jobs", "detail": "Check whether existing jobs are pending before proposing maintenance. Viewing the queue does not cancel jobs or restart the host."}], "interpretation": "Confirm the service tag, versions and inventory, then check hardware events and any queued jobs. An old inventory may not yet reflect a recent component change.", "verification": "Compare the results with the approved baseline and confirm job state before scheduling any update."}}, {"id": "dell-data-domain-capacity-and-health", "title": "Dell Data Domain capacity and health", "product": "Dell Data Domain", "vendor": "Dell Data Domain", "category": "Infrastructure", "description": "Inspect filesystem state, capacity and active protection-appliance alerts.", "scope": "Dell Data Domain / PowerProtect DD, DD OS CLI. Verify syntax for your installed DD OS version.", "prerequisites": "Use an authorized DD management account with read privileges. Preserve alerts and do not run clean, destroy or storage changes from a quick reference.", "source": "https://www.delltechnologies.com/asset/en-us/products/data-protection/technical-support/docu91804.pdf", "sourceLabel": "Dell Data Domain official documentation", "rows": [["system show version", "Identify DD OS release"], ["filesys status", "Inspect filesystem availability"], ["filesys show space", "Inspect physical and logical space"], ["alerts show current", "Read active appliance alerts"], ["replication status", "Inspect replication context state"]], "walkthrough": ["Record the system software version and consult the matching command reference. Appliance capabilities and output fields vary between DD OS releases.", "Confirm the filesystem is running before treating a backup error as a client-only problem. A running state does not establish that capacity and integration are healthy.", "Distinguish pre-compression data from post-compression storage and available physical space. Deduplication ratios alone do not indicate usable headroom.", "Capture alert IDs and severity alongside the time of the backup failure. Investigate capacity, hardware and environmental alerts through the matching vendor runbook.", "Compare the enabled state and last synchronization for the expected destination. An idle connection may be normal when there is no new data to replicate."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "Backups fail against a Data Domain appliance", "symptom": "A backup job reports errors and the storage team needs the appliance baseline.", "steps": [{"action": "system show version", "purpose": "Identify DD OS release", "detail": "Record the system software version and consult the matching command reference. Appliance capabilities and output fields vary between DD OS releases."}, {"action": "filesys status", "purpose": "Inspect filesystem availability", "detail": "Confirm the filesystem is running before treating a backup error as a client-only problem. A running state does not establish that capacity and integration are healthy."}, {"action": "filesys show space", "purpose": "Inspect physical and logical space", "detail": "Distinguish pre-compression data from post-compression storage and available physical space. Deduplication ratios alone do not indicate usable headroom."}, {"action": "alerts show current", "purpose": "Read active appliance alerts", "detail": "Capture alert IDs and severity alongside the time of the backup failure. Investigate capacity, hardware and environmental alerts through the matching vendor runbook."}, {"action": "replication status", "purpose": "Inspect replication context state", "detail": "Compare the enabled state and last synchronization for the expected destination. An idle connection may be normal when there is no new data to replicate."}], "interpretation": "Check DD OS version, filesystem state, physical capacity and current alerts; then inspect relevant replication state. A running filesystem does not guarantee free capacity.", "verification": "Retest a scoped backup after the underlying issue is addressed and confirm capacity and alerts remain healthy."}}, {"id": "dell-data-domain-replication-checks", "title": "Dell Data Domain replication checks", "product": "Dell Data Domain", "vendor": "Dell Data Domain", "category": "Infrastructure", "description": "Inspect replication contexts and distinguish idle replication from a stalled copy.", "scope": "DD OS replication CLI; context type and supported metrics vary by release.", "prerequisites": "Use authorized read access to the source and destination. Identify the replication context and expected schedule before judging lag.", "source": "https://www.dell.com/support/kbdoc/en-us/000043349/72419-replication-status", "sourceLabel": "Dell Data Domain official documentation", "rows": [["replication show config", "Identify configured replication contexts"], ["replication status", "Inspect replication state"], ["replication show performance rctx://<context-number>", "Read context throughput"], ["alerts show current", "Correlate replication with active alerts"], ["filesys status", "Check the filesystem during replication diagnosis"]], "walkthrough": ["Match the source and destination paths to the protected workload. Configuration alone does not prove an active or healthy transfer.", "Check the intended context and compare state with expected activity. An idle context can be healthy when there is no new data to transfer.", "Replace the placeholder with a real context number from the configuration. Compare repeated samples with the source workload; a single zero sample is not proof of failure.", "Check both systems for capacity and connectivity-related alerts. Document the context, observed state and incident time before escalating.", "A replication issue can accompany a filesystem or capacity problem. Inspect both systems and correlate their state with active alerts."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "A replication destination looks behind", "symptom": "A protection team notices that the expected replication destination has not updated.", "steps": [{"action": "replication show config", "purpose": "Identify configured replication contexts", "detail": "Match the source and destination paths to the protected workload. Configuration alone does not prove an active or healthy transfer."}, {"action": "replication status", "purpose": "Inspect replication state", "detail": "Check the intended context and compare state with expected activity. An idle context can be healthy when there is no new data to transfer."}, {"action": "replication show performance rctx://<context-number>", "purpose": "Read context throughput", "detail": "Replace the placeholder with a real context number from the configuration. Compare repeated samples with the source workload; a single zero sample is not proof of failure."}, {"action": "alerts show current", "purpose": "Correlate replication with active alerts", "detail": "Check both systems for capacity and connectivity-related alerts. Document the context, observed state and incident time before escalating."}, {"action": "filesys status", "purpose": "Check the filesystem during replication diagnosis", "detail": "A replication issue can accompany a filesystem or capacity problem. Inspect both systems and correlate their state with active alerts."}], "interpretation": "Match the context and last synchronization with the expected schedule. An idle context may be normal without new data; compare repeated throughput samples and alerts.", "verification": "Confirm the relevant context completes a new synchronization and document the observed time and status."}}, {"id": "kali-nmap-discovery-essentials", "title": "Kali Nmap discovery essentials", "product": "Kali Linux", "vendor": "Kali Linux", "category": "Cybersecurity", "description": "Discover a lab host’s exposed TCP services and interpret scan states.", "scope": "Kali Linux with Nmap 7.x. Examples use one explicitly authorized lab host.", "prerequisites": "Replace <lab-ip> with the address of a system you own or have permission to assess. These commands send network probes; agree on scope before scanning.", "source": "https://nmap.org/book/man.html", "sourceLabel": "Kali Linux official documentation", "rows": [["nmap --version", "Check the installed scanner version"], ["nmap -sn <lab-ip>", "Check host discovery responses"], ["nmap -sT -p 22,80,443 <lab-ip>", "Inspect three selected TCP ports"], ["nmap -sT -sV -p 22,80,443 <lab-ip>", "Identify services on selected ports"], ["nmap -sT -p 443 --reason <lab-ip>", "Show the reason for the reported port state"]], "walkthrough": ["Record the Nmap version and available libraries before following examples. Package versions can differ between Kali installations and rolling updates.", "Replace the placeholder with one approved target. Host discovery does not perform a port scan. A host marked down may simply block the discovery probes; it is not proof the machine is absent.", "This TCP connect scan checks only the listed ports. Open means a connection was accepted; closed and filtered have different meanings. Results reflect this source host and observation time.", "Service detection sends additional application probes. Treat product and version matches as evidence to verify with the service owner, not a definitive vulnerability finding.", "Replace the placeholder with a single authorized host. Compare the reason and timing with firewall logs; a filtered state is not proof of a specific filtering device."], "kind": "Command", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "Validate a lab host’s exposed ports", "symptom": "A lab owner asks which of three known TCP services are reachable from an approved test machine.", "steps": [{"action": "nmap --version", "purpose": "Check the installed scanner version", "detail": "Record the Nmap version and available libraries before following examples. Package versions can differ between Kali installations and rolling updates."}, {"action": "nmap -sn <lab-ip>", "purpose": "Check host discovery responses", "detail": "Replace the placeholder with one approved target. Host discovery does not perform a port scan. A host marked down may simply block the discovery probes; it is not proof the machine is absent."}, {"action": "nmap -sT -p 22,80,443 <lab-ip>", "purpose": "Inspect three selected TCP ports", "detail": "This TCP connect scan checks only the listed ports. Open means a connection was accepted; closed and filtered have different meanings. Results reflect this source host and observation time."}, {"action": "nmap -sT -p 443 --reason <lab-ip>", "purpose": "Show the reason for the reported port state", "detail": "Replace the placeholder with a single authorized host. Compare the reason and timing with firewall logs; a filtered state is not proof of a specific filtering device."}, {"action": "nmap -sT -sV -p 22,80,443 <lab-ip>", "purpose": "Identify services on selected ports", "detail": "Service detection sends additional application probes. Treat product and version matches as evidence to verify with the service owner, not a definitive vulnerability finding."}], "interpretation": "Confirm the authorized target and compare host discovery with a bounded connect scan. A filtered port is not proof of which firewall or host caused the filtering.", "verification": "Repeat the same limited scan after the approved change and compare port states and reasons with the original results."}}, {"id": "kali-wireshark-packet-analysis", "title": "Kali Wireshark packet analysis", "product": "Kali Linux", "vendor": "Kali Linux", "category": "Cybersecurity", "description": "Use display filters to inspect DNS, TCP handshakes and one lab conversation.", "scope": "Wireshark desktop on Kali Linux. Examples are display filters, not capture filters.", "prerequisites": "Open a packet capture you are authorized to inspect using File → Open. Use an existing lab capture for this walkthrough; captures can contain credentials and personal data.", "source": "https://www.wireshark.org/docs/wsug_html_chunked/index.html", "sourceLabel": "Kali Linux official documentation", "rows": [["dns", "Display decoded DNS traffic"], ["tcp.flags.syn == 1 && tcp.flags.ack == 0", "Find initial TCP SYN packets"], ["ip.addr == 192.0.2.10", "Focus on one IPv4 endpoint"], ["tcp.stream eq 0", "Isolate a TCP conversation"], ["tcp.analysis.retransmission", "Display TCP retransmission indications"]], "walkthrough": ["Enter dns in the display filter bar and apply it. Match query names, transaction IDs and responses. Encrypted DNS may not appear as ordinary decoded DNS packets.", "Look for the first step of a TCP handshake, then compare it with the reverse-direction response. Retransmissions alone do not establish whether a firewall or endpoint caused a failure.", "Replace the documentation address with the host in your capture. This matches either source or destination. A display filter hides unrelated packets without deleting them from the file.", "Replace 0 with the stream index of the selected connection, or use Follow → TCP Stream. TLS payload remains encrypted unless you have appropriate decryption material; export only approved data.", "Investigate the affected stream and timing, then compare with capture location and packet loss. Capture loss or asymmetric visibility can affect analysis."], "kind": "Display filter", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "Investigate a failed connection in a lab capture", "symptom": "A permitted packet capture shows a client unable to connect to a test service.", "steps": [{"action": "ip.addr == 192.0.2.10", "purpose": "Focus on one IPv4 endpoint", "detail": "Replace the documentation address with the host in your capture. This matches either source or destination. A display filter hides unrelated packets without deleting them from the file."}, {"action": "dns", "purpose": "Display decoded DNS traffic", "detail": "Enter dns in the display filter bar and apply it. Match query names, transaction IDs and responses. Encrypted DNS may not appear as ordinary decoded DNS packets."}, {"action": "tcp.flags.syn == 1 && tcp.flags.ack == 0", "purpose": "Find initial TCP SYN packets", "detail": "Look for the first step of a TCP handshake, then compare it with the reverse-direction response. Retransmissions alone do not establish whether a firewall or endpoint caused a failure."}, {"action": "tcp.stream eq 0", "purpose": "Isolate a TCP conversation", "detail": "Replace 0 with the stream index of the selected connection, or use Follow → TCP Stream. TLS payload remains encrypted unless you have appropriate decryption material; export only approved data."}, {"action": "tcp.analysis.retransmission", "purpose": "Display TCP retransmission indications", "detail": "Investigate the affected stream and timing, then compare with capture location and packet loss. Capture loss or asymmetric visibility can affect analysis."}], "interpretation": "Focus on the test endpoint, DNS and the TCP handshake. Retransmissions and missing packets are clues, but capture location and packet loss can affect interpretation.", "verification": "Compare a fresh authorized capture after remediation and protect capture files because they can contain sensitive traffic."}}, {"id": "kali-burp-suite-proxy-basics", "title": "Kali Burp Suite proxy basics", "product": "Kali Linux", "vendor": "Kali Linux", "category": "Cybersecurity", "description": "Inspect requests from a local training application with Burp’s built-in browser.", "scope": "Burp Suite Community or Professional desktop. Proxy inspection works without an automated scanner.", "prerequisites": "Start Burp with a temporary project and default settings. Use a local training application or a target you are explicitly authorized to test; keep personal browsing outside Burp’s browser.", "source": "https://portswigger.net/burp/documentation/desktop/tools/proxy", "sourceLabel": "Kali Linux official documentation", "rows": [["Proxy → Intercept → Open Browser", "Launch the preconfigured test browser"], ["Proxy → Intercept → Intercept is off", "Allow ordinary browsing while recording"], ["Proxy → HTTP history", "Inspect a lab request and response"], ["Proxy → Intercept → Intercept is on → Forward", "Observe a paused request, then release it"], ["Target → Site map", "Review discovered lab requests"]], "walkthrough": ["Open your approved training application in Burp’s browser. This browser is already configured to use Burp’s proxy, avoiding changes to your everyday browser’s proxy and certificate settings.", "Keep interception off while navigating the lab so requests are not paused. HTTP history still records traffic that passes through the proxy.", "Select a request to your training app and compare the method, path, status and response headers. Apply filters to focus on the approved target and avoid collecting unrelated traffic.", "Trigger one harmless page request in the lab browser. Inspect it and click Forward without editing. Turn interception off when finished so later requests do not remain unexpectedly paused.", "Use the site map to review hosts and paths observed during the authorized session. Confirm that the host is in scope before continuing any testing."], "kind": "Console path", "level": "Beginner", "time": 6, "updated": "2026-11-02", "case": {"title": "Inspect a training application request", "symptom": "A learner needs to understand a harmless request to an authorized local training application.", "steps": [{"action": "Proxy → Intercept → Open Browser", "purpose": "Launch the preconfigured test browser", "detail": "Open your approved training application in Burp’s browser. This browser is already configured to use Burp’s proxy, avoiding changes to your everyday browser’s proxy and certificate settings."}, {"action": "Proxy → Intercept → Intercept is off", "purpose": "Allow ordinary browsing while recording", "detail": "Keep interception off while navigating the lab so requests are not paused. HTTP history still records traffic that passes through the proxy."}, {"action": "Proxy → HTTP history", "purpose": "Inspect a lab request and response", "detail": "Select a request to your training app and compare the method, path, status and response headers. Apply filters to focus on the approved target and avoid collecting unrelated traffic."}, {"action": "Target → Site map", "purpose": "Review discovered lab requests", "detail": "Use the site map to review hosts and paths observed during the authorized session. Confirm that the host is in scope before continuing any testing."}, {"action": "Proxy → Intercept → Intercept is on → Forward", "purpose": "Observe a paused request, then release it", "detail": "Trigger one harmless page request in the lab browser. Inspect it and click Forward without editing. Turn interception off when finished so later requests do not remain unexpectedly paused."}], "interpretation": "Use the built-in browser, inspect the method, path and status in history, and confirm the host belongs to the lab. A paused request must be forwarded to continue browsing.", "verification": "Turn interception off and repeat the same harmless request; close the temporary project according to the lab’s data-handling rules."}}, {"id": "windows-dns-resolution-investigation", "title": "Windows DNS resolution investigation", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Separate resolver selection, stale cache, missing records and service reachability in a Windows DNS incident.", "scope": "Windows 10/11 or Windows Server; PowerShell DnsClient and NetTCPIP modules.", "prerequisites": "Replace app.corp.example, 10.20.0.10 and 10.20.1.25 with your internal service, resolver and expected address. Run from the affected client; queries and connection tests send traffic.", "source": "https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname", "sourceLabel": "Microsoft Resolve-DnsName reference", "sources": [{"label": "Microsoft Resolve-DnsName reference", "url": "https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname"}, {"label": "Microsoft DNS client module", "url": "https://learn.microsoft.com/en-us/powershell/module/dnsclient/"}, {"label": "Microsoft Test-NetConnection reference", "url": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection"}], "rows": [["Get-DnsClientServerAddress -AddressFamily IPv4", "Identify configured IPv4 resolvers"], ["Resolve-DnsName app.corp.example -Type A -DnsOnly", "Query the client DNS path"], ["Resolve-DnsName app.corp.example -Server 10.20.0.10 -Type A -DnsOnly", "Ask a selected resolver directly"], ["Get-DnsClientCache | Where-Object Entry -eq \"app.corp.example\"", "Inspect matching local cache entries"], ["Resolve-DnsName app.corp.example -Server 10.20.0.10 -Type AAAA -DnsOnly", "Check the IPv6 answer separately"], ["Test-NetConnection 10.20.1.25 -Port 443 -InformationLevel Detailed", "Test TCP against the expected address"]], "walkthrough": ["Match InterfaceAlias to the adapter carrying this connection. VPN and physical adapters can use different resolvers. These are configured addresses, not proof that a query reached a server; record the adapter and resolver before testing.", "Inspect the returned IPv4 addresses, aliases and TTLs. NXDOMAIN means the queried name does not exist according to that response; a timeout means no usable response arrived. Do not interpret those outcomes as the same fault.", "Compare this answer with the default query. A difference can indicate resolver selection, split DNS, replication lag or cache state. Query the other intended internal resolver as well before deciding that a record is incorrect.", "Compare cached data and remaining TTL with the intended record. An absent entry does not prove that the application has no cache of its own. Capture the evidence before considering an approved cache clear; this command changes nothing.", "An application can prefer IPv6 even when IPv4 is healthy. Compare any AAAA answer with the supported application path. No AAAA record is normal for an IPv4-only service; investigate an unexpected record rather than disabling IPv6.", "Inspect TcpTestSucceeded, SourceAddress and InterfaceAlias. A successful IP-based TCP connection separates basic reachability from name resolution, but does not validate the certificate, HTTP host routing or application login."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "The intranet works by IP but not by name", "symptom": "After a VPN change, a user cannot open app.corp.example. The expected internal IPv4 address is 10.20.1.25.", "steps": [{"action": "Get-DnsClientServerAddress -AddressFamily IPv4", "purpose": "Identify configured IPv4 resolvers", "detail": "Record the VPN and LAN resolver lists. Establish which connection is active and retain both lists for the network team."}, {"action": "Resolve-DnsName app.corp.example -Type A -DnsOnly", "purpose": "Query the client DNS path", "detail": "Capture the default answer and error type. In this example the default lookup returns NXDOMAIN."}, {"action": "Resolve-DnsName app.corp.example -Server 10.20.0.10 -Type A -DnsOnly", "purpose": "Ask a selected resolver directly", "detail": "Query the intended internal resolver. It returns 10.20.1.25, so the name exists on that DNS path."}, {"action": "Get-DnsClientCache | Where-Object Entry -eq \"app.corp.example\"", "purpose": "Inspect matching local cache entries", "detail": "Check for a cached result before changing anything. An old negative answer may persist for its negative-cache lifetime."}, {"action": "Test-NetConnection 10.20.1.25 -Port 443 -InformationLevel Detailed", "purpose": "Test TCP against the expected address", "detail": "Test the expected IP and service port. A successful connection narrows the incident toward DNS selection or caching."}], "evidence": "Illustrative findings: default lookup = NXDOMAIN; selected internal resolver = 10.20.1.25; TcpTestSucceeded = True.", "interpretation": "The internal record and TCP service are available in this example. The failing client DNS path deserves investigation; these findings do not prove whether the VPN policy, resolver order or a cache is responsible.", "verification": "After the DNS or VPN owner applies the approved correction, repeat the default A and AAAA queries, then open the application by name and verify its certificate and login from the affected client.", "escalation": "Escalate with the query time, adapter, VPN state, both resolver answers and expected record. Ask the DNS owner to compare authoritative data and split-DNS policy."}}, {"id": "windows-dhcp-scope-and-lease-investigation", "title": "Windows DHCP scope and lease investigation", "product": "Windows", "vendor": "Windows", "category": "Infrastructure", "description": "Inspect DHCP scope capacity, leases, reservations, options and failover before changing a production scope.", "scope": "Windows Server DHCP with the DhcpServer PowerShell module or RSAT DHCP tools.", "prerequisites": "Use authorized read access. Replace dhcp01.corp.example and 10.20.30.0 with the DHCP server and scope network ID, not a client address. These commands query the server without releasing leases.", "source": "https://learn.microsoft.com/en-us/powershell/module/dhcpserver/", "sourceLabel": "Microsoft DHCP Server cmdlets", "sources": [{"label": "Microsoft DHCP Server cmdlets", "url": "https://learn.microsoft.com/en-us/powershell/module/dhcpserver/"}], "rows": [["Get-DhcpServerv4Scope -ComputerName dhcp01.corp.example", "List scopes and their configured state"], ["Get-DhcpServerv4ScopeStatistics -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "Measure scope utilization"], ["Get-DhcpServerv4Lease -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "Inspect allocated leases"], ["Get-DhcpServerv4Reservation -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "Review scope reservations"], ["Get-DhcpServerv4OptionValue -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "Inspect configured scope options"], ["Get-DhcpServerv4Failover -ComputerName dhcp01.corp.example", "Inspect configured failover relationships"]], "walkthrough": ["Find the affected subnet by ScopeId and inspect State, StartRange, EndRange and SubnetMask. An active scope is necessary but does not confirm that the client VLAN can reach the server or that the relay targets this server.", "Compare AddressesFree, AddressesInUse and PercentageInUse with the incident time. A nearly exhausted pool can explain new-client failures while existing clients keep working; retain the sample time and compare with another sample.", "Find the affected client using its address, client identifier and host name. Compare AddressState and LeaseExpiryTime. A client absent from this server may have contacted another server or never reached DHCP; absence alone cannot distinguish those cases.", "Compare reserved addresses and client identifiers with the intended equipment. A reservation is not evidence that a client is online, and a MAC or client-ID mismatch can prevent the expected assignment. Do not remove reservations during evidence collection.", "Compare router option 003 and DNS server option 006 with the subnet design. Scope options do not tell the entire story when server defaults, policies or reservation-level overrides apply; compare the actual client configuration too.", "Record partner, relationship state and associated scopes. No relationship can be intentional on a standalone server. An unexpected communication state requires checking partner health and connectivity before any manual state transition."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "Existing laptops work but new clients receive no lease", "symptom": "New devices on VLAN 30 cannot obtain an address, while machines with current leases remain connected.", "steps": [{"action": "Get-DhcpServerv4Scope -ComputerName dhcp01.corp.example", "purpose": "List scopes and their configured state", "detail": "Confirm VLAN 30 maps to the active 10.20.30.0 scope. A wrong or inactive scope leads to a different investigation."}, {"action": "Get-DhcpServerv4ScopeStatistics -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "purpose": "Measure scope utilization", "detail": "Read available addresses at the time a new client tries to connect. This example has zero free addresses."}, {"action": "Get-DhcpServerv4Lease -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "purpose": "Inspect allocated leases", "detail": "Inspect lease distribution and expiration times. Do not delete apparently unused leases based only on host names."}, {"action": "Get-DhcpServerv4Reservation -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0", "purpose": "Review scope reservations", "detail": "Compare reservations with the approved allocation plan, looking for unexpected consumption or client-ID mismatches."}, {"action": "Get-DhcpServerv4Failover -ComputerName dhcp01.corp.example", "purpose": "Inspect configured failover relationships", "detail": "Check the failover partner state before attributing all available capacity to one server."}], "evidence": "Illustrative findings: State = Active; AddressesFree = 0; existing leases remain valid; failover relationship state = Normal.", "interpretation": "Exhaustion is supported by the capacity sample. It does not establish why addresses were consumed. Review lease growth and address planning with the DHCP owner before changing ranges or lease duration.", "verification": "After the approved capacity correction, have one test client request a lease normally. Confirm its subnet, gateway, DNS options and lease on the server, then repeat the free-address sample.", "escalation": "Send the scope ID, utilization samples, lease counts and partner state to the DHCP owner. If free addresses exist, investigate VLAN relay, server reachability and DHCP logs instead."}}, {"id": "linux-systemd-service-failure-triage", "title": "Linux systemd service failure triage", "product": "Linux", "vendor": "Linux", "category": "IT fundamentals", "description": "Connect service state, exit codes, unit configuration and journal events without hiding evidence behind a restart.", "scope": "Linux distributions running systemd; examples use nginx.service, whose unit name varies by distribution.", "prerequisites": "Replace nginx.service with the affected unit. Use an account permitted to read its journal and configuration. status exits nonzero for a failed unit; that is useful evidence, not a reason to restart it.", "source": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html", "sourceLabel": "systemctl manual", "sources": [{"label": "systemctl manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"label": "journalctl manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}], "rows": [["systemctl status nginx.service --no-pager --full", "Capture service state and recent messages"], ["systemctl show nginx.service -p ActiveState -p SubState -p Result -p ExecMainStatus -p NRestarts", "Read machine-friendly failure fields"], ["journalctl -u nginx.service --since \"30 minutes ago\" -n 100 --no-pager -o short-iso", "Read a bounded incident window"], ["systemctl cat nginx.service", "Inspect the unit and drop-in files"], ["systemctl list-dependencies nginx.service --no-pager", "Inspect declared dependencies"], ["ss -ltnp", "Compare expected TCP listeners with processes"]], "walkthrough": ["Record Loaded, Active, Main PID and the failure timestamp. The short log excerpt can omit the original cause, so use it as a starting point. A failed unit can still have unrelated processes listening on the same application port.", "Compare Result and ExecMainStatus with the service documentation. A nonzero application exit code is different from a timeout or signal. NRestarts records automatic restarts tracked by the manager, not every historical manual start.", "Look for the first error before repeated restart messages. Correlate ISO timestamps with the reported interruption. Empty results can reflect permissions, retention or a wrong unit name; they do not prove that the service produced no errors.", "Read ExecStart, User, dependencies and any override files. This shows files on disk; if they changed without a daemon reload, the manager may still use older settings. Compare the configured executable and account with the journal error.", "Check required units and their state, then investigate any dependency named in the failure log. This is the unit dependency graph, not a full map of DNS, databases or other external services the application needs.", "Find the expected port and local binding. Loopback-only and all-interface listeners serve different paths. Process information can require elevated privileges; an occupied port may explain a bind failure but does not identify the correct owner by itself."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A web service fails immediately after a deployment", "symptom": "The nginx unit fails at startup after an application deployment. Capture evidence before requesting a restart.", "steps": [{"action": "systemctl status nginx.service --no-pager --full", "purpose": "Capture service state and recent messages", "detail": "Record the failed state and the first reported failure time."}, {"action": "journalctl -u nginx.service --since \"30 minutes ago\" -n 100 --no-pager -o short-iso", "purpose": "Read a bounded incident window", "detail": "Read the incident window. In this fictional example the journal reports that binding to port 80 failed because the address is already in use."}, {"action": "systemctl cat nginx.service", "purpose": "Inspect the unit and drop-in files", "detail": "Check the intended executable and drop-ins so that the unit being examined is actually the expected web server."}, {"action": "ss -ltnp", "purpose": "Compare expected TCP listeners with processes", "detail": "Identify the listener on port 80. The example has a separate process holding the port; record its PID for the service owner."}], "evidence": "Illustrative findings: Active = failed; journal contains an address-in-use bind error; ss shows another process listening on TCP 80.", "interpretation": "A port conflict is supported. Do not kill the listener until its owner and purpose are established. The deployment may have introduced a second service or changed a binding.", "verification": "After the owner resolves the conflicting configuration and performs an approved start, repeat status, journal and listener checks, then test the application through its normal URL.", "escalation": "Provide unit/drop-in paths, the first failure message, timestamps and listener PID to the application owner. Remove credentials from configuration excerpts."}}, {"id": "linux-disk-space-and-inode-investigation", "title": "Linux disk space and inode investigation", "product": "Linux", "vendor": "Linux", "category": "Infrastructure", "description": "Distinguish exhausted bytes, exhausted inodes, mount layout and directory growth before deleting any files.", "scope": "Linux with GNU coreutils and util-linux. Commands inspect mounted filesystems and may take time on large directory trees.", "prerequisites": "Replace /var with the affected path. Directory traversal may need additional read permissions. Stay on the selected filesystem when measuring; this workflow performs no cleanup or filesystem repair.", "source": "https://man7.org/linux/man-pages/man8/lsblk.8.html", "sourceLabel": "Linux lsblk manual", "sources": [{"label": "Linux lsblk manual", "url": "https://man7.org/linux/man-pages/man8/lsblk.8.html"}, {"label": "GNU disk usage documentation", "url": "https://www.gnu.org/software/coreutils/manual/html_node/Disk-usage.html"}, {"label": "Linux findmnt manual", "url": "https://man7.org/linux/man-pages/man8/findmnt.8.html"}], "rows": [["df -hT /var", "Inspect filesystem byte capacity"], ["df -i /var", "Inspect inode capacity"], ["findmnt -T /var", "Identify the mount serving a path"], ["lsblk -o NAME,SIZE,FSTYPE,MOUNTPOINTS", "Map block devices to filesystems"], ["du -xhd1 /var", "Measure first-level directory byte usage"], ["du --inodes -x --max-depth=1 /var", "Locate directories consuming many inodes"]], "walkthrough": ["Read the filesystem, mountpoint, type, Available and Use% for this path. A full parent or separate mount can affect only part of the server. Human-readable rounded values are useful for triage; compare the same mount across samples.", "Check IFree and IUse% on filesystems with fixed inode accounting. A workload creating many tiny files can exhaust inodes while gigabytes remain free. Some filesystem types allocate metadata differently, so interpret these fields with their documentation.", "Record SOURCE, TARGET, FSTYPE and mount options. A read-only mount can explain write failures even when capacity remains. Compare the selected mount with the expected volume before attributing usage to a directory on another filesystem.", "Trace the mounted filesystem back to its disk, partition or logical device. A large disk does not mean the filesystem has been expanded to use it. MOUNTPOINTS availability depends on util-linux version; use MOUNTPOINT on older releases.", "Compare the largest immediate directories while staying on one filesystem. du reports accessible linked files, whereas df reports filesystem allocation, so deleted-open files, metadata, reserved space and permission failures can explain a difference.", "On GNU du, compare inode counts by immediate directory when df -i indicates pressure. A large count points toward many files rather than a single large log. Inspect the responsible application and its retention policy before authorizing cleanup."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "An application says no space left despite free gigabytes", "symptom": "A queue worker cannot create new files under /var. The monitoring dashboard still shows several gigabytes free.", "steps": [{"action": "df -hT /var", "purpose": "Inspect filesystem byte capacity", "detail": "Confirm the failing path is on the filesystem represented in the dashboard."}, {"action": "df -i /var", "purpose": "Inspect inode capacity", "detail": "Read inode utilization. This example reports IFree = 0 despite available bytes."}, {"action": "findmnt -T /var", "purpose": "Identify the mount serving a path", "detail": "Verify the actual mount and options so a separate queue volume is not confused with the root filesystem."}, {"action": "du --inodes -x --max-depth=1 /var", "purpose": "Locate directories consuming many inodes", "detail": "Compare directory inode counts. The example concentrates millions of small entries under the application queue."}], "evidence": "Illustrative findings: Available = 8G; IUse% = 100%; the application queue dominates the inode count.", "interpretation": "The immediate limit is inode availability, not byte capacity. Application retention or a stuck queue may explain growth; deleting arbitrary queue entries could lose work.", "verification": "After the application owner performs approved retention or queue recovery, repeat df -i and the directory count. Confirm that a normal application operation creates and processes a new item.", "escalation": "Share the mount, inode samples, growth window and directory counts with the application/storage owners. If df and du disagree, ask for an investigation of deleted-open files and filesystem accounting."}}, {"id": "docker-container-health-and-restart-investigation", "title": "Docker container health and restart investigation", "product": "Docker", "vendor": "Docker", "category": "Infrastructure", "description": "Inspect container exit state, health checks, bounded logs, resource usage and published ports during a restart incident.", "scope": "Docker Engine CLI; examples use a container named web. Health fields exist only when a health check is configured.", "prerequisites": "Confirm your Docker context and replace web with the affected container. Use authorized daemon access. No command here restarts, removes or executes code inside a container.", "source": "https://docs.docker.com/reference/cli/docker/container/", "sourceLabel": "Docker container CLI reference", "sources": [{"label": "Docker container CLI reference", "url": "https://docs.docker.com/reference/cli/docker/container/"}, {"label": "Docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}, {"label": "Docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"label": "Docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}], "rows": [["docker context show", "Confirm the selected Docker context"], ["docker ps -a --filter name=web", "Find the container and its status"], ["docker inspect --format \"{{json .State}}\" web", "Inspect exit and health state"], ["docker logs --since 30m --tail 100 --timestamps web", "Read bounded application logs"], ["docker stats --no-stream web", "Take one resource-usage sample"], ["docker port web", "Inspect published host port mappings"]], "walkthrough": ["Record the context before collecting evidence. The same container name may exist on a local workstation and a remote daemon. Also check whether DOCKER_HOST or command-line endpoint flags override where your investigation is directed.", "Inspect the container ID, image, status and published ports. The name filter can match multiple names; select the exact ID for follow-up queries. A running state does not prove application readiness or a passing health check.", "Read Status, ExitCode, OOMKilled, Error and timestamps. When present, Health includes probe results. OOMKilled supports a memory-kill investigation; exit code 137 alone does not prove an OOM kill because other SIGKILL paths can produce it.", "Correlate the first application error with the start and finish timestamps. Logs generally reflect stdout and stderr, and availability depends on the logging driver. Redact tokens and connection strings before attaching excerpts to an incident.", "Record memory use, limit, CPU and block I/O for a running container. A single sample cannot establish the peak immediately before a crash. Compare multiple timed samples with host monitoring and the recorded exit state.", "Compare the container port and host binding with the URL users reach. A published mapping does not prove that the process is listening inside the container or that the host firewall and upstream load balancer permit traffic."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A web container repeatedly exits during peak traffic", "symptom": "Users see intermittent failures and the web container repeatedly starts and exits under load.", "steps": [{"action": "docker context show", "purpose": "Confirm the selected Docker context", "detail": "Confirm that the CLI targets the production daemon named in the incident."}, {"action": "docker ps -a --filter name=web", "purpose": "Find the container and its status", "detail": "Capture the exact container ID and image so a replacement is not confused with the original container."}, {"action": "docker inspect --format \"{{json .State}}\" web", "purpose": "Inspect exit and health state", "detail": "Read the stored exit state. This example has OOMKilled = true and ExitCode = 137."}, {"action": "docker logs --since 30m --tail 100 --timestamps web", "purpose": "Read bounded application logs", "detail": "Compare the last logs with the exit timestamp; missing shutdown logs are consistent with a forced kill but do not explain memory growth."}, {"action": "docker stats --no-stream web", "purpose": "Take one resource-usage sample", "detail": "If the container is running, sample its memory and correlate with host metrics. If stopped, record that stats cannot show its previous peak."}], "evidence": "Illustrative findings: OOMKilled = true; ExitCode = 137; monitoring records memory approaching the configured limit before each exit.", "interpretation": "The evidence supports a memory kill. It does not distinguish a leak, insufficient sizing or a traffic spike. Increasing limits without checking host capacity can move the failure to the host.", "verification": "After an approved application or resource change, observe the same traffic window. Confirm stable uptime, passing health checks if configured, memory headroom and successful requests through the published service.", "escalation": "Send container/image IDs, exit timestamps, configured limits and monitoring graphs to the application/platform owners. Do not include a full inspect dump containing environment secrets."}}, {"id": "kubernetes-pod-crash-and-readiness-investigation", "title": "Kubernetes pod crash and readiness investigation", "product": "Kubernetes", "vendor": "Kubernetes", "category": "Cloud", "description": "Trace a failing pod through context, scheduling, container state, current logs, previous logs and namespace events.", "scope": "kubectl against a supported Kubernetes cluster. Examples target namespace production, pod web-abc123 and container web.", "prerequisites": "Replace namespace, pod and container names. Confirm cluster context and RBAC read access. Pod replacement changes the name and UID; use the pod that exists in the incident window.", "source": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/", "sourceLabel": "Kubernetes pod debugging", "sources": [{"label": "Kubernetes pod debugging", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/"}, {"label": "kubectl reference", "url": "https://kubernetes.io/docs/reference/kubectl/"}, {"label": "kubectl logs reference", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}], "rows": [["kubectl config current-context", "Confirm the selected cluster context"], ["kubectl get pods -n production -o wide", "Inspect pod readiness, restarts and placement"], ["kubectl describe pod web-abc123 -n production", "Inspect container states, probes and events"], ["kubectl logs web-abc123 -n production -c web --since=30m --tail=100 --timestamps=true", "Read the current container logs"], ["kubectl logs web-abc123 -n production -c web --previous --tail=100 --timestamps=true", "Read the previous terminated instance"], ["kubectl get events -n production --sort-by=.metadata.creationTimestamp", "Correlate recent namespace events"]], "walkthrough": ["Record the context and compare it with the incident environment. A context name is locally configured and can be misleading; verify the intended cluster through your approved inventory before interpreting workload results.", "Find the affected pod and note Ready, Status, Restarts, age and node. Running is a lifecycle phase, not a guarantee that every container is ready. Pending requires scheduling investigation; a crash loop requires container-state and log inspection.", "Read current State, Last State, exit reason, readiness/liveness probes and events. OOMKilled, failed probes and image-pull failures lead to different investigations. A failing readiness probe removes readiness; a failing liveness probe can trigger a restart.", "Use the explicit container name in multi-container pods. Correlate timestamps with restarts and probes. Empty current logs may simply mean that the newest container has barely started; examine the previous container instance if it exists.", "Look for the first fatal message before termination. Previous logs cover the prior container instance in this pod, not every historical restart or a deleted pod. Unavailable logs require your centralized logging system or node-level investigation.", "Match involved object names, messages and times to the pod under investigation. Events are retained for a limited period and can aggregate repeated occurrences. A broad namespace list may include unrelated failures, so do not infer causality from proximity alone."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A deployment has Running pods but no ready replicas", "symptom": "After a rollout, a web pod appears Running but shows 0/1 Ready and an increasing restart count.", "steps": [{"action": "kubectl config current-context", "purpose": "Confirm the selected cluster context", "detail": "Confirm the cluster context before querying the production namespace."}, {"action": "kubectl get pods -n production -o wide", "purpose": "Inspect pod readiness, restarts and placement", "detail": "Record the pod name, node and restart count twice to determine whether restarts are still increasing."}, {"action": "kubectl describe pod web-abc123 -n production", "purpose": "Inspect container states, probes and events", "detail": "Read the termination reason and probe events. This example shows a nonzero application exit rather than OOMKilled."}, {"action": "kubectl logs web-abc123 -n production -c web --previous --tail=100 --timestamps=true", "purpose": "Read the previous terminated instance", "detail": "Read previous logs. The fictional log reports a missing required configuration key at startup."}, {"action": "kubectl get events -n production --sort-by=.metadata.creationTimestamp", "purpose": "Correlate recent namespace events", "detail": "Correlate rollout timing and restart events without dumping Secret values into the incident ticket."}], "evidence": "Illustrative findings: Ready = 0/1; restart count increases; previous logs report a required configuration key missing; no OOMKilled reason.", "interpretation": "The startup configuration is the leading hypothesis. A readiness failure alone would not explain repeated restarts; correlate application exits and liveness events before deciding on the trigger.", "verification": "After the owner corrects the deployment configuration through the approved rollout, inspect the replacement pods. Confirm all expected containers are ready, restart counts stay stable, and the service responds through its normal route.", "escalation": "Provide namespace, pod UID/name, image, first fatal message and relevant event times to the workload owner. Record configuration key names without exposing Secret values."}}, {"id": "http-and-tls-troubleshooting-with-curl", "title": "HTTP and TLS troubleshooting with curl", "product": "curl", "vendor": "curl", "category": "Networking", "description": "Separate DNS, TCP, certificate validation, redirects and HTTP status with bounded curl requests.", "scope": "curl on Linux/macOS or curl.exe on Windows. Commands below use POSIX shell quoting; use curl.exe in Windows PowerShell.", "prerequisites": "Replace app.example.com and 192.0.2.25 with an approved endpoint and expected IP. Requests contact the service. Commands retain certificate verification and send no authentication token.", "source": "https://curl.se/docs/manpage.html", "sourceLabel": "curl official command manual", "sources": [{"label": "curl official command manual", "url": "https://curl.se/docs/manpage.html"}], "rows": [["curl --version", "Identify curl features and TLS backend"], ["curl --head --connect-timeout 5 --max-time 15 https://app.example.com/", "Inspect the first HTTP response headers"], ["curl --silent --show-error --output /dev/null --write-out \"code=%{http_code} dns=%{time_namelookup} tcp=%{time_connect} tls=%{time_appconnect} total=%{time_total}\\n\" --connect-timeout 5 --max-time 15 https://app.example.com/", "Compare request timing checkpoints"], ["curl --verbose --output /dev/null --connect-timeout 5 --max-time 15 https://app.example.com/", "Inspect connection and certificate diagnostics"], ["curl --head --location --max-redirs 5 --connect-timeout 5 --max-time 20 https://app.example.com/", "Trace a bounded redirect chain"], ["curl --head --resolve app.example.com:443:192.0.2.25 --connect-timeout 5 --max-time 15 https://app.example.com/", "Test one endpoint while preserving hostname checks"]], "walkthrough": ["Record the version, TLS backend and supported protocols. Different builds can use different certificate stores and proxy behavior. On Windows invoke curl.exe explicitly if PowerShell resolves curl to Invoke-WebRequest.", "Read the status and Location header without following redirects. HEAD can behave differently from GET and may be unsupported, so a 405 response is not proof that normal browsing fails. Connection and total timeouts bound the attempt.", "The timing values are cumulative checkpoints from request start, not independent phase durations. Subtract adjacent checkpoints cautiously; proxies, reuse and redirects change interpretation. On Windows replace /dev/null with NUL. HTTP 4xx/5xx can still have a zero curl exit code.", "Inspect the resolved address, proxy use, TLS negotiation and certificate error if any. Verbose output can contain headers and sensitive connection details, so redact before sharing. Keep verification enabled; use NUL instead of /dev/null on Windows.", "Compare each status and Location with the expected canonical host and login flow. A loop or unexpected destination can explain browser failures. HEAD redirects are still not a full test of a GET request or an authenticated user session.", "This pins the host/port to the selected address while retaining the URL hostname for TLS and HTTP routing. It isolates DNS selection without disabling certificate verification. An active proxy can change the connection path; inspect proxy use first."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A site fails after a DNS migration", "symptom": "A browser reports a certificate error after an application moves to a new load balancer.", "steps": [{"action": "curl --version", "purpose": "Identify curl features and TLS backend", "detail": "Record the TLS backend so differences in trust stores between the browser and CLI can be investigated."}, {"action": "curl --verbose --output /dev/null --connect-timeout 5 --max-time 15 https://app.example.com/", "purpose": "Inspect connection and certificate diagnostics", "detail": "Capture the selected destination and certificate failure. In this example the default DNS path reaches an old endpoint with the wrong hostname certificate."}, {"action": "curl --head --resolve app.example.com:443:192.0.2.25 --connect-timeout 5 --max-time 15 https://app.example.com/", "purpose": "Test one endpoint while preserving hostname checks", "detail": "Pin the expected new endpoint while preserving app.example.com. The example succeeds with normal verification."}, {"action": "curl --head --location --max-redirs 5 --connect-timeout 5 --max-time 20 https://app.example.com/", "purpose": "Trace a bounded redirect chain", "detail": "Trace the redirect chain on the intended path and confirm that a later redirect is not sending users back to the old hostname."}], "evidence": "Illustrative findings: default request fails hostname verification; the --resolve request to the approved new address returns HTTP 200 with certificate verification enabled.", "interpretation": "The result supports an endpoint-selection or DNS-transition problem. It does not prove the authoritative record is wrong; a recursive cache, hosts override, split DNS or proxy can select the old endpoint.", "verification": "After the approved DNS/load-balancer correction and applicable cache expiry, repeat the default request without --resolve. Verify the certificate, final URL and normal browser session from affected networks.", "escalation": "Send the hostname, resolved addresses, error text, TLS backend and pin-test result to the DNS/load-balancer owner. Do not solve a hostname error by disabling certificate checks."}}, {"id": "aws-ec2-network-path-inspection", "title": "AWS EC2 network path inspection", "product": "AWS", "vendor": "AWS", "category": "Cloud", "description": "Connect AWS identity, instance state, subnets, route tables, security groups and network ACLs in one inspection workflow.", "scope": "AWS CLI v2 with an existing authenticated profile and read permissions for STS and EC2. Examples use eu-west-1.", "prerequisites": "Replace the profile, region, instance, subnet, VPC and security-group IDs. Confirm the incident account first. AWS APIs return configuration; these commands do not run packet probes or change rules.", "source": "https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-instances.html", "sourceLabel": "AWS EC2 describe-instances", "sources": [{"label": "AWS EC2 describe-instances", "url": "https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-instances.html"}, {"label": "AWS EC2 describe-route-tables", "url": "https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-route-tables.html"}, {"label": "AWS EC2 describe-security-groups", "url": "https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-security-groups.html"}, {"label": "AWS EC2 describe-network-acls", "url": "https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-network-acls.html"}, {"label": "AWS STS get-caller-identity", "url": "https://docs.aws.amazon.com/cli/latest/reference/sts/get-caller-identity.html"}], "rows": [["aws sts get-caller-identity --profile production --region eu-west-1", "Confirm the account and principal"], ["aws ec2 describe-instances --instance-ids i-0123456789abcdef0 --profile production --region eu-west-1", "Inspect the target instance and interfaces"], ["aws ec2 describe-instance-status --instance-ids i-0123456789abcdef0 --include-all-instances --profile production --region eu-west-1", "Check instance and system status checks"], ["aws ec2 describe-route-tables --filters Name=vpc-id,Values=vpc-0123456789abcdef0 --profile production --region eu-west-1", "Identify the subnet route table and main fallback"], ["aws ec2 describe-security-groups --group-ids sg-0123456789abcdef0 --profile production --region eu-west-1", "Inspect a security group attached to the interface"], ["aws ec2 describe-network-acls --filters Name=association.subnet-id,Values=subnet-0123456789abcdef0 --profile production --region eu-west-1", "Inspect the subnet network ACL"]], "walkthrough": ["Compare Account and Arn with the approved environment. A profile label does not prove account identity. Authentication failure must be resolved through the normal sign-in flow before interpreting missing resources as an infrastructure problem.", "Record State, VpcId, SubnetId, private addresses and security groups on the actual network interface. A running instance can still have a failing guest OS or application. Wrong-region queries can look like missing resources.", "Distinguish system status, instance status and any scheduled events. Passed checks do not establish application readiness, DNS correctness or allowed service ports; use them to separate infrastructure signals from later path checks.", "Find an explicit association for the instance subnet; otherwise use the VPC main route table. Inspect destination-specific routes, target and State, including blackhole entries. Listing only explicit subnet associations can miss the main-table fallback.", "Compare protocol, ports and source or destination with the actual flow. Evaluate all groups attached to the interface because allowed rules combine. Security groups are stateful, but that does not override network ACLs, guest firewalls or missing routes.", "Evaluate the first matching rule in ascending rule-number order in each direction. ACLs are stateless, so include the response path and appropriate ephemeral ports. Confirm the effective client address when traffic passes through NAT or a load balancer."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "An instance runs but HTTPS clients time out", "symptom": "An EC2 application is running, yet an approved client network cannot connect to TCP 443 after a subnet change.", "steps": [{"action": "aws sts get-caller-identity --profile production --region eu-west-1", "purpose": "Confirm the account and principal", "detail": "Record the account and principal to avoid examining a similarly named workload in another environment."}, {"action": "aws ec2 describe-instances --instance-ids i-0123456789abcdef0 --profile production --region eu-west-1", "purpose": "Inspect the target instance and interfaces", "detail": "Identify the actual subnet and every security group attached to the serving interface."}, {"action": "aws ec2 describe-route-tables --filters Name=vpc-id,Values=vpc-0123456789abcdef0 --profile production --region eu-west-1", "purpose": "Identify the subnet route table and main fallback", "detail": "Resolve the effective subnet route table, including the main fallback, and trace the return destination."}, {"action": "aws ec2 describe-security-groups --group-ids sg-0123456789abcdef0 --profile production --region eu-west-1", "purpose": "Inspect a security group attached to the interface", "detail": "Check inbound 443 against the real client source. In this example the security group permits it."}, {"action": "aws ec2 describe-network-acls --filters Name=association.subnet-id,Values=subnet-0123456789abcdef0 --profile production --region eu-west-1", "purpose": "Inspect the subnet network ACL", "detail": "Read ACL rules in order in both directions. The fictional example has an outbound rule denying the client ephemeral-port range before an allow rule."}], "evidence": "Illustrative findings: instance = running; security group permits inbound TCP 443; effective ACL has an earlier outbound deny matching response traffic.", "interpretation": "The ACL is a supported path blocker in this example. It is not evidence that the application is healthy. Validate the client address and response ports against real flow evidence before changing a rule.", "verification": "After the network owner applies a least-privilege correction, repeat configuration checks and perform an approved HTTPS request from the original client. Confirm application response and return traffic.", "escalation": "Provide account, region, ENI/subnet, effective route table, all attached groups, ordered ACL rules and client flow tuple. Escalate guest listener and host-firewall checks to the instance owner."}}, {"id": "git-working-tree-and-merge-conflict-inspection", "title": "Git working tree and merge conflict inspection", "product": "Git", "vendor": "Git", "category": "IT fundamentals", "description": "Separate staged, unstaged, untracked and conflicted files before choosing a commit or recovery action.", "scope": "Git CLI in an existing trusted repository. These commands inspect local state without fetching, resetting or resolving conflicts.", "prerequisites": "Run from the affected checkout. Replace src/app.js with a real conflicted path. Remote-tracking information can be stale until a separately approved fetch; preserve local changes before planning recovery.", "source": "https://git-scm.com/docs/git-status", "sourceLabel": "Git status reference", "sources": [{"label": "Git status reference", "url": "https://git-scm.com/docs/git-status"}, {"label": "Git diff reference", "url": "https://git-scm.com/docs/git-diff"}, {"label": "Git ls-files reference", "url": "https://git-scm.com/docs/git-ls-files"}], "rows": [["git status --short --branch", "Summarize the branch and file states"], ["git diff --stat", "Measure unstaged tracked changes"], ["git diff --cached --stat", "Measure changes staged for the next commit"], ["git diff --name-only --diff-filter=U", "List unresolved conflict paths"], ["git ls-files -u -- src/app.js", "Inspect unmerged index stages for one file"], ["git log -5 --oneline --decorate", "Locate the current commit in recent history"]], "walkthrough": ["Read the two status columns separately: the first describes the index and the second the working tree, with special combinations for conflicts. Untracked files appear separately. Upstream ahead/behind counts depend on the last locally known remote state.", "This summarizes differences between tracked working files and the index. It excludes staged-only changes and untracked files, so a blank result does not mean the checkout is clean. Compare it with status before concluding that work is missing.", "Inspect what the index contains relative to HEAD. A file can have both staged and unstaged edits; compare both diff summaries. The staged snapshot is what a normal commit records, not necessarily the entire current file on disk.", "Collect paths with unmerged index entries before editing. The list does not determine which side is correct or whether a merge versus rebase is in progress; read the full status message for the operation and its next steps.", "Read the stage numbers and object IDs. For a typical content conflict, stages 1, 2 and 3 represent base and the two sides; add/delete conflicts can omit stages. During a rebase, intuitive meanings of ours and theirs can differ from a normal merge.", "Compare HEAD and visible branch labels with the expected checkout. This shows local history, not evidence that a push succeeded. Detached HEAD can be intentional in CI or inspection work; do not move branch pointers just to change its appearance."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A file seems missing from the next commit", "symptom": "A developer edits several files during a merge, but the staged diff contains only part of the work.", "steps": [{"action": "git status --short --branch", "purpose": "Summarize the branch and file states", "detail": "Read the status columns and identify files with both staged and unstaged changes."}, {"action": "git diff --stat", "purpose": "Measure unstaged tracked changes", "detail": "Compare the unstaged summary with the intended change; an edited file can be absent from the staged snapshot."}, {"action": "git diff --cached --stat", "purpose": "Measure changes staged for the next commit", "detail": "Inspect the actual staged file set rather than assuming every visible editor change will be committed."}, {"action": "git diff --name-only --diff-filter=U", "purpose": "List unresolved conflict paths", "detail": "Check for unresolved paths before recommending a commit or proceeding with the merge."}], "evidence": "Illustrative findings: status reports MM for one file and UU for another; the staged summary omits the newest working-tree edit.", "interpretation": "The index and working tree contain different snapshots, and a separate conflict remains unresolved. These are two issues; staging everything blindly would not establish that the conflict resolution is correct.", "verification": "After reviewing and resolving the intended edits, repeat status and both diffs. Verify the staged patch contains only the approved change and that no unmerged paths remain before committing.", "escalation": "Provide the branch, operation in progress, affected paths and relevant patch excerpts to the repository owner. Preserve the checkout; avoid reset or clean as a diagnostic shortcut."}}, {"id": "ansible-inventory-and-playbook-preflight", "title": "Ansible inventory and playbook preflight", "product": "Ansible", "vendor": "Ansible", "category": "Infrastructure", "description": "Check configuration, inventory groups, resolved host variables and selected playbook hosts before running automation.", "scope": "ansible-core CLI on the control node. Use a trusted inventory and playbook; plugins, inventory scripts and lookups can execute code even during preflight.", "prerequisites": "Replace inventory.ini, site.yml and web01 with local trusted inputs. These examples do not execute playbook tasks. Inventory output can include secrets; keep variable dumps private.", "source": "https://docs.ansible.com/projects/ansible/latest/cli/ansible-inventory.html", "sourceLabel": "Ansible inventory CLI", "sources": [{"label": "Ansible inventory CLI", "url": "https://docs.ansible.com/projects/ansible/latest/cli/ansible-inventory.html"}, {"label": "Ansible playbook CLI", "url": "https://docs.ansible.com/projects/ansible/latest/cli/ansible-playbook.html"}, {"label": "Ansible configuration CLI", "url": "https://docs.ansible.com/projects/ansible/latest/cli/ansible-config.html"}], "rows": [["ansible --version", "Identify runtime and configuration file"], ["ansible-config dump --only-changed", "Inspect effective nondefault configuration"], ["ansible-inventory -i inventory.ini --graph", "Inspect inventory group membership"], ["ansible-inventory -i inventory.ini --host web01", "Inspect resolved inventory variables for one host"], ["ansible-playbook -i inventory.ini site.yml --list-hosts", "List hosts selected by the playbook"], ["ansible-playbook -i inventory.ini site.yml --syntax-check", "Check playbook syntax without running tasks"]], "walkthrough": ["Record ansible-core version, Python interpreter and the selected configuration file. A shell in another directory or virtual environment can load different settings; compare the actual paths with the automation runner before investigating hosts.", "Review changed settings and their origin, especially inventory and collection paths. This is not the resolved set of every host variable. Redact credentials or sensitive paths before sharing the output outside the control-node team.", "Confirm that the intended host belongs to the group referenced by the playbook. A parse warning or an empty group points toward inventory selection or syntax. A valid graph does not prove that SSH access or task privileges will work.", "Compare ansible_host, connection type and group-derived variables with the intended target. The alias may differ from its DNS name. Treat the output as sensitive because inventory variables can contain passwords and tokens.", "Compare each play host pattern with the expected maintenance scope. This does not execute tasks or test connectivity. Additional limit flags in the real runner can narrow the selected set further, so compare the exact production command.", "Resolve reported YAML, task or collection-loading errors before execution. Passing syntax checks does not validate runtime variables, network access, task behavior or dynamically included content in every possible branch."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A playbook reports no hosts matched", "symptom": "An operator expects a web-server maintenance play to select web01, but the automation runner selects zero hosts.", "steps": [{"action": "ansible --version", "purpose": "Identify runtime and configuration file", "detail": "Record the config file and runtime used in the failing shell; compare them with the runner."}, {"action": "ansible-inventory -i inventory.ini --graph", "purpose": "Inspect inventory group membership", "detail": "Inspect the inventory graph. In this example web01 belongs to webservers, while no web group exists."}, {"action": "ansible-playbook -i inventory.ini site.yml --list-hosts", "purpose": "List hosts selected by the playbook", "detail": "List playbook hosts with the same inventory. The fictional play targets web, producing an empty selection."}, {"action": "ansible-playbook -i inventory.ini site.yml --syntax-check", "purpose": "Check playbook syntax without running tasks", "detail": "Check syntax separately so a syntactically valid playbook is not confused with correct targeting."}], "evidence": "Illustrative findings: inventory has webservers/web01; the play targets web; syntax check passes; list-hosts returns zero targets.", "interpretation": "The host-pattern mismatch explains the empty selection in this example. Syntax success does not prove that a play targets the intended equipment.", "verification": "After the owner corrects the approved inventory or play pattern, repeat the graph and list-hosts checks with the runner exact arguments. Review the selected hosts before scheduling execution.", "escalation": "Send the configuration path, inventory path, group names and selected host count to the automation owner. Share variable names rather than secret values."}}, {"id": "terraform-workspace-and-state-inspection", "title": "Terraform workspace and state inspection", "product": "Terraform", "vendor": "Terraform", "category": "Cloud", "description": "Verify the active workspace, provider requirements, configuration validity and recorded resources before planning infrastructure changes.", "scope": "Terraform CLI in an already initialized, trusted configuration directory with the intended backend access.", "prerequisites": "Use the approved checkout and installed providers. Replace aws_instance.web with a real state address. These commands do not apply changes; state output can expose infrastructure identifiers and sensitive values.", "source": "https://developer.hashicorp.com/terraform/cli/commands/state/list", "sourceLabel": "Terraform state list", "sources": [{"label": "Terraform state list", "url": "https://developer.hashicorp.com/terraform/cli/commands/state/list"}, {"label": "Terraform state show", "url": "https://developer.hashicorp.com/terraform/cli/commands/state/show"}, {"label": "Terraform validate", "url": "https://developer.hashicorp.com/terraform/cli/commands/validate"}, {"label": "Terraform workspace show", "url": "https://developer.hashicorp.com/terraform/cli/commands/workspace/show"}], "rows": [["terraform version", "Record CLI and installed provider versions"], ["terraform workspace show", "Identify the selected CLI workspace"], ["terraform providers", "Inspect provider requirements by module"], ["terraform validate", "Validate configuration in the initialized directory"], ["terraform state list", "List addresses in the selected state"], ["terraform state show 'aws_instance.web'", "Inspect one recorded resource"]], "walkthrough": ["Compare the CLI and provider versions with the project constraints and lock file. A local version difference can explain validation behavior. Version output alone does not prove that the correct backend or cloud account is selected.", "Compare the workspace name with the deployment process. A workspace is a state selection mechanism, not proof of cloud account identity. HCP Terraform workspace mapping and backend configuration require their own verification.", "Compare provider requirements from configuration and state with the expected modules. This helps identify an unexpected dependency or migration gap; it does not query whether the remote resource is healthy or whether credentials are valid.", "Read errors about configuration structure, types and provider schema. Required modules and providers must already be installed. Validation does not compare real infrastructure with state or establish that a later plan will be accepted by an API.", "Find the expected module and resource addresses. Empty state can mean a new workspace, wrong backend, wrong workspace or genuinely unmanaged infrastructure. Do not import or create resources until the state-selection question is settled.", "Use the exact address from state list, preserving quotes for indexed addresses where required. This displays recorded state and does not refresh remote facts. Protect the output; it can include sensitive values and internal resource details."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A resource exists in the cloud but not in state list", "symptom": "An engineer is preparing a change and cannot find the production instance in the current Terraform state.", "steps": [{"action": "terraform workspace show", "purpose": "Identify the selected CLI workspace", "detail": "Check the active workspace. This example reports default rather than the intended production workspace."}, {"action": "terraform providers", "purpose": "Inspect provider requirements by module", "detail": "Compare the module/provider layout with the repository used by the production pipeline."}, {"action": "terraform state list", "purpose": "List addresses in the selected state", "detail": "Record the current state addresses without importing or creating anything."}, {"action": "terraform validate", "purpose": "Validate configuration in the initialized directory", "detail": "Validate configuration separately; a valid configuration does not make the state selection correct."}], "evidence": "Illustrative findings: current workspace = default; state list is empty; the production runner is documented to use another state selection.", "interpretation": "A state-selection mismatch is the leading explanation. The cloud resource existing does not mean that importing it into this empty state is appropriate; it may already belong to the intended production state.", "verification": "After the owner selects the approved backend/workspace through the normal process, repeat workspace show and state list. Compare recorded resource identity with the cloud account before requesting a reviewed plan.", "escalation": "Provide the checkout revision, workspace, backend identity and expected resource address to the infrastructure owner. Avoid publishing state contents or changing backend settings during evidence collection."}}, {"id": "redis-memory-and-latency-investigation", "title": "Redis memory and latency investigation", "product": "Redis", "vendor": "Redis", "category": "Infrastructure", "description": "Compare Redis identity, memory pressure, eviction counters, client connections and slow-command evidence without scanning the keyspace.", "scope": "Redis CLI against a permitted Redis endpoint. Examples use a local endpoint on 127.0.0.1:6379; ACL permissions and managed-service command support vary.", "prerequisites": "Use an existing authenticated session or approved credential mechanism. Adapt host, TLS and authentication options to your environment; do not place passwords in shared command lines. No key writes, KEYS, MONITOR or configuration changes are used.", "source": "https://redis.io/docs/latest/commands/info/", "sourceLabel": "Redis INFO command", "sources": [{"label": "Redis INFO command", "url": "https://redis.io/docs/latest/commands/info/"}, {"label": "Redis SLOWLOG GET", "url": "https://redis.io/docs/latest/commands/slowlog-get/"}, {"label": "Redis PING", "url": "https://redis.io/docs/latest/commands/ping/"}], "rows": [["redis-cli -h 127.0.0.1 -p 6379 PING", "Test the selected Redis endpoint"], ["redis-cli -h 127.0.0.1 -p 6379 INFO server", "Identify the server and uptime"], ["redis-cli -h 127.0.0.1 -p 6379 INFO memory", "Inspect memory use and configured limits"], ["redis-cli -h 127.0.0.1 -p 6379 INFO stats", "Compare eviction and cache counters"], ["redis-cli -h 127.0.0.1 -p 6379 INFO clients", "Inspect connection pressure"], ["redis-cli -h 127.0.0.1 -p 6379 SLOWLOG GET 10", "Read a bounded slow-command sample"]], "walkthrough": ["A PONG confirms the server answered this command on this connection. It does not prove application authorization, cache-hit behavior or acceptable latency under load. An authentication or ACL error is different from a connection timeout.", "Record version, server mode and uptime to correlate a restart with the incident. In clustered or replicated deployments, one endpoint does not represent all nodes; confirm which node the application actually uses.", "Compare used_memory, used_memory_rss, maxmemory and maxmemory_policy. RSS and allocator memory measure different things. A zero maxmemory value is not evidence of unlimited physical RAM; host or container limits can still apply.", "Capture evicted_keys, keyspace_hits and keyspace_misses twice with timestamps. These are cumulative counters, so a historical nonzero value does not prove an active incident. Compare deltas and the workload mix, not only totals.", "Compare connected_clients and blocked_clients with normal operation and application connection-pool settings. Blocked clients may be legitimate consumers using blocking commands; they are not automatically evidence of a hung server.", "Inspect execution time and command shape. Slowlog measures command execution rather than all client/network waiting and contains only retained entries above its configured threshold. Arguments can expose data, so redact them before sharing."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "Cache misses rise during a memory-pressure incident", "symptom": "An application reports more backend reads and slower responses while Redis remains reachable.", "steps": [{"action": "redis-cli -h 127.0.0.1 -p 6379 PING", "purpose": "Test the selected Redis endpoint", "detail": "Confirm the application endpoint answers; availability alone does not establish useful cache performance."}, {"action": "redis-cli -h 127.0.0.1 -p 6379 INFO memory", "purpose": "Inspect memory use and configured limits", "detail": "Compare memory with maxmemory and record the configured eviction policy."}, {"action": "redis-cli -h 127.0.0.1 -p 6379 INFO stats", "purpose": "Compare eviction and cache counters", "detail": "Collect two counter samples. In this example evicted_keys and keyspace_misses both increase during the incident."}, {"action": "redis-cli -h 127.0.0.1 -p 6379 SLOWLOG GET 10", "purpose": "Read a bounded slow-command sample", "detail": "Check retained slow commands as a separate signal; their absence does not rule out network or client delays."}], "evidence": "Illustrative findings: PONG succeeds; used_memory is near maxmemory; evicted_keys rises between samples; the workload has increasing misses.", "interpretation": "The samples support active eviction under memory pressure. They do not establish whether sizing, TTL choices or workload growth caused it, and cache misses can have other explanations.", "verification": "After the owner applies an approved sizing or retention adjustment, compare the same counter deltas under similar load. Confirm application hit behavior, latency and host memory headroom.", "escalation": "Provide the node identity, memory policy, timestamped counter deltas and redacted slow-command shapes to the cache/application owner. Avoid dumping keys or values."}}, {"id": "postgresql-session-and-blocking-investigation", "title": "PostgreSQL session and blocking investigation", "product": "PostgreSQL", "vendor": "PostgreSQL", "category": "Infrastructure", "description": "Inspect database identity, connection counts, wait events, blocking relationships and long transactions using bounded SQL queries.", "scope": "PostgreSQL 14–18 with a connected SQL client. Broader session visibility may require pg_read_all_stats or an approved monitoring role.", "prerequisites": "Connect to the intended database using your normal secure client. Run these SELECT statements in autocommit for fresh samples. Query text and session metadata can expose application data; no sessions are cancelled or terminated.", "source": "https://www.postgresql.org/docs/current/monitoring-stats.html", "sourceLabel": "PostgreSQL activity statistics", "sources": [{"label": "PostgreSQL activity statistics", "url": "https://www.postgresql.org/docs/current/monitoring-stats.html"}, {"label": "PostgreSQL system information functions", "url": "https://www.postgresql.org/docs/current/functions-info.html"}], "rows": [["SELECT current_database(), current_user, inet_server_addr(), inet_server_port();", "Confirm database and server identity"], ["SELECT datname, state, count(*) FROM pg_stat_activity GROUP BY datname, state ORDER BY count(*) DESC;", "Summarize connections by state"], ["SELECT pid, usename, state, wait_event_type, wait_event, now()-query_start AS query_age FROM pg_stat_activity WHERE state <> 'idle' AND pid <> pg_backend_pid() ORDER BY query_start LIMIT 20;", "Inspect a bounded set of active waits"], ["SELECT pid AS waiting_pid, pg_blocking_pids(pid) AS blocking_pids FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid)) > 0 LIMIT 20;", "Identify current blocking relationships"], ["SELECT pid, usename, state, now()-xact_start AS transaction_age FROM pg_stat_activity WHERE xact_start IS NOT NULL AND pid <> pg_backend_pid() ORDER BY xact_start LIMIT 20;", "Find long-lived transactions"], ["SELECT datname, numbackends, deadlocks, stats_reset FROM pg_stat_database WHERE datname = current_database();", "Inspect database counters with their reset time"]], "walkthrough": ["Match database, user and endpoint with the incident. A local Unix-domain socket can return a null network address. A connection proxy or service alias can route to different servers, so record the identity before comparing sessions.", "Compare active, idle and idle-in-transaction counts with the normal connection pool. An idle session is not necessarily a leak. Visibility depends on privileges, and this snapshot does not reveal historical peaks by itself.", "Use wait_event_type and wait_event to separate lock waiting from other waits. Query age includes time waiting and does not prove CPU use. The monitoring query excludes its own backend but may still include unrelated long-running maintenance.", "Record waiting and blocking process IDs while the issue is occurring. Relationships can change between samples. A blocker may itself be waiting on another transaction, so trace the chain with the database owner instead of terminating the first PID found.", "Compare transaction age and state with the incident. An idle-in-transaction session can retain locks or delay cleanup, but age alone does not establish impact. Associate it with application ownership before any corrective action.", "Read deadlocks as a cumulative counter since stats_reset, not a live count of blocked queries. A blocking wait is not automatically a deadlock. Compare timed samples and database logs when establishing whether new deadlocks occurred."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "Requests stall behind an idle transaction", "symptom": "Application updates hang while the database is reachable and most connections appear idle.", "steps": [{"action": "SELECT current_database(), current_user, inet_server_addr(), inet_server_port();", "purpose": "Confirm database and server identity", "detail": "Confirm the affected database and endpoint before interpreting process IDs."}, {"action": "SELECT pid, usename, state, wait_event_type, wait_event, now()-query_start AS query_age FROM pg_stat_activity WHERE state <> 'idle' AND pid <> pg_backend_pid() ORDER BY query_start LIMIT 20;", "purpose": "Inspect a bounded set of active waits", "detail": "Identify sessions reporting a lock wait during the user-visible stall."}, {"action": "SELECT pid AS waiting_pid, pg_blocking_pids(pid) AS blocking_pids FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid)) > 0 LIMIT 20;", "purpose": "Identify current blocking relationships", "detail": "Map each waiter to its blocker. In this fictional example several sessions point to one PID."}, {"action": "SELECT pid, usename, state, now()-xact_start AS transaction_age FROM pg_stat_activity WHERE xact_start IS NOT NULL AND pid <> pg_backend_pid() ORDER BY xact_start LIMIT 20;", "purpose": "Find long-lived transactions", "detail": "Inspect transaction age and state for that PID. The example blocker is idle in transaction from an application session."}], "evidence": "Illustrative findings: several active requests wait on Lock; their blocking PID is the same; that backend is idle in transaction with an older xact_start.", "interpretation": "The blocking relationship supports a transaction-lifecycle problem. Being idle alone is not the cause; the open transaction and its retained locks matter. Review the application path that failed to finish the transaction.", "verification": "After the owner completes or rolls back the transaction through the approved process, repeat the blocking query and a normal application request. Confirm the waits clear and the pattern does not immediately recur.", "escalation": "Provide the database, waiting/blocking PIDs, transaction age and incident times to the DBA and application owner. Share SQL text only through an approved private channel."}}, {"id": "mysql-connection-and-innodb-lock-investigation", "title": "MySQL connection and InnoDB lock investigation", "product": "MySQL", "vendor": "MySQL", "category": "Infrastructure", "description": "Inspect MySQL identity, connection saturation, running sessions, active InnoDB transactions and lock dependencies.", "scope": "MySQL 8.0/8.4 SQL client. Performance Schema access and PROCESS visibility depend on the monitoring account privileges.", "prerequisites": "Use an existing secure connection to the affected instance. These statements inspect metadata without killing connections or changing global settings. Queries and process metadata may contain sensitive information.", "source": "https://dev.mysql.com/doc/refman/8.4/en/show-processlist.html", "sourceLabel": "MySQL SHOW PROCESSLIST", "sources": [{"label": "MySQL SHOW PROCESSLIST", "url": "https://dev.mysql.com/doc/refman/8.4/en/show-processlist.html"}, {"label": "MySQL data_lock_waits table", "url": "https://dev.mysql.com/doc/refman/8.4/en/performance-schema-data-lock-waits-table.html"}, {"label": "MySQL INNODB_TRX table", "url": "https://dev.mysql.com/doc/refman/8.4/en/information-schema-innodb-trx-table.html"}], "rows": [["SELECT VERSION(), @@hostname, @@port, DATABASE(), CURRENT_USER();", "Identify server and authenticated account"], ["SHOW GLOBAL STATUS WHERE Variable_name IN ('Threads_connected','Threads_running','Max_used_connections','Aborted_connects');", "Inspect connection and activity counters"], ["SHOW GLOBAL VARIABLES LIKE 'max_connections';", "Read the configured connection ceiling"], ["SHOW FULL PROCESSLIST;", "Inspect visible sessions and their state"], ["SELECT trx_id, trx_state, trx_started, trx_mysql_thread_id FROM information_schema.innodb_trx ORDER BY trx_started LIMIT 20;", "Inspect older InnoDB transactions"], ["SELECT REQUESTING_ENGINE_TRANSACTION_ID, BLOCKING_ENGINE_TRANSACTION_ID FROM performance_schema.data_lock_waits LIMIT 20;", "Inspect current data-lock dependencies"]], "walkthrough": ["Compare version, server host, port and current database with the incident environment. CURRENT_USER identifies the privilege account used by MySQL, which can differ from the client-supplied login identity. A null database can simply mean none was selected.", "Compare current connections and running threads with a healthy baseline. Max_used_connections is a recorded peak; Aborted_connects is cumulative. Neither value alone proves the current application is hitting its connection limit.", "Compare the ceiling with current connections and application pool sizes across all instances. A higher ceiling is not a free performance improvement; additional sessions consume resources and can increase contention.", "Look for long-running commands, waits and repeated application users. FULL includes complete statement text, so avoid sharing raw results. Without the relevant privileges you may see only your own sessions; a short list does not prove the server is quiet.", "Compare transaction start time and state with the incident. trx_mysql_thread_id links to the connection identity shown in processlist. An old transaction is a lead, not proof that it blocks other transactions; check the wait relationships next.", "Map requesting and blocking transaction IDs to INNODB_TRX while the wait exists. This is a changing snapshot, not a history of all lock incidents, and metadata-lock waits need a different view. Multiple blockers can exist for a request."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "An update queue grows behind one transaction", "symptom": "Application updates slow down while read requests continue and the connection count is below its ceiling.", "steps": [{"action": "SHOW GLOBAL STATUS WHERE Variable_name IN ('Threads_connected','Threads_running','Max_used_connections','Aborted_connects');", "purpose": "Inspect connection and activity counters", "detail": "Record current connection/activity values before attributing the incident to connection exhaustion."}, {"action": "SHOW FULL PROCESSLIST;", "purpose": "Inspect visible sessions and their state", "detail": "Inspect session states and correlate long waits with the affected application user."}, {"action": "SELECT trx_id, trx_state, trx_started, trx_mysql_thread_id FROM information_schema.innodb_trx ORDER BY trx_started LIMIT 20;", "purpose": "Inspect older InnoDB transactions", "detail": "Record transaction IDs and their connection IDs for older open transactions."}, {"action": "SELECT REQUESTING_ENGINE_TRANSACTION_ID, BLOCKING_ENGINE_TRANSACTION_ID FROM performance_schema.data_lock_waits LIMIT 20;", "purpose": "Inspect current data-lock dependencies", "detail": "Map current lock dependencies. In this example several requesting transaction IDs point to one blocker."}], "evidence": "Illustrative findings: connections are below max_connections; several InnoDB requests wait behind one older transaction; the application pool retains its connection.", "interpretation": "The wait graph supports lock contention rather than connection saturation. Determine why the blocking transaction remains open before recommending a session termination or a timeout change.", "verification": "After the owner resolves the transaction through the approved process, repeat the lock and process views. Verify a representative update completes and that application latency returns to baseline.", "escalation": "Provide server identity, transaction/connection IDs, wait samples and start times to the DBA/application owner. Redact literal SQL values and avoid sending full processlist output publicly."}}, {"id": "nginx-reverse-proxy-upstream-investigation", "title": "NGINX reverse proxy upstream investigation", "product": "NGINX", "vendor": "NGINX", "category": "Networking", "description": "Connect configuration tests, service logs, listener state and direct upstream requests during a reverse-proxy outage.", "scope": "NGINX on a systemd-based Linux host; log paths, executable paths and service names vary by installation.", "prerequisites": "Use authorized read access and replace the log paths, app.example.com and 127.0.0.1:8080 with your configured values. nginx -t validates and opens referenced files; it does not reload running workers.", "source": "https://nginx.org/en/docs/switches.html", "sourceLabel": "NGINX command-line parameters", "sources": [{"label": "NGINX command-line parameters", "url": "https://nginx.org/en/docs/switches.html"}, {"label": "NGINX logging documentation", "url": "https://docs.nginx.com/nginx/admin-guide/monitoring/logging/"}, {"label": "NGINX proxy module", "url": "https://nginx.org/en/docs/http/ngx_http_proxy_module.html"}], "rows": [["nginx -t", "Test the selected configuration files"], ["systemctl status nginx.service --no-pager --full", "Check the proxy service state"], ["journalctl -u nginx.service --since \"30 minutes ago\" -n 100 --no-pager", "Inspect recent service-level events"], ["tail -n 100 /var/log/nginx/error.log", "Read a bounded proxy error sample"], ["ss -ltnp", "Compare proxy and upstream TCP listeners"], ["curl --silent --show-error --output /dev/null --write-out \"%{http_code}\\n\" --connect-timeout 5 --max-time 15 -H \"Host: app.example.com\" http://127.0.0.1:8080/health", "Test the configured local upstream directly"]], "walkthrough": ["Read the tested configuration path and any filename/line error. File permissions can make the test fail under a different account from the service. A successful test does not show that the running workers have loaded the same on-disk configuration.", "Record active state, PID and recent events. A running service may still return upstream errors or serve an older configuration. Compare the incident time with restarts and deployment history rather than restarting solely to change the status.", "Look for startup, reload and service errors around the incident. Application request details may be written to separate files or another logging destination, so an empty journal excerpt does not rule out proxy errors.", "Correlate the request time and upstream address with the incident. Connection refused, timeout and certificate verification errors describe different failure paths. Use the configured destination if errors go to stderr, syslog or another file.", "Check the expected proxy port and local upstream port, if the upstream is on this host. A missing local listener supports a service or binding issue. For a remote upstream, a local socket listing cannot establish whether it is listening remotely.", "Use the intended protocol, path and host header; do not substitute HTTP for an HTTPS upstream. This bypasses the proxy and therefore cannot validate the external TLS listener, proxy routing or authentication behavior."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "The public site returns 502 after an application restart", "symptom": "NGINX remains active but requests return Bad Gateway after the backend deployment.", "steps": [{"action": "nginx -t", "purpose": "Test the selected configuration files", "detail": "Check that the on-disk configuration can be parsed; distinguish this from whether it is loaded."}, {"action": "tail -n 100 /var/log/nginx/error.log", "purpose": "Read a bounded proxy error sample", "detail": "Read the exact upstream error. The example reports connection refused at 127.0.0.1:8080."}, {"action": "ss -ltnp", "purpose": "Compare proxy and upstream TCP listeners", "detail": "Compare local listeners. No process is listening on the configured upstream port in this scenario."}, {"action": "curl --silent --show-error --output /dev/null --write-out \"%{http_code}\\n\" --connect-timeout 5 --max-time 15 -H \"Host: app.example.com\" http://127.0.0.1:8080/health", "purpose": "Test the configured local upstream directly", "detail": "Test the same upstream endpoint directly. It also refuses the connection, independently of public DNS and client TLS."}], "evidence": "Illustrative findings: nginx configuration test succeeds; workers remain active; error log reports upstream connection refused; TCP 8080 has no listener.", "interpretation": "The evidence points to the backend listener or its configured address. Changing proxy timeouts will not create the missing listener. Confirm whether deployment changed the backend port or stopped the service.", "verification": "After the application owner restores the intended listener or the proxy owner approves the corrected upstream, verify direct health response and a normal request through the public hostname. Compare fresh error-log entries.", "escalation": "Provide the upstream address, request time, log error and listener result to the backend/proxy owners. Include only the relevant configuration excerpt, with credentials removed."}}, {"id": "windows-time-synchronization-investigation", "title": "Windows time synchronization investigation", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Inspect time source, synchronization status, peer configuration and measured offset before forcing a clock change.", "scope": "Windows 10/11 or Windows Server with Windows Time service. Domain hierarchy and virtualization can influence time sources.", "prerequisites": "Use the affected machine and replace dc01.corp.example with an approved reference. Some queries need elevation; stripchart sends bounded probes. This workflow does not resync, reconfigure or set the clock.", "source": "https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings", "sourceLabel": "Microsoft Windows Time tools and settings", "sources": [{"label": "Microsoft Windows Time tools and settings", "url": "https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings"}], "rows": [["Get-Service W32Time", "Check Windows Time service status"], ["w32tm /query /source", "Read the currently reported time source"], ["w32tm /query /status /verbose", "Inspect synchronization state and last success"], ["w32tm /query /configuration", "Inspect effective time configuration and origin"], ["w32tm /query /peers", "Inspect configured peer state"], ["w32tm /stripchart /computer:dc01.corp.example /samples:5 /dataonly", "Sample offset against an approved reference"]], "walkthrough": ["Record the service state on the affected host. A running service is not proof of synchronization, and a stopped service can reflect policy or trigger behavior. Correlate the state with configured time policy before proposing a restart.", "Compare the source with the intended domain hierarchy or approved external reference. A local clock source may explain lack of external discipline, but its meaning depends on the host role, virtualization platform and intended design.", "Record last successful sync, stratum, source and any error fields. An old success time can indicate ongoing failure despite the service running. Interpret timestamps in their displayed timezone and compare with the reported incident window.", "Review Type, NtpServer and settings attributed to policy versus local configuration. Domain members commonly follow domain hierarchy; manually setting public peers on every member can conflict with that design. Inspect first without changing settings.", "Compare peer addresses, mode, state and reachability context with the expected design. Peer presence does not prove recent successful synchronization. A domain-selected source and a manually configured peer list need not be identical.", "Compare several offsets rather than a single measurement. Stripchart probes use their own client behavior, so successful samples do not prove that Windows Time synchronization traffic or policy is functioning. A timeout can reflect filtering or reference availability."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "Authentication errors coincide with clock drift", "symptom": "One domain workstation reports authentication failures and its clock differs noticeably from nearby systems.", "steps": [{"action": "Get-Service W32Time", "purpose": "Check Windows Time service status", "detail": "Record Windows Time service status instead of immediately restarting it."}, {"action": "w32tm /query /source", "purpose": "Read the currently reported time source", "detail": "Compare the reported source with the expected domain hierarchy."}, {"action": "w32tm /query /status /verbose", "purpose": "Inspect synchronization state and last success", "detail": "Capture the last successful synchronization and error fields."}, {"action": "w32tm /stripchart /computer:dc01.corp.example /samples:5 /dataonly", "purpose": "Sample offset against an approved reference", "detail": "Measure offset against the approved reference. The example shows a persistent difference across all five samples."}], "evidence": "Illustrative findings: W32Time runs; the last successful sync is old; repeated offset measurements show a consistent several-minute difference.", "interpretation": "Clock drift is supported, but the samples alone do not establish its root cause or prove every authentication failure is time-related. Investigate source selection, policy, network reachability and virtualization time integration.", "verification": "After the owner restores the approved time path, confirm a recent successful sync and repeat offset samples. Retest the affected authentication flow and compare timestamps across the relevant logs.", "escalation": "Provide host role, source, policy origin, last sync and offset samples to the domain/platform owner. Coordinate any significant clock adjustment with application owners."}}, {"id": "windows-smb-share-access-investigation", "title": "Windows SMB share access investigation", "product": "Windows", "vendor": "Windows", "category": "Infrastructure", "description": "Separate TCP reachability, client SMB connections, share permissions, filesystem ACLs and server-side sessions.", "scope": "Windows SMB client and Windows file server with PowerShell SmbShare. Commands are explicitly split between client and server contexts.", "prerequisites": "Replace fs01.corp.example, Projects and D:\\Shares\\Projects. Run network/client checks on the affected client and share/ACL/session checks on the actual server with authorized read privileges.", "source": "https://learn.microsoft.com/en-us/powershell/module/smbshare/", "sourceLabel": "Microsoft SMB Share module", "sources": [{"label": "Microsoft SMB Share module", "url": "https://learn.microsoft.com/en-us/powershell/module/smbshare/"}, {"label": "Microsoft Get-SmbConnection", "url": "https://learn.microsoft.com/en-us/powershell/module/smbshare/get-smbconnection"}, {"label": "Microsoft Get-Acl", "url": "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.security/get-acl"}], "rows": [["Test-NetConnection fs01.corp.example -Port 445", "Client: test the SMB TCP endpoint"], ["Get-SmbConnection | Select-Object ServerName,ShareName,UserName,Dialect", "Client: inspect existing SMB connection identity"], ["Get-SmbShare -Name Projects | Select-Object Name,Path,Description", "Server: identify the share and backing path"], ["Get-SmbShareAccess -Name Projects", "Server: inspect share-level permissions"], ["Get-Acl -LiteralPath 'D:\\Shares\\Projects' | Format-List Owner,AccessToString", "Server: inspect the backing directory ACL"], ["Get-SmbSession | Select-Object ClientComputerName,ClientUserName,NumOpens", "Server: inspect current client sessions"]], "walkthrough": ["Check TcpTestSucceeded and the selected source address from the affected client. TCP success does not establish SMB authentication or file permissions. Name resolution failure, TCP refusal and TCP timeout require different follow-up checks.", "Compare server, share and user with the identity expected for the failing operation. Existing connections are context-dependent; run in the relevant user session. An empty list can mean no active SMB connection, not proof that the share is unavailable.", "Run on the file server and verify the actual filesystem path. A DFS namespace or alias can lead to a different server than expected, so confirm the serving host before interpreting the share. Do not create a replacement share to make the lookup succeed.", "Compare allow and deny entries with the affected account group membership. Share permissions are only one layer: filesystem ACLs, deny entries and the actual authenticated token also affect the result. Broad share access does not establish write access to files.", "Compare inherited and explicit entries on the actual failing path, not only the share root. This is an ACL listing rather than an effective-access calculation; nested group membership, deny entries and child permissions need separate evaluation.", "Match the affected client and user at the incident time. A session can exist while a particular file operation is denied. Missing sessions can reflect a failure before session establishment, idle disconnects or a different serving node."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A user can browse a share but cannot save files", "symptom": "One user opens the Projects share but receives Access Denied when saving a document.", "steps": [{"action": "Get-SmbConnection | Select-Object ServerName,ShareName,UserName,Dialect", "purpose": "Client: inspect existing SMB connection identity", "detail": "Verify which user identity the client SMB connection actually uses."}, {"action": "Get-SmbShare -Name Projects | Select-Object Name,Path,Description", "purpose": "Server: identify the share and backing path", "detail": "Confirm the serving host and the filesystem path behind Projects."}, {"action": "Get-SmbShareAccess -Name Projects", "purpose": "Server: inspect share-level permissions", "detail": "Inspect the share permissions. The fictional example grants the relevant group Change access."}, {"action": "Get-Acl -LiteralPath 'D:\\Shares\\Projects' | Format-List Owner,AccessToString", "purpose": "Server: inspect the backing directory ACL", "detail": "Inspect the actual failing directory. In this example its filesystem ACL grants that user group only read access."}], "evidence": "Illustrative findings: SMB connects as the intended user; share permissions allow changes; the target directory filesystem ACL allows read access only.", "interpretation": "The filesystem permission layer is a supported blocker in this example. Do not replace it with broad Full Control; determine the intended business access and evaluate the complete effective token and ACL.", "verification": "After the access owner approves a scoped permission correction, have the affected user create, edit and delete an approved test file in that directory. Recheck access without changing unrelated shares.", "escalation": "Provide client user context, serving node, exact directory and relevant ACL entries to the file-service/access owner. Avoid sharing file contents or full user inventories."}}, {"id": "windows-group-policy-application-investigation", "title": "Windows Group Policy application investigation", "product": "Active Directory", "vendor": "Active Directory", "category": "Identity & Microsoft 365", "description": "Compare endpoint policy results, processing events, domain GPO inventory, OU inheritance and configured settings.", "scope": "Domain-joined Windows endpoints plus a management host with RSAT GroupPolicy. User and computer policy processing are separate scopes.", "prerequisites": "Run gpresult and event-log checks on the affected endpoint; run domain GPO commands from an authorized RSAT session. Replace Workstation Baseline and the OU distinguished name. No gpupdate or policy changes are performed.", "source": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/gpresult", "sourceLabel": "Microsoft gpresult command", "sources": [{"label": "Microsoft gpresult command", "url": "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/gpresult"}, {"label": "Microsoft GroupPolicy module", "url": "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/"}, {"label": "Microsoft Get-GPInheritance", "url": "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/get-gpinheritance"}], "rows": [["gpresult /r /scope user", "Endpoint: inspect the current user policy result"], ["gpresult /r /scope computer", "Endpoint: inspect computer policy separately"], ["Get-WinEvent -LogName 'Microsoft-Windows-GroupPolicy/Operational' -MaxEvents 50", "Endpoint: read recent policy-processing events"], ["Get-GPO -All | Select-Object DisplayName,Id,GpoStatus,ModificationTime", "RSAT: inspect the domain GPO inventory"], ["Get-GPInheritance -Target 'OU=Workstations,DC=corp,DC=example'", "RSAT: inspect OU links and inherited policies"], ["Get-GPOReport -Name 'Workstation Baseline' -ReportType Xml", "RSAT: inspect the configured policy report"]], "walkthrough": ["Run in the affected user context and record applied and denied GPOs where shown. This reports the recorded processing result, not a live prediction after an administrator edits a link. A different logged-on account can produce a different result.", "Use an elevated authorized session where needed and compare the machine result with the user result. A user setting cannot be diagnosed solely from computer scope. Missing RSoP data may mean processing or visibility problems rather than no applicable GPOs.", "Correlate processing times, activity IDs and extension errors with the relevant sign-in or refresh. The latest 50 events may not include the incident, so use a bounded time filter when needed. Read event details rather than interpreting event numbers alone.", "Confirm the intended policy exists and inspect whether its user or computer settings are disabled. Inventory presence does not prove a policy is linked, readable, in scope or successfully processed on the endpoint.", "Replace the target with the computer or user actual OU and examine direct and inherited links, enforcement and inheritance behavior. This does not fully evaluate security filtering, WMI filtering or loopback processing for an individual endpoint.", "Read the relevant setting and configured filters in the XML returned to the console. This is configuration evidence, not endpoint resultant policy. Reports can contain internal paths and security details; share only the necessary excerpt."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-02", "case": {"title": "A workstation never receives its new baseline", "symptom": "A new workstation lacks the expected computer policy settings even though the baseline GPO exists in the domain.", "steps": [{"action": "gpresult /r /scope computer", "purpose": "Endpoint: inspect computer policy separately", "detail": "Capture the computer policy result from the affected endpoint, with the correct privileges."}, {"action": "Get-WinEvent -LogName 'Microsoft-Windows-GroupPolicy/Operational' -MaxEvents 50", "purpose": "Endpoint: read recent policy-processing events", "detail": "Check the corresponding processing window for errors before assuming filtering or linking is the cause."}, {"action": "Get-GPO -All | Select-Object DisplayName,Id,GpoStatus,ModificationTime", "purpose": "RSAT: inspect the domain GPO inventory", "detail": "Confirm the baseline GPO exists and its computer settings are enabled."}, {"action": "Get-GPInheritance -Target 'OU=Workstations,DC=corp,DC=example'", "purpose": "RSAT: inspect OU links and inherited policies", "detail": "Inspect the workstation actual OU. In the fictional example it is in a staging OU where the baseline is not linked or inherited."}], "evidence": "Illustrative findings: the baseline is absent from applied computer GPOs; the domain GPO is enabled; the workstation is in a staging OU without its link.", "interpretation": "The OU/link mismatch supports a scope problem. GPO existence alone does not make it applicable. Verify the intended placement and check filtering, replication and loopback if the link evidence does not explain the result.", "verification": "After the directory owner corrects placement or linking through the approved process, allow normal policy processing or an approved refresh. Repeat computer gpresult and verify the specific intended setting on the endpoint.", "escalation": "Provide endpoint identity, actual OU, GPO GUID, scope, processing time and the relevant event details to the directory owner. Avoid moving accounts or changing links merely to test a hypothesis."}}, {"id": "vcf-9-esxi-host-root-password-recovery", "title": "VCF 9 ESXi host root password recovery", "product": "VMware VCF", "vendor": "VMware VCF", "category": "Infrastructure", "description": "Recover a managed ESXi host root account through vCenter and PowerCLI, and reconcile VCF credential management.", "scope": "VCF 9 with ESXi 9 managed by a connected vCenter; this procedure changes the selected host root password.", "prerequisites": "Use an authorized vCenter administrative account and approved maintenance process. Confirm the exact host, VCF password-management policy and recovery access. The host must be connected and responding; vpxuser shell access must not be disabled. Do not record passwords in tickets or transcripts.", "source": "https://knowledge.broadcom.com/external/article/376979/reset-password-for-root-account-of-esxi.html", "sourceLabel": "Broadcom ESXi root recovery using PowerCLI", "sources": [{"label": "Broadcom ESXi root recovery using PowerCLI", "url": "https://knowledge.broadcom.com/external/article/376979/reset-password-for-root-account-of-esxi.html"}, {"label": "Broadcom configuration profile password drift", "url": "https://knowledge.broadcom.com/external/article/404104/reset-root-password-using-vsphere-config.html"}, {"label": "Broadcom ESXi recovery with another local administrator", "url": "https://knowledge.broadcom.com/external/article/409618"}], "rows": [["Connect-VIServer -Server vcsa.example.com", "Connect to the correct vCenter"], ["$hostObject = Get-VMHost -Name esx01.example.com", "Select and verify the target host"], ["$credential = Get-Credential -UserName root -Message \"Enter the new ESXi root password\"", "Collect the new password interactively"], ["$esxcli = Get-EsxCli -VMHost $hostObject -V2", "Obtain the host ESXCLI interface"], ["$args = $esxcli.system.account.set.CreateArgs(); $args.id = $credential.UserName; $args.password = $credential.GetNetworkCredential().Password; $args.passwordconfirmation = $credential.GetNetworkCredential().Password", "Prepare the account change arguments"], ["$esxcli.system.account.set.Invoke($args)", "Apply the approved root password change"]], "walkthrough": ["Authenticate interactively with an authorized administrative account and verify the vCenter identity. The target host must be managed by this vCenter and connected; do not use this method for a disconnected standalone host.", "Replace the example with the exact inventory name. Check the returned host and connection state before proceeding. If multiple vCenter connections exist, scope the command to the intended server to avoid selecting a different host.", "Enter the new root password in the secure credential prompt, following host password policy. Avoid embedding it in scripts, shell history, command lines or support tickets. The host validates its password requirements.", "This obtains the versioned interface for the selected host. Confirm the target again; the next commands prepare and execute a real password change on that host.", "This holds the password in the current PowerShell process memory. Do not print or export the argument object. Use a private session and clear credential variables after the approved operation.", "This changes the root password on the selected ESXi host. Broadcom documents a true result on success. Verify access through an approved path and reconcile SDDC Manager and configuration-profile credentials using the supported workflow."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-03", "case": {"title": "A managed host root password no longer works", "symptom": "A connected VCF-managed ESXi host rejects the recorded root password, while vCenter administrative access remains available.", "steps": [{"action": "Connect-VIServer -Server vcsa.example.com", "purpose": "Connect to the correct vCenter", "detail": "Confirm the vCenter endpoint and sign in with an authorized administrator."}, {"action": "$hostObject = Get-VMHost -Name esx01.example.com", "purpose": "Select and verify the target host", "detail": "Check the inventory name and ensure that the host is connected and responding."}, {"action": "$credential = Get-Credential -UserName root -Message \"Enter the new ESXi root password\"", "purpose": "Collect the new password interactively", "detail": "Collect the replacement password in a secure prompt without saving it in a script."}, {"action": "$esxcli = Get-EsxCli -VMHost $hostObject -V2", "purpose": "Obtain the host ESXCLI interface", "detail": "Create the ESXCLI interface for the verified host; prepare and invoke the account change only after authorization."}], "evidence": "Example: vCenter is reachable and the target host is connected, so the documented PowerCLI recovery path is available.", "interpretation": "A connected management path makes the documented host account update possible; it does not reset vCenter appliance root or automatically reconcile all VCF credential records.", "verification": "Confirm the operation returns true, test access through the approved administrative path, and use VCF credential-management remediation and configuration-profile compliance checks as applicable.", "escalation": "Escalate disconnected hosts, failed privileges or profile drift to the VCF administrator and Broadcom support. Do not repeatedly try passwords or reinstall a host as a first step."}}, {"id": "vcf-9-license-server-deployment-and-registration", "title": "VCF 9 license server deployment and registration", "product": "VMware VCF", "vendor": "VMware VCF", "category": "Infrastructure", "description": "Plan and verify the dedicated VCF License Server deployment and registration for VCF 9.1.", "scope": "VCF 9.1 and VCF Operations 9.1. Licensing architecture differs in 9.0; verify the exact release and upgrade path before deployment.", "prerequisites": "Use the release-specific Broadcom deployment guide, supported OVA and an authorized VCF administrator. Prepare the required DNS, network, certificates and capacity per the official version-specific checklist. UI labels and workflows vary by release.", "source": "https://knowledge.broadcom.com/external/article/453149/unable-to-update-license-keys-in-vcf-ope.html", "sourceLabel": "Broadcom missing License Server recovery", "sources": [{"label": "Broadcom missing License Server recovery", "url": "https://knowledge.broadcom.com/external/article/453149/unable-to-update-license-keys-in-vcf-ope.html"}, {"label": "Broadcom VCF 9.1 licensing overview", "url": "https://knowledge.broadcom.com/external/article/440471"}, {"label": "Broadcom 9.0 and 9.1 deployment distinction", "url": "https://knowledge.broadcom.com/external/article/423051/manual-deployment-of-vcf-operations-in-a.html"}], "rows": [["Verify product version and entitlement", "Identify the correct licensing architecture"], ["VCF Operations → Licenses & Registration → Manage → License Servers", "Inspect existing License Server registration"], ["Prepare the approved VCF 9.1 deployment inputs", "Validate deployment prerequisites"], ["Deploy VCF Management Services and License Server", "Deploy the supported appliance"], ["Register VCF Operations and License Server with Business Services Console", "Establish the licensing registration"], ["VCF Operations → Licenses & Registration → Version 9+", "Review and assign active entitlements"]], "walkthrough": ["Record the installed VCF and Operations releases and confirm entitlement in the Business Services Console. The dedicated License Server is a VCF 9.1 component; do not assume the same deployment workflow applies to every 9.0 environment.", "Check whether a server is already listed, its state and the existing licensing environment. Record the current registration before creating a duplicate appliance or replacing an existing server.", "Use the exact Broadcom guide for the deployment or upgrade path. Confirm supported OVA, management network, DNS records, addresses, time synchronization, certificates and required connectivity using its release-specific requirements.", "Follow the version-specific VCF deployment or upgrade workflow referenced by Broadcom. Supply the approved infrastructure and networking values, then wait for the workflow and appliance initialization to complete. Do not substitute VVF-only manual deployment instructions for VCF.", "Complete the registration procedure for both components using the appropriate connected or disconnected workflow. Confirm the appliance appears in License Servers and check registration and usage reporting status.", "Use the approved active primary entitlements for the applicable vCenter and ESXi hosts. Verify allocation, usage reporting and licensing state after synchronization; keep license keys and account details out of shared incident notes."], "kind": "Step", "level": "Intermediate", "time": 6, "updated": "2026-11-03", "case": {"title": "License allocation fails after a 9.1 upgrade", "symptom": "VCF Operations reports a usage deadline and its License Servers view has no deployed appliance.", "steps": [{"action": "Verify product version and entitlement", "purpose": "Identify the correct licensing architecture", "detail": "Confirm that this environment is actually VCF 9.1 and record its entitlement status."}, {"action": "VCF Operations → Licenses & Registration → Manage → License Servers", "purpose": "Inspect existing License Server registration", "detail": "Inspect the License Servers view and determine whether an appliance is missing or merely disconnected."}, {"action": "Prepare the approved VCF 9.1 deployment inputs", "purpose": "Validate deployment prerequisites", "detail": "Complete the exact release-specific deployment prerequisites with the infrastructure owner."}, {"action": "Deploy VCF Management Services and License Server", "purpose": "Deploy the supported appliance", "detail": "Deploy the required components through the documented VCF upgrade workflow, then register both components."}], "evidence": "Example: VCF Operations 9.1 shows no License Server and warns that a usage report is overdue.", "interpretation": "A missing appliance is a documented cause of licensing failure in VCF 9.1. Verify connectivity and registration separately when a License Server already exists.", "verification": "Confirm the server appears as registered, report usage using the approved method, and verify active allocations and host licensing state.", "escalation": "Escalate entitlement, deployment or registration errors with the VCF version, task ID and sanitized logs. For offline sites follow Broadcom disconnected licensing documentation."}}, {"id": "vcf-9-esxi-monitoring-and-troubleshooting-commands", "title": "VCF 9 ESXi monitoring and troubleshooting commands", "product": "VMware VCF", "vendor": "VMware VCF", "category": "Infrastructure", "description": "Inspect ESXi 9 identity, resources, networking, storage and time when investigating a VCF workload issue.", "scope": "ESXi 9 host in a VCF 9 environment. Commands are read-only inspection examples; privileges and available namespaces vary by release.", "prerequisites": "Use authorized ESXi Shell or SSH access to the affected host. Confirm the management context and maintenance policy before collecting output; host information and logs can contain sensitive data.", "source": "https://developer.broadcom.com/xapis/esxcli-command-reference/latest/namespace/esxcli_storage.html", "sourceLabel": "Broadcom ESXCLI storage reference", "sources": [{"label": "Broadcom ESXCLI storage reference", "url": "https://developer.broadcom.com/xapis/esxcli-command-reference/latest/namespace/esxcli_storage.html"}, {"label": "Broadcom ESXCLI network reference", "url": "https://developer.broadcom.com/xapis/esxcli-command-reference/latest/namespace/esxcli_network.html"}, {"label": "Broadcom ESXCLI system reference", "url": "https://developer.broadcom.com/xapis/esxcli-command-reference/latest/namespace/esxcli_system.html"}], "rows": [["vmware -v", "Identify the hypervisor version"], ["esxcli system uptime get", "Inspect host uptime"], ["esxcli network ip interface list", "Inspect VMkernel interfaces"], ["esxcli network nic list", "Inspect physical network adapters"], ["esxcli storage filesystem list", "Inspect mounted filesystems and capacity"], ["esxcli storage core path list", "Inspect storage path states"], ["esxtop", "Observe live host resource usage"]], "walkthrough": ["Record the installed ESXi product version and build. Compare the host with the VCF supported bill of materials before interpreting a command result or planning a change.", "Compare the uptime with the incident timeline and planned maintenance. A recent reboot can explain an interruption but does not establish its cause; correlate events and logs.", "Identify management, vMotion and storage VMkernel interfaces and their state. Compare MTU and service topology with the design; an interface being enabled does not prove end-to-end connectivity.", "Compare link status and speed with the intended uplinks and switch ports. A down link can be expected for an unused adapter; verify the host design before treating it as a fault.", "Find the datastore and compare mount state, free space and total size. A mounted datastore can still experience latency or path failures; correlate with storage paths and vCenter performance data.", "Compare device identifiers, adapters and path states with the expected multipath design. An inactive standby path may be intentional; inspect the path policy and array design before drawing conclusions.", "Run interactively and consult the ESXi version-specific documentation for display keys and counters. Compare sustained CPU, memory, disk and network pressure with a baseline; one sample does not establish the source of a VM performance issue."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-03", "case": {"title": "A datastore workload becomes slow", "symptom": "A VM on one host shows storage latency while other services remain online.", "steps": [{"action": "vmware -v", "purpose": "Identify the hypervisor version", "detail": "Record the host version and build for correlation with the VCF inventory."}, {"action": "esxcli storage filesystem list", "purpose": "Inspect mounted filesystems and capacity", "detail": "Check that the relevant datastore is mounted and has available capacity."}, {"action": "esxcli storage core path list", "purpose": "Inspect storage path states", "detail": "Compare storage path states with the approved multipath design."}, {"action": "esxtop", "purpose": "Observe live host resource usage", "detail": "Observe sustained storage latency and resource behavior during an approved incident window."}], "evidence": "Example: the datastore remains mounted, but a required path is unavailable and latency is elevated over several samples.", "interpretation": "A path issue is a plausible contributor, but a mounted datastore or one inactive path alone does not prove root cause. Correlate array health, path policy and latency across hosts.", "verification": "After the storage owner resolves the approved issue, compare path state and performance over time and verify the affected workload.", "escalation": "Provide host build, datastore identifier, timestamps, path states and performance samples to the virtualization and storage teams."}}, {"id": "vcf-9-vcenter-appliance-root-password-recovery", "title": "VCF 9 vCenter appliance root password recovery", "product": "VMware VCF", "vendor": "VMware VCF", "category": "Infrastructure", "description": "Reset a forgotten vCenter Server Appliance root password through an authorized SSO administrator and reconcile the VCF credential.", "scope": "vCenter Server Appliance 9.x in VCF. This changes the vCenter appliance OS root account, not an ESXi host root or the SSO administrator password.", "prerequisites": "Confirm the exact vCenter and approved maintenance process. Take a current backup and snapshot as required by Broadcom; for Enhanced Linked Mode follow its coordinated backup or powered-off snapshot guidance. The no-reboot method requires SSH access and an SSO user in SystemConfiguration.BashShellAdministrator; follow the linked Broadcom GRUB procedure if this access is unavailable.", "source": "https://knowledge.broadcom.com/external/article/321369/vcenter-server-appliance-root-password-r.html", "sourceLabel": "Broadcom vCenter root reset without reboot", "sources": [{"label": "Broadcom vCenter root reset without reboot", "url": "https://knowledge.broadcom.com/external/article/321369/vcenter-server-appliance-root-password-r.html"}, {"label": "Broadcom vCenter root recovery and GRUB procedure", "url": "https://knowledge.broadcom.com/external/article/322247/change-or-reset-the-root-account-passwor.html"}, {"label": "Broadcom VCF credential remediation", "url": "https://knowledge.broadcom.com/external/article/408771/vcenter-root-account-showing-disconnect.html"}], "rows": [["ssh administrator@vsphere.local@vcsa.example.com", "Connect as an authorized SSO administrator"], ["shell.set --enable true", "Enable the appliance Bash shell if needed"], ["shell", "Enter the appliance Bash shell"], ["sudo /usr/sbin/faillock --user root --reset", "Unlock root only if its account is locked"], ["sudo passwd root", "Set a new vCenter appliance root password"], ["sudo chage -l root", "Review the root password expiration details"]], "walkthrough": ["Replace the SSO domain and appliance FQDN with your own. This is an SSH login to the vCenter appliance, and the user must have the documented BashShellAdministrator membership. SSH and shell access must be permitted by your environment.", "Run in the vCenter appliance shell with an appropriately authorized SSO user. Broadcom documents this when shell access has not already been enabled. Follow local policy for any later change to the shell setting.", "Run this in the appliance shell after enabling shell access if necessary. Confirm the prompt and appliance identity before running the following commands; these commands target the vCenter appliance itself.", "Use this conditional step for a root account locked after unsuccessful login attempts. Broadcom specifies faillock for current Photon-based vCenter releases. An expired or forgotten password does not necessarily require clearing lockout.", "This changes the root password. Enter and confirm the new password interactively and check the success message; do not place passwords in commands, recordings or tickets. Coordinate the new credential with VCF password management.", "After the password change, review the account expiration and password-aging fields. This inspects the existing policy; do not disable expiration merely as a recovery shortcut. Verify a root login through an approved access path."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-03", "case": {"title": "vCenter appliance root is locked after failed logins", "symptom": "A VCF-managed vCenter 9 appliance rejects root login, while an authorized SSO administrator retains SSH and shell privileges.", "steps": [{"action": "ssh administrator@vsphere.local@vcsa.example.com", "purpose": "Connect as an authorized SSO administrator", "detail": "Confirm the target vCenter and log in with the permitted SSO administrator."}, {"action": "shell.set --enable true", "purpose": "Enable the appliance Bash shell if needed", "detail": "Enable the Bash shell if it is not already enabled, according to the access policy."}, {"action": "shell", "purpose": "Enter the appliance Bash shell", "detail": "Enter Bash and verify that the shell is running on the intended appliance."}, {"action": "sudo /usr/sbin/faillock --user root --reset", "purpose": "Unlock root only if its account is locked", "detail": "If lockout is confirmed, reset the root failure counter before changing the password."}, {"action": "sudo passwd root", "purpose": "Set a new vCenter appliance root password", "detail": "Set and confirm the new root password interactively, then check that the command reports success."}], "evidence": "Example: the authorized SSO shell is available, the root account was locked, and the password update completes successfully.", "interpretation": "The reset restores the appliance root credential; it does not change ESXi host passwords or automatically update the stored VCF management credential. If SSO shell access is unavailable, use the separate reboot and GRUB recovery procedure in the linked Broadcom article.", "verification": "Verify root login using the approved access path, review expiration, and use the supported VCF Operations password-management remediation workflow to reconcile the stored vCenter root credential. Confirm the account returns to Active; Broadcom notes status updates can take time.", "escalation": "Escalate unavailable SSO or console access, linked-mode backup questions, or failed credential reconciliation to the VCF administrator and Broadcom support. Preserve task IDs and sanitized logs without sharing passwords."}}, {"id": "ubiquiti-unifi-usw-layer-3-discovery-and-adoption", "title": "Ubiquiti UniFi USW Layer 3 discovery and adoption", "product": "Ubiquiti", "vendor": "Ubiquiti", "category": "Networking", "description": "Discover and adopt a UniFi USW switch when the UniFi Network application is on another subnet or site.", "scope": "UniFi USW switches and UniFi Network. Layer 3 discovery means management adoption across routed networks; it does not require the switch itself to support Layer 3 routing.", "prerequisites": "Use the correct UniFi site and an authorized administrator. Identify the switch management VLAN, IP address and current ownership before changing its inform target. A new or explicitly reset device can be adopted; do not factory-reset or take over an already managed production switch without an approved migration.", "source": "https://help.ui.com/hc/en-us/articles/204909754-Remote-Adoption-Layer-3", "sourceLabel": "Ubiquiti remote adoption (Layer 3)", "sources": [{"label": "Ubiquiti remote adoption (Layer 3)", "url": "https://help.ui.com/hc/en-us/articles/204909754-Remote-Adoption-Layer-3"}, {"label": "Ubiquiti device adoption", "url": "https://help.ui.com/hc/en-us/articles/360012622613-UniFi-Device-Adoption"}, {"label": "Ubiquiti device SSH access", "url": "https://help.ui.com/hc/en-us/articles/204909374-Connecting-to-UniFi-with-Debug-Tools-SSH"}, {"label": "Ubiquiti Layer 3 routing", "url": "https://help.ui.com/hc/en-us/articles/360042281174-Layer-3-Routing"}], "rows": [["Identify the USW and its management network", "Confirm switch identity, ownership and addressing"], ["Verify the UniFi Network application and site", "Select the correct controller and inform address"], ["Test-NetConnection unifi.example.com -Port 8080", "Test the inform TCP port from an equivalent network"], ["ssh <device-user>@<switch-ip>", "Connect to the USW management interface"], ["set-inform http://unifi.example.com:8080/inform", "Point the switch at the UniFi Network application"], ["UniFi Network → Devices → Ready to Adopt → Adopt", "Adopt and verify the intended switch"], ["DHCP Option 43 or DNS unifi", "Review alternate discovery methods"], ["Compare routed adoption and Layer 3 switching", "Distinguish controller discovery from packet routing"]], "walkthrough": ["Record model, MAC address, management IP, subnet, gateway and current adoption state. Check the DHCP lease or network inventory if the address is unknown. A switch already controlled by another application needs an approved migration, not an immediate reset.", "Confirm the intended UniFi Network application is running and that you are viewing the correct site. Identify its address reachable from the switch. For Official UniFi Hosting use the dashboard Copy Inform URL rather than guessing a hostname.", "Run this PowerShell example from a Windows test host on the same management VLAN and with equivalent firewall policy as the switch; replace the hostname. TcpTestSucceeded confirms only that test host can reach TCP 8080, not that the switch can. Check routing, ACLs and return traffic for the actual switch.", "Replace both placeholders and use the authorized UniFi device SSH credentials. Device SSH credentials differ from UniFi Console SSH credentials. The initial SSH example applies to a factory-default device in Ubiquiti’s remote adoption workflow; follow your approved migration process for an existing managed switch.", "Run this command in the USW SSH session, substituting the application IP or FQDN reachable from that switch. It changes the device inform target. For Official UniFi Hosting use its provided inform URL. Do not use the gateway IP unless it actually hosts or forwards the UniFi application.", "In the intended site, match the device MAC and choose Adopt. Ubiquiti notes that set-inform may need repeating after the device appears. Wait for provisioning and confirm the switch remains connected; an inform command alone does not complete adoption.", "For scaled deployments, Ubiquiti documents DHCP Option 43 and DNS resolution of unifi to the Network application. Check the options supplied on the switch management VLAN and the vendor-specific encoding. The device may try multiple inform sources, so remove unintended competing targets through an approved change.", "Discovery across subnets needs a reachable application and routed TCP 8080. Inter-VLAN routing on the switch is a separate feature available only on selected USW models; consult Ubiquiti’s Layer 3 routing guide if the switch should route client VLANs."], "kind": "Step", "level": "Intermediate", "time": 6, "updated": "2026-11-03", "case": {"title": "A branch switch does not appear in the central controller", "symptom": "A new factory-default USW has a management address on a branch VLAN. UniFi Network runs on a different subnet.", "steps": [{"action": "Identify the USW and its management network", "purpose": "Confirm switch identity, ownership and addressing", "detail": "Match the switch MAC to its management address and confirm that it is available for adoption."}, {"action": "Verify the UniFi Network application and site", "purpose": "Select the correct controller and inform address", "detail": "Identify the intended Network site and the application address reachable from the branch."}, {"action": "Test-NetConnection unifi.example.com -Port 8080", "purpose": "Test the inform TCP port from an equivalent network", "detail": "Test TCP 8080 from the switch management path or an equivalent authorized test host. In this example the equivalent test initially times out."}, {"action": "ssh <device-user>@<switch-ip>", "purpose": "Connect to the USW management interface", "detail": "After the network team corrects the approved route or firewall policy, connect to the switch with the authorized device SSH account."}, {"action": "set-inform http://unifi.example.com:8080/inform", "purpose": "Point the switch at the UniFi Network application", "detail": "Set the correct inform URL on the USW and watch the intended application for its MAC address."}, {"action": "UniFi Network → Devices → Ready to Adopt → Adopt", "purpose": "Adopt and verify the intended switch", "detail": "Adopt the switch in the intended site and repeat set-inform only if the device appears but requires the documented retry."}], "evidence": "Illustrative findings: the switch has a valid management IP; the controller is on another subnet; TCP 8080 initially times out and succeeds after an approved firewall correction.", "interpretation": "The timeout supports a connectivity investigation. A test from another host is supporting evidence, not proof of the switch path. Once connectivity works, check ownership, inform address and competing DHCP or DNS discovery settings if adoption still fails.", "verification": "Confirm the correct MAC appears in the intended site, adoption and provisioning complete, and the switch remains connected. Verify management reachability and the expected port configuration after provisioning.", "escalation": "Provide switch MAC, model, management VLAN/IP, application FQDN, inform URL without credentials, TCP 8080 test source and timestamps to the network or UniFi administrator. Avoid factory reset until ownership and an approved recovery path are established."}}, {"id": "kubernetes-service-endpoint-troubleshooting", "title": "Kubernetes service endpoint troubleshooting", "product": "Kubernetes", "vendor": "Kubernetes", "category": "Cloud", "description": "Trace a Service through selectors, pod readiness, EndpointSlices and service ports.", "scope": "Kubernetes with EndpointSlice support and kubectl read access to the target namespace.", "prerequisites": "Replace production, web, app=web and the pod name. Confirm the context and use an authorized account; these commands inspect resources without changing them.", "source": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/", "sourceLabel": "Kubernetes service debugging", "sources": [{"label": "Kubernetes service debugging", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-service/"}, {"label": "Kubernetes EndpointSlices", "url": "https://kubernetes.io/docs/concepts/services-networking/endpoint-slices/"}], "rows": [["kubectl config current-context", "Confirm the cluster context"], ["kubectl get service web -n production -o wide", "Inspect Service addresses and ports"], ["kubectl describe service web -n production", "Inspect Service selector and endpoint summary"], ["kubectl get pods -n production -l app=web -o wide --show-labels", "Inspect selected pods and readiness"], ["kubectl get endpointslice -n production -l kubernetes.io/service-name=web -o yaml", "Inspect EndpointSlice addresses and conditions"]], "walkthrough": ["Compare the selected context with the approved cluster inventory. Context names can be arbitrary local labels, so verify the endpoint through your organization’s inventory before interpreting production results.", "Record the ClusterIP, service ports and selector for the affected Service. A ClusterIP being assigned does not prove that any backend is ready or that the application is listening on its target port.", "Compare the selector, port and targetPort with the deployed application. A named target port must match the pod’s declared container port name; the summary is a starting point, not a substitute for inspecting EndpointSlices.", "Use the selector actually shown by the Service rather than assuming app=web. Check labels, readiness and node placement; a Running pod can still be unready or expose the wrong application port.", "Compare endpoint addresses, ports and readiness conditions with the intended pods. A missing or unready endpoint narrows the investigation to selection or readiness; avoid sharing full resource output if it contains internal addresses."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-07", "case": {"title": "A Service has no ready backends", "symptom": "Clients receive errors from a ClusterIP even though the web pods are running.", "steps": [{"action": "kubectl config current-context", "purpose": "Confirm the cluster context", "detail": "Verify the cluster context and production namespace before inspecting resources."}, {"action": "kubectl describe service web -n production", "purpose": "Inspect Service selector and endpoint summary", "detail": "Read the Service selector and target port from the actual Service definition."}, {"action": "kubectl get pods -n production -l app=web -o wide --show-labels", "purpose": "Inspect selected pods and readiness", "detail": "Compare selected pod labels and readiness against the selector."}, {"action": "kubectl get endpointslice -n production -l kubernetes.io/service-name=web -o yaml", "purpose": "Inspect EndpointSlice addresses and conditions", "detail": "Inspect EndpointSlices for ready addresses corresponding to those pods."}], "evidence": "Illustrative findings: the Service selects app=web, but the deployed pods have app=frontend and the EndpointSlice has no ready backends.", "interpretation": "A selector mismatch explains the empty backend list in this example. An empty list can also reflect pod readiness or other Service configuration, so inspect those separately.", "verification": "After the workload owner corrects the selector or pod labels through the approved deployment, confirm ready EndpointSlices and test the Service from an authorized client.", "escalation": "Send the namespace, Service selector, pod labels, endpoint conditions and timestamps to the application platform owner."}}, {"id": "docker-network-connectivity-inspection", "title": "Docker network connectivity inspection", "product": "Docker", "vendor": "Docker", "category": "Infrastructure", "description": "Inspect container network membership, addressing, port publication and bounded application logs.", "scope": "Docker Engine CLI against the intended local or remote Docker daemon; network behavior differs for Docker Desktop and Linux hosts.", "prerequisites": "Replace web and app-net with exact container and network names. Confirm the Docker context first; inspect output can contain internal addresses and configuration.", "source": "https://docs.docker.com/reference/cli/docker/network/inspect/", "sourceLabel": "Docker network inspect", "sources": [{"label": "Docker network inspect", "url": "https://docs.docker.com/reference/cli/docker/network/inspect/"}, {"label": "Docker network list", "url": "https://docs.docker.com/reference/cli/docker/network/ls/"}, {"label": "Docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}, {"label": "Docker published ports", "url": "https://docs.docker.com/reference/cli/docker/container/port/"}], "rows": [["docker context show", "Confirm the Docker context"], ["docker network ls", "List available Docker networks"], ["docker network inspect app-net", "Inspect a network and attached containers"], ["docker inspect --format \"{{json .NetworkSettings.Networks}}\" web", "Inspect one container’s network attachments"], ["docker port web", "Inspect published host ports"], ["docker logs --since 30m --tail 100 --timestamps web", "Review a bounded application log sample"]], "walkthrough": ["Record the active context and check it against the incident environment. A similarly named container can exist on another daemon; endpoint overrides can also affect where the CLI connects.", "Find the intended network name, ID and driver. A network existing on the daemon does not prove that the application containers are attached or that their services are responding.", "Compare the network ID, driver, subnet and listed container endpoints with the intended deployment. Treat IP addresses as implementation details that can change when containers are recreated.", "Compare the exact container’s network names and addresses with the peer’s attachments. A shared network enables a possible path but does not establish application readiness or listening ports.", "Check the host address and port mapped to the container. Published host ports and container-to-container ports are separate paths; a mapping does not prove that the process inside is listening.", "Compare connection and startup errors with the incident time. Logging drivers and retention affect what is available; redact credentials and application data before sharing any excerpts."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-07", "case": {"title": "A frontend cannot reach its backend container", "symptom": "A frontend and backend work individually, but requests between them fail after a deployment.", "steps": [{"action": "docker context show", "purpose": "Confirm the Docker context", "detail": "Confirm the CLI targets the daemon running the affected workload."}, {"action": "docker network ls", "purpose": "List available Docker networks", "detail": "List the networks and identify the expected application network."}, {"action": "docker network inspect app-net", "purpose": "Inspect a network and attached containers", "detail": "Inspect the network membership for the frontend and backend."}, {"action": "docker inspect --format \"{{json .NetworkSettings.Networks}}\" web", "purpose": "Inspect one container’s network attachments", "detail": "Compare the exact attachments of the affected container with its peer."}], "evidence": "Illustrative findings: the frontend is attached to app-net but the backend was recreated on another network.", "interpretation": "The membership mismatch is a supported explanation for the missing shared network path. Service name resolution and the backend listener still need separate verification.", "verification": "After the owner corrects the approved deployment configuration, inspect both attachments again and test the application through its normal path.", "escalation": "Provide daemon context, container IDs, network IDs and sanitized error timestamps to the deployment owner."}}, {"id": "dns-record-investigation-with-dig", "title": "DNS record investigation with dig", "product": "BIND", "vendor": "BIND", "category": "Networking", "description": "Compare DNS answers, authoritative servers, response codes and TCP fallback using dig.", "scope": "BIND 9 dig on a host with access to the intended DNS resolvers. Queries send DNS traffic.", "prerequisites": "Replace app.example.com, example.com and 192.0.2.53 with approved names and resolvers. Compare results from the affected network; public and internal DNS can intentionally differ.", "source": "https://bind9.readthedocs.io/en/latest/manpages.html#dig-dns-lookup-utility", "sourceLabel": "ISC BIND dig manual", "sources": [{"label": "ISC BIND dig manual", "url": "https://bind9.readthedocs.io/en/latest/manpages.html#dig-dns-lookup-utility"}], "rows": [["dig app.example.com A", "Query an IPv4 host record"], ["dig app.example.com AAAA", "Query the IPv6 host record"], ["dig @192.0.2.53 app.example.com A", "Query a chosen resolver"], ["dig example.com NS", "Find nameservers advertised for a zone"], ["dig +tcp @192.0.2.53 app.example.com A", "Repeat the query over TCP"], ["dig -x 192.0.2.25", "Inspect reverse DNS for an address"]], "walkthrough": ["Read the response status, answer section, TTL and responding server. NXDOMAIN and a timeout are different observations. A successful A answer does not establish application or TLS health.", "Compare any IPv6 answer with the application’s supported network path. No AAAA answer can be expected for an IPv4-only service; an answer alone does not prove IPv6 reachability.", "Replace the documentation address with an approved DNS server and compare its response with the default resolver. Differences can result from split DNS, caches or resolver configuration.", "Record the returned nameserver names and TTL, then verify authority for the actual zone with the DNS owner. An NS answer from a recursive resolver can itself be cached.", "Compare the TCP result with the normal query to help investigate transport filtering or truncated responses. A successful TCP query does not prove that every UDP path or application resolver works.", "Replace the documentation address with an authorized target. PTR data can be absent or independently managed and should not be assumed to match the forward record."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-07", "case": {"title": "Two clients receive different service addresses", "symptom": "An internal application resolves to different addresses from two client networks.", "steps": [{"action": "dig app.example.com A", "purpose": "Query an IPv4 host record", "detail": "Capture the default A answer and responding resolver from each client network."}, {"action": "dig @192.0.2.53 app.example.com A", "purpose": "Query a chosen resolver", "detail": "Query the intended internal resolver explicitly and record the answer and TTL."}, {"action": "dig app.example.com AAAA", "purpose": "Query the IPv6 host record", "detail": "Check whether an IPv6 answer changes the application path."}, {"action": "dig +tcp @192.0.2.53 app.example.com A", "purpose": "Repeat the query over TCP", "detail": "Compare TCP DNS behavior if normal queries time out or are truncated."}], "evidence": "Illustrative findings: one resolver returns the intended internal address while another returns a public address for the same name.", "interpretation": "Different answers support investigating resolver selection or split-horizon DNS. They do not by themselves establish which answer is incorrect or whether a cache is stale.", "verification": "After the DNS owner applies the approved correction, repeat queries from the affected client and verify the application by its normal hostname.", "escalation": "Provide query time, client network, resolver addresses, response codes and TTLs to the DNS owner."}}, {"id": "windows-tcp-listener-and-process-investigation", "title": "Windows TCP listener and process investigation", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Map a TCP listener to its owning process and compare local binding with a remote connectivity test.", "scope": "Windows PowerShell with the NetTCPIP module. Some process details require elevated read privileges.", "prerequisites": "Replace port 443 and server.example.com with the approved service. Run listener checks on the server and the TCP probe on an authorized client; the probe sends traffic.", "source": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-nettcpconnection", "sourceLabel": "Microsoft Get-NetTCPConnection", "sources": [{"label": "Microsoft Get-NetTCPConnection", "url": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-nettcpconnection"}, {"label": "Microsoft Test-NetConnection", "url": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection"}], "rows": [["Get-NetTCPConnection -State Listen", "List TCP listeners"], ["Get-NetTCPConnection -LocalPort 443 -State Listen", "Inspect the service port"], ["Get-NetTCPConnection -LocalPort 443 -State Listen | Select-Object LocalAddress,LocalPort,OwningProcess", "Capture listener address and process ID"], ["Get-Process -Id 1234", "Identify the process owning the listener"], ["Get-NetTCPConnection -State Established", "Inspect current established TCP connections"], ["Test-NetConnection server.example.com -Port 443 -InformationLevel Detailed", "Test TCP from an affected client"]], "walkthrough": ["Inspect local addresses, local ports and owning PIDs. A listener on loopback is not a listener on every interface. The command is a point-in-time view and does not list UDP sockets.", "Replace 443 with the intended TCP port and compare the binding with the service design. No result can mean the process is not listening at that moment or that the wrong port was inspected.", "Record the exact PID and address for the incident. An address of 127.0.0.1 is local-only; an all-interface binding is still subject to host and network policy.", "Replace 1234 with the PID from the previous result. A PID can be reused after a process exits, so collect both observations close together and confirm the application owner.", "Compare local and remote endpoints with a known healthy baseline. Existing established connections do not establish that new clients can connect or that application authentication succeeds.", "Run from the client network and inspect TcpTestSucceeded, source address and interface. A successful TCP handshake does not validate HTTP, TLS certificates or user authorization."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-07", "case": {"title": "A web service works locally but remote users time out", "symptom": "A Windows-hosted web service answers on the server itself but clients cannot connect.", "steps": [{"action": "Get-NetTCPConnection -LocalPort 443 -State Listen", "purpose": "Inspect the service port", "detail": "Check the expected listener on the server and record the port."}, {"action": "Get-NetTCPConnection -LocalPort 443 -State Listen | Select-Object LocalAddress,LocalPort,OwningProcess", "purpose": "Capture listener address and process ID", "detail": "Inspect the local bind address and PID for that listener."}, {"action": "Get-Process -Id 1234", "purpose": "Identify the process owning the listener", "detail": "Match the PID to the expected application process and confirm that it has not restarted between observations."}, {"action": "Test-NetConnection server.example.com -Port 443 -InformationLevel Detailed", "purpose": "Test TCP from an affected client", "detail": "Run the same TCP port test from an authorized affected client."}], "evidence": "Illustrative findings: the expected process listens only on 127.0.0.1:443, while a remote client TCP test fails.", "interpretation": "The loopback-only binding is a supported explanation for remote connectivity failure. Check the application’s intended exposure and firewall path before changing any setting.", "verification": "After an approved binding correction, repeat the listener and client TCP checks, then verify the normal application and TLS flow.", "escalation": "Share server identity, bind address, process ID, client source and test timestamps with the application owner."}}, {"id": "tls-certificate-inspection-with-openssl", "title": "TLS certificate inspection with OpenSSL", "product": "OpenSSL", "vendor": "OpenSSL", "category": "Cybersecurity", "description": "Inspect the presented TLS certificate, hostname validation and certificate expiration using OpenSSL.", "scope": "OpenSSL 3.x CLI and an approved TLS endpoint. Examples assume a POSIX shell and a PEM certificate file.", "prerequisites": "Replace app.example.com and server.pem with the authorized hostname and certificate file. The s_client commands contact the remote service. Never share private keys or paste secrets into commands.", "source": "https://docs.openssl.org/3.0/man1/openssl-s_client/", "sourceLabel": "OpenSSL s_client reference", "sources": [{"label": "OpenSSL s_client reference", "url": "https://docs.openssl.org/3.0/man1/openssl-s_client/"}, {"label": "OpenSSL x509 reference", "url": "https://docs.openssl.org/3.0/man1/openssl-x509/"}], "rows": [["openssl version", "Identify the OpenSSL version"], ["openssl s_client -connect app.example.com:443 -servername app.example.com -showcerts </dev/null", "Inspect the server-presented certificate chain"], ["openssl s_client -connect app.example.com:443 -servername app.example.com -verify_hostname app.example.com -verify_return_error </dev/null", "Check hostname and certificate validation"], ["openssl x509 -in server.pem -noout -subject -issuer -dates", "Inspect a saved certificate’s identity and dates"], ["openssl x509 -in server.pem -noout -ext subjectAltName", "Inspect subject alternative names"], ["openssl x509 -in server.pem -checkend 604800 -noout", "Check whether a certificate expires within seven days"]], "walkthrough": ["Record the OpenSSL release and compare supported options with the installed manual. Trust-store configuration and TLS behavior can vary across builds and platforms.", "Specify the hostname for SNI and inspect the returned certificates and handshake messages. A displayed chain is the server-provided chain, not necessarily a verified trust chain; output can include internal names.", "Use the expected DNS name for SNI and hostname verification. Trust depends on the OpenSSL trust store and any explicitly configured CA files; compare it with the client environment experiencing the issue.", "Read the subject, issuer and validity period from the public PEM certificate file. This command does not contact the server and cannot establish which certificate a load balancer is currently serving.", "Compare the DNS name clients use with the certificate subject alternative names. Hostname matching rules and wildcard scope matter; use explicit hostname verification as well as reading the extension.", "The interval is in seconds. Use the command exit status with the output and confirm the file represents the certificate in question; this is not a complete chain or hostname validation."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-07", "case": {"title": "A browser reports a certificate name mismatch", "symptom": "Users reach an HTTPS endpoint but the browser rejects the presented certificate.", "steps": [{"action": "openssl version", "purpose": "Identify the OpenSSL version", "detail": "Record the OpenSSL version and the hostname users actually enter."}, {"action": "openssl s_client -connect app.example.com:443 -servername app.example.com -showcerts </dev/null", "purpose": "Inspect the server-presented certificate chain", "detail": "Inspect the certificate presented with the expected SNI hostname."}, {"action": "openssl s_client -connect app.example.com:443 -servername app.example.com -verify_hostname app.example.com -verify_return_error </dev/null", "purpose": "Check hostname and certificate validation", "detail": "Run explicit hostname verification using the same hostname."}, {"action": "openssl x509 -in server.pem -noout -ext subjectAltName", "purpose": "Inspect subject alternative names", "detail": "Compare the public certificate subject alternative names with the requested host."}], "evidence": "Illustrative findings: the server presents a certificate for old.example.com and explicit verification for app.example.com fails.", "interpretation": "The observed hostname mismatch explains the verification failure for this connection. It does not establish whether DNS, load-balancer selection or certificate deployment caused the wrong certificate to be presented.", "verification": "After the certificate or endpoint owner corrects the approved configuration, repeat the hostname validation and test the normal browser path with trust checks enabled.", "escalation": "Provide the hostname, endpoint address, certificate issuer, validity dates and validation error to the certificate or load-balancer owner; never include private keys."}}, {"id": "windows-route-selection-and-vpn-troubleshooting", "title": "Windows route selection and VPN troubleshooting", "product": "Windows", "vendor": "Windows", "category": "Networking", "description": "Inspect route selection, interface metrics and the source path for a destination on a Windows host.", "scope": "Windows 10/11 or Windows Server with NetTCPIP PowerShell module.", "prerequisites": "Run on the affected host and replace 192.0.2.25 with the approved destination. VPN policy, route compartments and other filters can affect the observed path.", "source": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netroute", "sourceLabel": "Microsoft Get-NetRoute", "sources": [{"label": "Microsoft Get-NetRoute", "url": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netroute"}, {"label": "Microsoft Find-NetRoute", "url": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/find-netroute"}, {"label": "Microsoft Test-NetConnection", "url": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection"}], "rows": [["Get-NetIPConfiguration", "Inspect interface configuration"], ["Get-NetRoute -AddressFamily IPv4", "List IPv4 routes"], ["Get-NetIPInterface -AddressFamily IPv4", "Inspect IPv4 interface metrics"], ["Find-NetRoute -RemoteIPAddress 192.0.2.25", "Find the selected local address and route"], ["Test-NetConnection 192.0.2.25 -Port 443 -InformationLevel Detailed", "Test an approved TCP service"]], "walkthrough": ["Identify active adapters, their IP addresses and gateways. VPN and physical adapters may both be present; note the interface associated with the affected traffic.", "Compare destination prefixes, next hops, interface indexes and route metrics. The longest matching prefix matters before comparing metrics for otherwise equivalent routes.", "Compare the interface metrics and connection states with the affected route. Automatic metrics and changes in VPN state can affect selection; capture output during the incident.", "Replace the documentation address with the actual destination. Record the selected source address, route and interface, then check the return path separately.", "Run from the affected host and inspect the selected source interface and TcpTestSucceeded. A TCP connection alone does not prove that TLS or the application works."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-10", "case": {"title": "VPN users reach the wrong path", "symptom": "A user cannot connect to an internal service after enabling a VPN.", "steps": [{"action": "Get-NetIPConfiguration", "purpose": "Inspect interface configuration", "detail": "Record active addresses and gateways with the VPN connected."}, {"action": "Get-NetRoute -AddressFamily IPv4", "purpose": "List IPv4 routes", "detail": "Compare specific destination prefixes and next hops in the IPv4 route table."}, {"action": "Find-NetRoute -RemoteIPAddress 192.0.2.25", "purpose": "Find the selected local address and route", "detail": "Find the route and source address selected for the actual service address."}, {"action": "Test-NetConnection 192.0.2.25 -Port 443 -InformationLevel Detailed", "purpose": "Test an approved TCP service", "detail": "Test the approved service port and record the client source interface."}], "evidence": "Illustrative findings: a more-specific route points to the physical adapter rather than the expected VPN interface.", "interpretation": "The selected route explains the observed forward-path mismatch in this example. Verify the intended VPN configuration and return route before proposing a change.", "verification": "After the VPN owner applies an approved correction, repeat the route lookup and application test from the affected host.", "escalation": "Provide the destination, route prefixes, interface indexes and incident time to the network team."}}, {"id": "kubernetes-deployment-rollout-investigation", "title": "Kubernetes deployment rollout investigation", "product": "Kubernetes", "vendor": "Kubernetes", "category": "Cloud", "description": "Inspect deployment rollout status, ReplicaSets, pod readiness and events during a stalled release.", "scope": "kubectl and read access to Deployments, ReplicaSets, Pods and Events in the target namespace.", "prerequisites": "Replace production, web and app=web with the real namespace, Deployment and verified selector. These commands inspect resources and do not undo a rollout.", "source": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/", "sourceLabel": "Kubernetes deployments", "sources": [{"label": "Kubernetes deployments", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"label": "kubectl rollout status", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/kubectl_rollout_status/"}], "rows": [["kubectl config current-context", "Confirm the selected cluster"], ["kubectl get deployment web -n production -o wide", "Inspect deployment replica counts"], ["kubectl rollout status deployment/web -n production --watch=false", "Read current rollout status"], ["kubectl get replicasets -n production -l app=web", "Compare ReplicaSet revisions"], ["kubectl get pods -n production -l app=web -o wide", "Inspect selected pod state"], ["kubectl describe deployment web -n production", "Read conditions and recent events"]], "walkthrough": ["Compare the locally configured context with the approved cluster inventory before collecting evidence; similar context names can refer to different environments.", "Compare desired, ready, up-to-date and available replicas with the intended rollout. A Deployment object existing does not prove all new pods are serving.", "This returns the current status without an ongoing watch. If the rollout changes, repeat the command and correlate the output with Deployment conditions and event timestamps.", "Use the actual Deployment selector, which may differ from this example. Compare desired, current and ready counts to distinguish old replicas from the newest rollout.", "Review readiness, restarts and node placement for the selected pods. Running is not equivalent to ready; inspect the specific pod further when status or readiness is unexpected.", "Compare available and progressing conditions and recent events with the rollout window. Events are temporary and can be aggregated; use centralized logs for older evidence."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-10", "case": {"title": "A rollout stalls with unavailable replicas", "symptom": "A new application release remains partially available after deployment.", "steps": [{"action": "kubectl config current-context", "purpose": "Confirm the selected cluster", "detail": "Verify the current context and intended namespace before inspecting the deployment."}, {"action": "kubectl get deployment web -n production -o wide", "purpose": "Inspect deployment replica counts", "detail": "Record desired and available replica counts during the incident."}, {"action": "kubectl get replicasets -n production -l app=web", "purpose": "Compare ReplicaSet revisions", "detail": "Compare old and new ReplicaSet counts using the verified selector."}, {"action": "kubectl get pods -n production -l app=web -o wide", "purpose": "Inspect selected pod state", "detail": "Inspect readiness and restart status for the pods belonging to the new revision."}], "evidence": "Illustrative findings: old replicas remain ready while the new ReplicaSet has zero ready pods.", "interpretation": "The rollout is waiting on new replicas in this example. Pod events and logs are needed to distinguish image, configuration, scheduling or readiness failures.", "verification": "After the application owner resolves the cause, repeat the rollout status and confirm expected available replicas and a normal application request.", "escalation": "Send Deployment and ReplicaSet identities, conditions and sanitized event times to the platform owner."}}, {"id": "docker-compose-service-state-investigation", "title": "Docker Compose service state investigation", "product": "Docker", "vendor": "Docker", "category": "Infrastructure", "description": "Inspect the effective Compose service model, container state and recent service logs.", "scope": "Docker Compose v2 in a trusted project directory, connected to the intended Docker daemon.", "prerequisites": "Use the same Compose files, project name and environment as the deployment. Configuration and logs can expose secrets; these commands do not start, stop or recreate services.", "source": "https://docs.docker.com/reference/cli/docker/compose/config/", "sourceLabel": "Docker Compose config", "sources": [{"label": "Docker Compose config", "url": "https://docs.docker.com/reference/cli/docker/compose/config/"}, {"label": "Docker Compose ps", "url": "https://docs.docker.com/reference/cli/docker/compose/ps/"}, {"label": "Docker Compose logs", "url": "https://docs.docker.com/reference/cli/docker/compose/logs/"}], "rows": [["docker context show", "Confirm the active Docker context"], ["docker compose config --services", "List services in the effective model"], ["docker compose config --quiet", "Validate the effective Compose model"], ["docker compose ps --all", "Inspect project container states"], ["docker compose logs --since 30m --tail 100 --timestamps web", "Inspect a bounded service log window"]], "walkthrough": ["Compare the context with the deployment host. Environment or command-line endpoint overrides may change the actual daemon, so confirm the approved operating context before drawing conclusions.", "Run from the intended project and compare the resulting service names with deployment documentation. File selection, profiles and environment can change the model.", "This checks whether Compose can parse and resolve the model without printing it. A valid model does not prove that images, networks, credentials or application dependencies work.", "Compare the service name, state and exit information with the expected project. This view depends on the selected project; an empty result does not establish that no containers exist on the daemon.", "Replace web with the affected service and correlate the first relevant error with the failure time. Logging driver and retention settings affect availability; redact secrets before sharing."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-10", "case": {"title": "A Compose service exits after a configuration change", "symptom": "A web service exits immediately after a deployment configuration update.", "steps": [{"action": "docker context show", "purpose": "Confirm the active Docker context", "detail": "Confirm the active daemon and intended Compose project before investigation."}, {"action": "docker compose config --services", "purpose": "List services in the effective model", "detail": "List effective services using the same files and project context as the deployment."}, {"action": "docker compose ps --all", "purpose": "Inspect project container states", "detail": "Capture the affected container state and exit information."}, {"action": "docker compose logs --since 30m --tail 100 --timestamps web", "purpose": "Inspect a bounded service log window", "detail": "Review the bounded service logs around the first failed start."}], "evidence": "Illustrative findings: the intended project contains web, its container exits, and its logs report a missing required setting.", "interpretation": "A missing application setting is the leading hypothesis in this example. Compose model validation alone cannot establish that application-level settings are sufficient.", "verification": "After the owner corrects the deployment through the approved process, verify stable container state and a normal service request.", "escalation": "Provide context, project, service name, exit time and a sanitized error excerpt to the application owner."}}, {"id": "linux-memory-pressure-investigation", "title": "Linux memory pressure investigation", "product": "Linux", "vendor": "Linux", "category": "Infrastructure", "description": "Compare available memory, swap, process usage and kernel messages when a Linux host slows down.", "scope": "Linux with procps utilities and systemd journal access. Container limits can differ from host totals.", "prerequisites": "Use authorized read access on the affected host. Commands provide point-in-time evidence and do not clear caches, kill processes or change memory limits.", "source": "https://man7.org/linux/man-pages/man1/free.1.html", "sourceLabel": "procps free manual", "sources": [{"label": "procps free manual", "url": "https://man7.org/linux/man-pages/man1/free.1.html"}, {"label": "procps ps manual", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"label": "systemd journalctl manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}], "rows": [["free -h", "Inspect memory and swap totals"], ["cat /proc/meminfo", "Read detailed kernel memory accounting"], ["ps -eo pid,comm,rss --sort=-rss", "List processes by resident memory"], ["journalctl -k --since \"1 hour ago\" -n 100 --no-pager", "Inspect recent kernel messages"], ["systemctl --failed --no-pager", "List systemd units in failed state"]], "walkthrough": ["Compare the available memory estimate and swap use with the host baseline. Low free memory by itself is not proof of pressure because the kernel also uses memory for cache.", "Inspect MemAvailable, SwapTotal and SwapFree alongside the host’s context. Values are point-in-time counters; compare repeated samples and monitoring rather than inferring a trend from one reading.", "Compare resident set sizes and identify process owners. RSS values are not additive accounting of unique memory because shared pages can be counted in multiple processes.", "Look for memory-related events within the incident window. An absent message does not exclude prior pressure if journal permissions, retention or the selected time window hide it.", "Check for failed services around the incident. A failed unit does not by itself establish an out-of-memory cause; correlate service and kernel logs with timestamps."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-10", "case": {"title": "A server slows down and a service exits", "symptom": "An application stops responding during a period of unusually high host memory consumption.", "steps": [{"action": "free -h", "purpose": "Inspect memory and swap totals", "detail": "Capture available memory and swap usage at the time of the incident."}, {"action": "ps -eo pid,comm,rss --sort=-rss", "purpose": "List processes by resident memory", "detail": "Identify the highest resident-memory processes and their owners."}, {"action": "journalctl -k --since \"1 hour ago\" -n 100 --no-pager", "purpose": "Inspect recent kernel messages", "detail": "Check the kernel journal for memory-related events during the same window."}, {"action": "systemctl --failed --no-pager", "purpose": "List systemd units in failed state", "detail": "Inspect failed unit status and correlate it with the application timeline."}], "evidence": "Illustrative findings: available memory drops sharply and the kernel journal records an out-of-memory kill affecting the application.", "interpretation": "The kernel event supports a memory-kill diagnosis for that process. Determine whether workload growth, limits or another cause led to the pressure before changing sizing.", "verification": "After the owner applies an approved correction, monitor available memory and application stability over a comparable workload period.", "escalation": "Send timed memory samples, affected process identity and relevant redacted kernel messages to the system and application owners."}}, {"id": "openssh-client-connection-investigation", "title": "OpenSSH client connection investigation", "product": "OpenSSH", "vendor": "OpenSSH", "category": "Cybersecurity", "description": "Inspect OpenSSH client configuration, host keys and verbose connection stages without weakening host verification.", "scope": "OpenSSH client on a workstation with authorized access to the target host.", "prerequisites": "Replace admin and server.example.com with your approved account and host. Connection attempts contact the server. Verify host-key fingerprints through a trusted independent channel before accepting any change.", "source": "https://man.openbsd.org/ssh.1", "sourceLabel": "OpenSSH client manual", "sources": [{"label": "OpenSSH client manual", "url": "https://man.openbsd.org/ssh.1"}, {"label": "OpenSSH client configuration manual", "url": "https://man.openbsd.org/ssh_config.5"}, {"label": "OpenSSH ssh-keygen manual", "url": "https://man.openbsd.org/ssh-keygen.1"}], "rows": [["ssh -V", "Identify the client version"], ["ssh -G server.example.com", "Inspect effective client configuration"], ["ssh-keygen -F server.example.com", "Find known-host entries"], ["ssh -vvv admin@server.example.com", "Inspect a connection attempt"], ["ssh -o ConnectTimeout=10 admin@server.example.com", "Attempt a bounded connection"]], "walkthrough": ["Record the OpenSSH client version when investigating configuration or algorithm compatibility. A version alone does not establish which algorithms the server offers.", "Read the resolved host name, port, user and identity settings after client configuration is applied. This is a local configuration inspection; it does not connect or prove the destination is reachable.", "Inspect existing known_hosts matches for the target. An entry or fingerprint mismatch requires verification through an independent trusted channel; do not automatically remove the existing key.", "Review verbose connection, host-key and authentication stages to locate the failure. Logs can reveal usernames, network topology and key paths, so sanitize them before sharing.", "Use an authorized account and expected host name. ConnectTimeout limits connection establishment and the initial handshake, not necessarily every later interactive authentication step."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-10", "case": {"title": "SSH fails after a server migration", "symptom": "An administrator sees a host-key warning when connecting to a recently migrated server.", "steps": [{"action": "ssh -V", "purpose": "Identify the client version", "detail": "Record the client version and operating environment before comparing behavior."}, {"action": "ssh -G server.example.com", "purpose": "Inspect effective client configuration", "detail": "Inspect the effective destination, port and user to ensure the intended host is selected."}, {"action": "ssh-keygen -F server.example.com", "purpose": "Find known-host entries", "detail": "Find the existing known-host entry and compare its fingerprint with trusted inventory."}, {"action": "ssh -vvv admin@server.example.com", "purpose": "Inspect a connection attempt", "detail": "If appropriate, capture the connection stage without accepting an unverified replacement key."}], "evidence": "Illustrative findings: the resolved destination is correct, but its presented host key differs from the previously recorded key.", "interpretation": "A mismatch may be legitimate after migration or indicate an unexpected endpoint. The warning alone cannot distinguish those cases; confirm the new fingerprint out of band.", "verification": "After the administrator verifies and updates host-key trust using the approved process, reconnect with verification enabled and confirm the intended server identity.", "escalation": "Provide the hostname, resolved address and independently verified fingerprints to the server owner; do not share private keys."}}, {"id": "windows-firewall-policy-inspection", "title": "Windows firewall policy inspection", "product": "Windows", "vendor": "Windows", "category": "Cybersecurity", "description": "Inspect active Windows firewall profiles, rules and port filters when investigating a blocked connection.", "scope": "Windows with the NetSecurity PowerShell module; policy visibility depends on permissions.", "prerequisites": "Run on the affected endpoint with authorized read access. Replace the example rule display name. These commands inspect policy and do not change rules.", "source": "https://learn.microsoft.com/en-us/powershell/module/netsecurity/get-netfirewallprofile", "sourceLabel": "Microsoft firewall profiles", "sources": [{"label": "Microsoft firewall profiles", "url": "https://learn.microsoft.com/en-us/powershell/module/netsecurity/get-netfirewallprofile"}, {"label": "Microsoft firewall rules", "url": "https://learn.microsoft.com/en-us/powershell/module/netsecurity/get-netfirewallrule"}, {"label": "Microsoft port filters", "url": "https://learn.microsoft.com/en-us/powershell/module/netsecurity/get-netfirewallportfilter"}], "rows": [["Get-NetConnectionProfile", "Identify network connection profiles"], ["Get-NetFirewallProfile -PolicyStore ActiveStore", "Inspect effective profile settings"], ["Get-NetFirewallRule -PolicyStore ActiveStore -Enabled True -Direction Inbound", "List enabled inbound rules"], ["Get-NetFirewallRule -PolicyStore ActiveStore -DisplayName 'Example service' | Get-NetFirewallPortFilter", "Inspect ports for a selected rule"], ["Get-NetFirewallRule -PolicyStore ActiveStore -DisplayName 'Example service' | Get-NetFirewallAddressFilter", "Inspect address restrictions for a selected rule"]], "walkthrough": ["Record the interface and network category for the affected path. An endpoint can have multiple interfaces with different categories, so identify which one carries the incident traffic.", "Compare enabled state and default inbound and outbound actions for the active profile. Profile settings alone do not evaluate every rule, application filter or IPsec condition.", "Review relevant rule names, actions and profiles in the active policy store. A matching display name does not establish that every address, port or program filter matches the connection.", "Replace the display name with the confirmed rule. Check protocol and local and remote port filters, then separately inspect address, program, service and profile conditions.", "Compare allowed local and remote address ranges with the actual flow. Effective policy can include multiple rules, block rules and other conditions; this is not a complete effective-access calculation."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-11", "case": {"title": "A service is reachable from one subnet only", "symptom": "A Windows service accepts connections from one approved subnet but not another.", "steps": [{"action": "Get-NetConnectionProfile", "purpose": "Identify network connection profiles", "detail": "Identify the network profile on the interface carrying the affected connection."}, {"action": "Get-NetFirewallProfile -PolicyStore ActiveStore", "purpose": "Inspect effective profile settings", "detail": "Review effective defaults for that profile in the active store."}, {"action": "Get-NetFirewallRule -PolicyStore ActiveStore -DisplayName 'Example service' | Get-NetFirewallPortFilter", "purpose": "Inspect ports for a selected rule", "detail": "Check the relevant service rule protocol and port filter."}, {"action": "Get-NetFirewallRule -PolicyStore ActiveStore -DisplayName 'Example service' | Get-NetFirewallAddressFilter", "purpose": "Inspect address restrictions for a selected rule", "detail": "Compare the rule remote address filter with both client subnets."}], "evidence": "Illustrative findings: the rule covers the correct TCP port but its remote address filter includes only the working subnet.", "interpretation": "The address restriction is a supported explanation in this example. Other matching block rules or network controls still need consideration before changing policy.", "verification": "After the policy owner approves a scoped correction, test from both authorized subnets and inspect the active rule again.", "escalation": "Provide the endpoint, interface profile, connection tuple and relevant sanitized rule filters to the security owner."}}, {"id": "kubernetes-persistent-volume-claim-investigation", "title": "Kubernetes persistent volume claim investigation", "product": "Kubernetes", "vendor": "Kubernetes", "category": "Cloud", "description": "Investigate a pending persistent volume claim using claim events, storage classes and bound volumes.", "scope": "Kubernetes cluster with kubectl read access to PVCs, pods and relevant storage resources.", "prerequisites": "Replace production and data-web with the actual namespace and claim. Confirm cluster context and use authorized read access; these commands do not delete claims, volumes or workloads.", "source": "https://kubernetes.io/docs/concepts/storage/persistent-volumes/", "sourceLabel": "Kubernetes persistent volumes", "sources": [{"label": "Kubernetes persistent volumes", "url": "https://kubernetes.io/docs/concepts/storage/persistent-volumes/"}, {"label": "Kubernetes storage classes", "url": "https://kubernetes.io/docs/concepts/storage/storage-classes/"}, {"label": "kubectl describe", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_describe/"}], "rows": [["kubectl config current-context", "Confirm the cluster context"], ["kubectl get pvc data-web -n production -o wide", "Inspect the claim status"], ["kubectl describe pvc data-web -n production", "Inspect claim details and events"], ["kubectl get storageclass", "List storage classes and binding modes"], ["kubectl get pods -n production -o wide", "Inspect workload scheduling"], ["kubectl get pv", "Inspect persistent volumes"]], "walkthrough": ["Compare the locally named context with the authorized cluster inventory. Similar local names can refer to different environments, so establish the target before interpreting resources.", "Record status, storage class, requested size and any bound volume. A Pending claim is a symptom; its events and binding mode provide the next clues.", "Read the requested access modes, storage class and recent provisioning events. Some classes wait for a consumer to be scheduled before binding; Pending can therefore be an intentional intermediate state.", "Identify the claim’s named storage class and its volume binding mode. A missing default class or a different class name can lead to different provisioning behavior.", "Identify the pod using the claim and inspect its scheduling state. With WaitForFirstConsumer, placement and storage topology influence provisioning; do not treat an unbound claim in isolation as a failure.", "If the claim is bound, match its volume name to the PV and compare capacity, access mode and reclaim policy. A PV object does not prove that a filesystem is mounted or the backing storage is healthy."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-11", "case": {"title": "A workload is pending with an unbound claim", "symptom": "A new application pod waits while its data claim remains Pending.", "steps": [{"action": "kubectl config current-context", "purpose": "Confirm the cluster context", "detail": "Confirm cluster and namespace before inspecting the affected workload."}, {"action": "kubectl get pvc data-web -n production -o wide", "purpose": "Inspect the claim status", "detail": "Capture the exact claim status and storage class name."}, {"action": "kubectl describe pvc data-web -n production", "purpose": "Inspect claim details and events", "detail": "Read recent claim events and requested access modes."}, {"action": "kubectl get storageclass", "purpose": "List storage classes and binding modes", "detail": "Compare the storage class binding mode with the pod scheduling state."}], "evidence": "Illustrative findings: the claim uses WaitForFirstConsumer and the consumer pod cannot be scheduled because no node satisfies its placement constraints.", "interpretation": "The claim waiting for scheduling is consistent with the configured binding mode in this example. Resolve the scheduling evidence before assuming the storage provisioner is broken.", "verification": "After the workload owner resolves the approved scheduling issue, verify the claim binds, the pod starts and the application can access its expected data.", "escalation": "Provide namespace, claim name, storage class, binding mode and sanitized events to the platform and storage owners."}}, {"id": "git-branch-and-upstream-tracking-inspection", "title": "Git branch and upstream tracking inspection", "product": "Git", "vendor": "Git", "category": "IT fundamentals", "description": "Inspect the current branch, upstream tracking and local commit differences before synchronizing a repository.", "scope": "Git in a trusted local repository. Remote-tracking information reflects the last completed fetch.", "prerequisites": "Run in the intended checkout. These commands are read-only local inspections and do not fetch, merge, reset or push.", "source": "https://git-scm.com/docs/git-branch", "sourceLabel": "Git branch manual", "sources": [{"label": "Git branch manual", "url": "https://git-scm.com/docs/git-branch"}, {"label": "Git rev-parse manual", "url": "https://git-scm.com/docs/git-rev-parse"}, {"label": "Git rev-list manual", "url": "https://git-scm.com/docs/git-rev-list"}], "rows": [["git status --short --branch", "Inspect the branch and worktree"], ["git branch -vv", "Inspect local branch tracking"], ["git branch -r", "List local remote-tracking references"], ["git rev-parse --abbrev-ref --symbolic-full-name '@{upstream}'", "Identify the current branch upstream"], ["git rev-list --left-right --count 'HEAD...@{upstream}'", "Count local and upstream-only commits"]], "walkthrough": ["Read the branch header and file status before planning synchronization. Ahead and behind values depend on the locally stored upstream reference, which may be stale.", "Compare each local branch with its configured upstream and most recent commit. Missing upstream configuration is different from an upstream branch having no new commits.", "Review the remote-tracking names known to this checkout. This command does not contact the server and can show stale references until a separately authorized fetch or prune.", "This resolves the configured upstream reference; it can fail for a detached HEAD or a branch without upstream tracking. The single quotes are accepted by PowerShell and POSIX shells.", "The two counts compare the local references only; fetch separately before using them as a current server comparison. Quoting protects the upstream syntax in PowerShell."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-11", "case": {"title": "A branch appears ahead and behind", "symptom": "A developer sees unexpected divergence from the tracked branch before publishing.", "steps": [{"action": "git status --short --branch", "purpose": "Inspect the branch and worktree", "detail": "Record branch status and any uncommitted work before choosing a synchronization strategy."}, {"action": "git branch -vv", "purpose": "Inspect local branch tracking", "detail": "Confirm the intended upstream configured for the current branch."}, {"action": "git rev-parse --abbrev-ref --symbolic-full-name '@{upstream}'", "purpose": "Identify the current branch upstream", "detail": "Resolve the upstream reference explicitly using the correct shell quoting."}, {"action": "git rev-list --left-right --count 'HEAD...@{upstream}'", "purpose": "Count local and upstream-only commits", "detail": "Compare local and upstream-only commit counts, remembering that the upstream reference can be stale."}], "evidence": "Illustrative findings: the current branch tracks origin/main and the locally stored references each contain commits absent from the other.", "interpretation": "The local references have diverged in this example. This does not show current server state until the upstream reference is refreshed, and it does not prescribe a merge or rebase.", "verification": "After an authorized fetch and an agreed integration method, inspect the resulting history and ensure the intended changes are preserved.", "escalation": "Provide branch name, upstream and commit identifiers to the repository owner without rewriting or discarding work."}}, {"id": "linux-ipv6-host-path-inspection", "title": "Linux IPv6 host path inspection", "product": "Linux", "vendor": "Linux", "category": "Networking", "description": "Inspect IPv6 addresses, route selection, neighbors and listeners on a Linux host.", "scope": "Linux with iproute2 and ss. Results depend on the host network namespace.", "prerequisites": "Run in the affected host or workload network namespace. Replace 2001:db8::25 with an authorized destination; these commands inspect local state and do not send probes.", "source": "https://man7.org/linux/man-pages/man8/ip-address.8.html", "sourceLabel": "Linux ip-address manual", "sources": [{"label": "Linux ip-address manual", "url": "https://man7.org/linux/man-pages/man8/ip-address.8.html"}, {"label": "Linux ip-route manual", "url": "https://man7.org/linux/man-pages/man8/ip-route.8.html"}, {"label": "Linux ip-neighbour manual", "url": "https://man7.org/linux/man-pages/man8/ip-neighbour.8.html"}, {"label": "Linux ss manual", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}], "rows": [["ip -6 address show", "Inspect IPv6 addresses"], ["ip -6 route show", "List IPv6 routes"], ["ip -6 route get 2001:db8::25", "Inspect route selection for a destination"], ["ip -6 neigh show", "Inspect IPv6 neighbor state"], ["ss -6 -ltn", "List IPv6 TCP listeners"]], "walkthrough": ["Compare global and link-local addresses, prefixes and address states with the intended interface. A link-local address is scoped to its link and does not establish global connectivity.", "Identify destination prefixes, default routes and next-hop interfaces. A route being present does not prove that the next hop or remote application is reachable.", "Replace the documentation address with the real approved IPv6 destination. Note the selected interface, source address and next hop; check the return path and policy separately.", "Compare the selected directly connected next hop with its neighbor state. An absent entry can be normal before traffic; FAILED or INCOMPLETE states are clues to investigate on the local link.", "Compare local IPv6 listener addresses and ports with the intended application. IPv4-mapped behavior can depend on socket and system settings, so verify the actual service configuration."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-11", "case": {"title": "An application fails only over IPv6", "symptom": "Clients receive an IPv6 address for a service but their IPv6 connection fails.", "steps": [{"action": "ip -6 address show", "purpose": "Inspect IPv6 addresses", "detail": "Confirm the affected host has the expected IPv6 address on the intended interface."}, {"action": "ip -6 route show", "purpose": "List IPv6 routes", "detail": "Inspect the IPv6 routing table for the relevant destination prefix."}, {"action": "ip -6 route get 2001:db8::25", "purpose": "Inspect route selection for a destination", "detail": "Check the selected source address, route and next hop for the service."}, {"action": "ip -6 neigh show", "purpose": "Inspect IPv6 neighbor state", "detail": "Inspect neighbor state for the directly connected next hop."}], "evidence": "Illustrative findings: the destination route selects the intended interface, but the next-hop neighbor remains INCOMPLETE during the incident.", "interpretation": "The neighbor state points toward a local-link or peer-resolution investigation in this example. It does not establish a specific switch, firewall or host fault.", "verification": "After the network owner resolves the issue, repeat the route and neighbor checks and test the approved application over IPv6.", "escalation": "Provide the host namespace, interface, selected route, next-hop address and timestamped neighbor state to the network owner."}}, {"id": "linux-systemd-timer-troubleshooting", "title": "Linux systemd timer troubleshooting", "product": "Linux", "vendor": "Linux", "category": "Infrastructure", "description": "Inspect timer schedules, unit settings and service results when scheduled work does not run.", "scope": "Linux distributions using systemd timers; commands inspect the system manager.", "prerequisites": "Replace backup.timer and backup.service with the actual units. Use an account permitted to read their journals. These commands do not start or change timers.", "source": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html", "sourceLabel": "systemctl manual", "sources": [{"label": "systemctl manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}, {"label": "systemd.timer manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.timer.html"}, {"label": "journalctl manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}], "rows": [["systemctl list-timers --all --no-pager", "List loaded timers and next runs"], ["systemctl status backup.timer --no-pager --full", "Inspect a particular timer"], ["systemctl cat backup.timer", "Review the timer and its drop-ins"], ["systemctl status backup.service --no-pager --full", "Inspect the triggered service"], ["journalctl -u backup.service --since \"24 hours ago\" -n 100 --no-pager", "Read the service journal"]], "walkthrough": ["Compare NEXT and LAST with the expected schedule. The list includes loaded timers; absence alone does not prove no timer unit file exists on disk.", "Check the loaded path, active state and trigger information. A timer being active does not prove its associated service completed successfully.", "Inspect the unit and drop-in files on disk, including scheduling directives and any Unit target. On-disk changes may differ from the manager state until configuration is reloaded.", "Compare the last result and exit status with the expected job. A successful start is not necessarily a successful backup; verify the job output and backup artifact.", "Correlate the first error with the expected execution window. Journal permissions and retention affect which records appear, so no entries are not proof that nothing happened."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-11", "case": {"title": "A scheduled backup is missing", "symptom": "The backup owner reports that the expected daily job did not produce a new backup.", "steps": [{"action": "systemctl list-timers --all --no-pager", "purpose": "List loaded timers and next runs", "detail": "Record the timer listing and compare the next and last trigger with the schedule."}, {"action": "systemctl status backup.timer --no-pager --full", "purpose": "Inspect a particular timer", "detail": "Inspect the exact timer active state and configured target."}, {"action": "systemctl status backup.service --no-pager --full", "purpose": "Inspect the triggered service", "detail": "Check the corresponding service result and timestamp."}, {"action": "journalctl -u backup.service --since \"24 hours ago\" -n 100 --no-pager", "purpose": "Read the service journal", "detail": "Review service journal messages from the reported job window."}], "evidence": "Illustrative findings: the timer fired on schedule, but the backup service exited with an error.", "interpretation": "The timer fired in this example; the service failure is the next investigation. The result does not establish that older backups are restorable.", "verification": "After an approved service correction, verify the next scheduled run, inspect its result and validate the backup through the normal restore-check process.", "escalation": "Provide unit names, trigger time, exit result and sanitized error messages to the backup owner."}}, {"id": "active-directory-domain-controller-discovery", "title": "Active Directory domain controller discovery", "product": "Active Directory", "vendor": "Active Directory", "category": "Identity & Microsoft 365", "description": "Inspect domain controller discovery, DNS service records and site selection from a Windows client.", "scope": "Windows with the ActiveDirectory and DnsClient PowerShell modules. Directory visibility depends on authorization.", "prerequisites": "Run on the affected domain-connected client and replace corp.example with the actual domain. Discovery and DNS queries contact directory services; no directory settings are changed.", "source": "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontroller", "sourceLabel": "Microsoft domain controller discovery", "sources": [{"label": "Microsoft domain controller discovery", "url": "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-addomaincontroller"}, {"label": "Microsoft nltest", "url": "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/cc731935(v=ws.11)"}, {"label": "Microsoft Resolve-DnsName", "url": "https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname"}], "rows": [["Get-ADDomain", "Inspect the current domain context"], ["Get-ADDomainController -Filter *", "List visible domain controllers"], ["Get-ADDomainController -Discover -DomainName 'corp.example'", "Discover a domain controller"], ["nltest /dsgetsite", "Identify the client AD site"], ["Resolve-DnsName -Name '_ldap._tcp.dc._msdcs.corp.example' -Type SRV -DnsOnly", "Inspect domain controller DNS records"]], "walkthrough": ["Record the domain DNS root and relevant controller information. The command depends on directory access and current credentials; a failure does not uniquely identify a DNS issue.", "Compare controller names and site properties with the approved inventory. This lists directory objects visible to the account, not proof that each controller currently accepts client requests.", "Replace the domain and record the selected controller and site returned by discovery. Client location, DNS and directory configuration can affect the result; one successful discovery does not establish replication health.", "Run on the affected client and record the site that Windows reports. Compare it with the expected subnet-to-site mapping; an incorrect or unknown site can affect controller selection.", "Replace the domain and inspect SRV targets and ports returned by the client DNS path. An advertised record alone does not prove that a target is reachable or healthy."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-13", "case": {"title": "A branch client chooses an unexpected controller", "symptom": "A branch workstation discovers a distant controller and experiences slow domain sign-in.", "steps": [{"action": "Get-ADDomain", "purpose": "Inspect the current domain context", "detail": "Confirm the domain context and directory access from the affected workstation."}, {"action": "Get-ADDomainController -Discover -DomainName 'corp.example'", "purpose": "Discover a domain controller", "detail": "Record the controller and site returned by domain controller discovery."}, {"action": "nltest /dsgetsite", "purpose": "Identify the client AD site", "detail": "Compare the reported client site with the branch network inventory."}, {"action": "Resolve-DnsName -Name '_ldap._tcp.dc._msdcs.corp.example' -Type SRV -DnsOnly", "purpose": "Inspect domain controller DNS records", "detail": "Inspect the domain controller SRV records returned by the client resolver."}], "evidence": "Illustrative findings: the client reports an unexpected AD site and discovers a controller associated with that site.", "interpretation": "Site selection is a useful lead in this example; verify subnet mappings, DNS and controller availability before changing directory configuration.", "verification": "After the directory owner corrects the approved configuration, repeat discovery and verify the normal sign-in experience from the branch.", "escalation": "Provide the client subnet, reported site, discovered controller and timestamped DNS results to the directory owner."}}, {"id": "docker-volume-mount-inspection", "title": "Docker volume mount inspection", "product": "Docker", "vendor": "Docker", "category": "Infrastructure", "description": "Trace a container mount to its Docker volume and inspect its driver and attachment.", "scope": "Docker Engine CLI with read access to the intended daemon; bind mounts and volumes are distinct mount types.", "prerequisites": "Confirm the Docker context and replace web and app-data with the actual container and volume. Inspect output can contain internal paths and configuration; these commands do not remove data.", "source": "https://docs.docker.com/reference/cli/docker/volume/ls/", "sourceLabel": "Docker volume list", "sources": [{"label": "Docker volume list", "url": "https://docs.docker.com/reference/cli/docker/volume/ls/"}, {"label": "Docker volume inspect", "url": "https://docs.docker.com/reference/cli/docker/volume/inspect/"}, {"label": "Docker volumes", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"label": "Docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}], "rows": [["docker context show", "Confirm the Docker context"], ["docker volume ls", "List volumes on the daemon"], ["docker volume inspect app-data", "Inspect the selected volume"], ["docker inspect --format \"{{json .Mounts}}\" web", "Inspect container mount attachments"], ["docker ps -a --filter volume=app-data", "List containers referencing the volume"]], "walkthrough": ["Compare the active context with the incident environment. A similarly named volume can exist on another daemon; check for endpoint overrides before interpreting results.", "Find the exact volume name and driver. Listing a volume does not prove that a particular container uses it or that its application data is current.", "Record the exact name, driver, scope and mountpoint. Driver behavior varies, and the daemon host mountpoint is not necessarily a path on a Docker Desktop client.", "Compare mount type, source or volume name, destination and read-write state. Bind mounts use host paths while Docker-managed volumes are identified by volume names.", "Compare container IDs and names with the expected workload. A reference does not establish that a service is healthy or that the application is writing to the expected path."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-13", "case": {"title": "Application data looks empty after recreation", "symptom": "A newly recreated container starts, but the application displays no previous data.", "steps": [{"action": "docker context show", "purpose": "Confirm the Docker context", "detail": "Confirm the CLI targets the intended Docker daemon."}, {"action": "docker volume ls", "purpose": "List volumes on the daemon", "detail": "Identify the exact volume name expected for the application."}, {"action": "docker inspect --format \"{{json .Mounts}}\" web", "purpose": "Inspect container mount attachments", "detail": "Compare the recreated container mount destination and volume name with the expected configuration."}, {"action": "docker ps -a --filter volume=app-data", "purpose": "List containers referencing the volume", "detail": "Check which containers reference the original named volume."}], "evidence": "Illustrative findings: the old container references app-data, while the replacement mounts a differently named volume.", "interpretation": "The mount mismatch explains why the replacement sees a different data location in this example. Do not delete either volume; verify the authoritative data and deployment configuration first.", "verification": "After the owner corrects the approved deployment, verify the mount and application data through its normal read path and backup procedures.", "escalation": "Provide daemon context, container IDs, volume names and mount destinations to the application owner without sharing data contents."}}, {"id": "kubernetes-cluster-dns-service-investigation", "title": "Kubernetes cluster DNS service investigation", "product": "Kubernetes", "vendor": "Kubernetes", "category": "Cloud", "description": "Inspect the cluster DNS Service, EndpointSlices, DNS pods and logs when workloads cannot resolve names.", "scope": "Kubernetes with kubectl read access to kube-system DNS resources. The common DNS Service is named kube-dns even when CoreDNS provides it.", "prerequisites": "Confirm the target cluster and authorized access. Labels and deployment names can vary; check the Service selector and pod labels before filtering. Commands inspect resources and logs without changing DNS configuration.", "source": "https://kubernetes.io/docs/tasks/administer-cluster/dns-debugging-resolution/", "sourceLabel": "Kubernetes DNS debugging", "sources": [{"label": "Kubernetes DNS debugging", "url": "https://kubernetes.io/docs/tasks/administer-cluster/dns-debugging-resolution/"}, {"label": "Kubernetes DNS for services and pods", "url": "https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/"}], "rows": [["kubectl config current-context", "Confirm the selected cluster"], ["kubectl get service kube-dns -n kube-system -o wide", "Inspect the cluster DNS Service"], ["kubectl describe service kube-dns -n kube-system", "Inspect DNS Service configuration"], ["kubectl get endpointslice -n kube-system -l kubernetes.io/service-name=kube-dns", "Inspect DNS EndpointSlices"], ["kubectl get pods -n kube-system -o wide", "Inspect system pod readiness"], ["kubectl logs -n kube-system deployment/coredns --since=30m --tail=100", "Review bounded CoreDNS logs"]], "walkthrough": ["Compare the local context with the approved cluster inventory. Context names are local labels and do not independently establish the target environment.", "Record the ClusterIP, exposed ports and selector. An assigned address does not prove that the service has ready backends or that clients can reach them.", "Review the actual selector, ports and endpoint summary. Use the selector returned by your environment rather than assuming every cluster uses the same DNS pod label.", "Compare the returned addresses and ports with the expected DNS backends. No endpoints can indicate a selector or readiness issue, but must be interpreted with the pod and Service state.", "Identify the actual DNS pods from their names and labels, then check readiness, restarts and node placement. A running pod is not necessarily ready or answering queries.", "Use this only if deployment/coredns exists in your environment; otherwise select the appropriate DNS workload. Redact internal names before sharing logs and correlate with the incident time."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-13", "case": {"title": "Workloads cannot resolve service names", "symptom": "Multiple pods report DNS timeouts while their applications remain running.", "steps": [{"action": "kubectl config current-context", "purpose": "Confirm the selected cluster", "detail": "Verify the cluster context before examining system resources."}, {"action": "kubectl get service kube-dns -n kube-system -o wide", "purpose": "Inspect the cluster DNS Service", "detail": "Confirm the kube-dns Service and its expected address and ports."}, {"action": "kubectl describe service kube-dns -n kube-system", "purpose": "Inspect DNS Service configuration", "detail": "Read the Service selector and compare it with the actual DNS pods."}, {"action": "kubectl get endpointslice -n kube-system -l kubernetes.io/service-name=kube-dns", "purpose": "Inspect DNS EndpointSlices", "detail": "Inspect the EndpointSlices for ready backend addresses."}, {"action": "kubectl get pods -n kube-system -o wide", "purpose": "Inspect system pod readiness", "detail": "Review DNS pod readiness and recent restarts in the same namespace."}], "evidence": "Illustrative findings: the DNS Service exists but its EndpointSlice has no ready addresses because the selected DNS pods are unready.", "interpretation": "Missing ready backends can explain failed queries through the Service in this example. Pod logs and readiness events are needed to establish why the DNS pods are unready.", "verification": "After the platform owner restores the DNS workload, verify ready EndpointSlices and repeat an approved name lookup from an affected workload.", "escalation": "Provide cluster, DNS Service selector, endpoint state, pod readiness and sanitized timestamps to the platform owner."}}, {"id": "linux-system-clock-synchronization-inspection", "title": "Linux system clock synchronization inspection", "product": "Linux", "vendor": "Linux", "category": "IT fundamentals", "description": "Inspect system time, synchronization status and the time service on a systemd-based Linux host.", "scope": "Linux running systemd; timesync-status specifically applies to systemd-timesyncd and may not apply to chrony or other time clients.", "prerequisites": "Run on the affected host with authorized journal access. These commands inspect time and service state without changing the clock or synchronization configuration.", "source": "https://www.freedesktop.org/software/systemd/man/latest/timedatectl.html", "sourceLabel": "systemd timedatectl", "sources": [{"label": "systemd timedatectl", "url": "https://www.freedesktop.org/software/systemd/man/latest/timedatectl.html"}, {"label": "systemd-timesyncd service", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd-timesyncd.service.html"}, {"label": "systemctl manual", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemctl.html"}], "rows": [["timedatectl status", "Inspect clock and synchronization status"], ["timedatectl show", "Read machine-readable clock properties"], ["systemctl status systemd-timesyncd.service --no-pager --full", "Inspect the timesyncd service"], ["timedatectl timesync-status", "Inspect timesyncd synchronization details"], ["journalctl -u systemd-timesyncd.service --since \"24 hours ago\" -n 100 --no-pager", "Review recent timesyncd events"]], "walkthrough": ["Record local time, universal time, time zone and synchronization indicators. A configured time zone changes display, while synchronization concerns the underlying clock; treat them as separate checks.", "Compare the reported time zone and synchronization properties with the intended host role. Property availability varies by systemd release and the active synchronization service.", "Use this when systemd-timesyncd is the intended client. A host may use chrony or another implementation instead, so an inactive timesyncd service is not automatically a fault.", "When systemd-timesyncd is active, examine the reported server and synchronization details. This command is specific to that service and may fail or be unavailable when another client is in use.", "Use this only for a host using systemd-timesyncd. Correlate server or network errors with the incident; log access and retention determine what is visible."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-13", "case": {"title": "A host has an incorrect clock", "symptom": "An application reports time-related errors on a systemd host that should use systemd-timesyncd.", "steps": [{"action": "timedatectl status", "purpose": "Inspect clock and synchronization status", "detail": "Record the clock, time zone and synchronization status."}, {"action": "systemctl status systemd-timesyncd.service --no-pager --full", "purpose": "Inspect the timesyncd service", "detail": "Confirm the intended time synchronization service and its current state."}, {"action": "timedatectl timesync-status", "purpose": "Inspect timesyncd synchronization details", "detail": "Inspect the selected time server and synchronization details."}, {"action": "journalctl -u systemd-timesyncd.service --since \"24 hours ago\" -n 100 --no-pager", "purpose": "Review recent timesyncd events", "detail": "Review relevant service messages for the incident window."}], "evidence": "Illustrative findings: the time zone is correct, but timesyncd is active and reports no successful synchronization with its configured server.", "interpretation": "The evidence supports investigating time-server reachability or configuration. An active service alone does not prove that the clock is synchronized.", "verification": "After the system owner resolves the approved time path, verify synchronization status and compare timestamps with a trusted reference.", "escalation": "Provide host identity, time service, server information and sanitized journal timestamps to the system owner."}}, {"id": "windows-certificate-store-inspection", "title": "Windows certificate store inspection", "product": "Windows", "vendor": "Windows", "category": "Cybersecurity", "description": "Inspect certificate stores, expiration dates and thumbprints when investigating a Windows service certificate.", "scope": "PowerShell Certificate provider on Windows. Store contents and private-key permissions depend on the account and host.", "prerequisites": "Run on the service host using authorized read access. Replace the example thumbprint with the actual public certificate identifier. These commands inspect certificates and do not export private keys or change bindings.", "source": "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.security/about/about_certificate_provider", "sourceLabel": "Microsoft Certificate provider", "sources": [{"label": "Microsoft Certificate provider", "url": "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.security/about/about_certificate_provider"}, {"label": "Microsoft certificate store management", "url": "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/inspect-certificates-manage-certificate-stores"}], "rows": [["Get-ChildItem Cert:\\LocalMachine", "List machine certificate stores"], ["Get-ChildItem Cert:\\LocalMachine\\My", "List machine personal certificates"], ["Get-ChildItem Cert:\\LocalMachine\\My | Select-Object Subject,Thumbprint,NotAfter,HasPrivateKey", "Inspect certificate identity and expiry"], ["Get-ChildItem Cert:\\LocalMachine\\My -ExpiringInDays 30", "Find certificates nearing expiration"], ["Get-Item Cert:\\LocalMachine\\My\\0123456789ABCDEF0123456789ABCDEF01234567 | Format-List *", "Inspect one certificate by thumbprint"]], "walkthrough": ["Inspect available machine-level stores and choose the store used by the service. A user-level store is separate, and store presence does not prove that a service is configured to use it.", "Review certificates in the local machine personal store. The list can include certificates for multiple services; match the thumbprint and hostname with the actual service configuration.", "Compare subject, thumbprint, expiration and private-key presence with the intended certificate. HasPrivateKey does not establish that the service account has permission to use the key.", "Review the returned certificates in context; an expiring certificate may be unused or already replaced. Confirm the service binding and complete chain before scheduling renewal work.", "Replace the example thumbprint with the certificate identifier and protect the output, which can reveal internal names. This reads certificate metadata; it does not prove which certificate a remote client receives."], "kind": "Command", "level": "Intermediate", "time": 6, "updated": "2026-11-13", "case": {"title": "A service presents an expired certificate", "symptom": "A Windows-hosted service has a renewed certificate, but clients still report an expiry error.", "steps": [{"action": "Get-ChildItem Cert:\\LocalMachine", "purpose": "List machine certificate stores", "detail": "Identify the certificate store used by the affected service."}, {"action": "Get-ChildItem Cert:\\LocalMachine\\My | Select-Object Subject,Thumbprint,NotAfter,HasPrivateKey", "purpose": "Inspect certificate identity and expiry", "detail": "Compare the old and renewed certificate thumbprints and expiration dates."}, {"action": "Get-ChildItem Cert:\\LocalMachine\\My -ExpiringInDays 30", "purpose": "Find certificates nearing expiration", "detail": "Check the expiring certificates in the machine personal store."}, {"action": "Get-Item Cert:\\LocalMachine\\My\\0123456789ABCDEF0123456789ABCDEF01234567 | Format-List *", "purpose": "Inspect one certificate by thumbprint", "detail": "Inspect the specific public certificate metadata by its confirmed thumbprint."}], "evidence": "Illustrative findings: a valid renewed certificate is present, while the service configuration still references the older expired thumbprint.", "interpretation": "The binding mismatch explains the reported certificate in this example. Certificate presence alone does not update a service binding or establish private-key access for the service account.", "verification": "After the service owner updates the approved binding, verify the certificate presented to a client, its hostname, chain and expiration using the normal application path.", "escalation": "Provide the service name, old and new public thumbprints and expiration dates to the certificate owner; never share private-key material."}}];window.PAGES={"about": ["A field guide for connected minds.", "Packetly brings practical IT references into one calm, searchable workspace. Explore Windows, Active Directory, Microsoft Graph, Entra ID, Exchange Online, Azure, FortiGate, Sophos, Cisco, Juniper, Ubiquiti, HPE, Dell and Data Domain, alongside Linux and cloud fundamentals. The name combines packets with an approachable “ly” ending.", "Our aim is to help you find the right command, understand its purpose and carry a useful reference to your desk. All guides are free to browse. Bookmarks are stored on your own device."], "editorial": ["Useful references, clear scope.", "Our guides prioritize inspection commands and explain their purpose in original walkthroughs. Each sheet includes its platform scope, update date and a link to primary documentation. Always consult the documentation for your deployed version.", "We do not claim that every command has been tested on every platform. We revise references when an error or version difference is identified. Vendor names belong to their respective owners. Sponsored placements, if introduced, will be labeled separately from editorial references."], "privacy": ["Privacy, in plain language.", "Packetly stores bookmarks and your theme preference in your browser’s local storage. These preferences are not submitted to a server by this website. You can clear them through your browser’s site-data settings.", "This website does not collect issue reports itself. The Report an issue button opens a pre-filled form on GitHub; anything you submit there becomes a public issue and is handled under GitHub’s own privacy terms. Hosting providers may process normal request logs. Google Fonts receives font requests, including normal network metadata.", "This site uses Google Analytics to measure traffic and Google AdSense to display advertising. Both are operated by Google, which may set cookies or similar identifiers in your browser and may process data including your IP address, device and browser details, and the pages you view. Google may use this data to personalise advertising. You can read how Google handles it at policies.google.com/technologies/partner-sites, choose your advertising settings at adssettings.google.com, and block or clear cookies through your browser’s settings. Analytics and advertising cookies stay switched off until you accept them in the banner shown on your first visit; use Change cookie choice below to answer again."], "terms": ["Use the guide with context.", "Packetly provides educational references without a warranty of completeness or compatibility. Verify commands against your platform documentation and your organization’s change process. Use commands only on systems you are authorized to administer.", "Fortinet, Cisco and other product names are trademarks of their respective owners. Packetly is independent and does not imply endorsement. Print references for personal learning and internal operational use."], "contact": ["Help make the next sheet better.", "Found an issue or need a tailored reference? Prepare a request with the sheet title, platform version, expected behavior and any correction. Do not include passwords, access tokens or private configuration.", "Use the button below to download a request brief you can share with your IT team. To report a correction, open the affected sheet and select Report an issue; it opens a pre-filled public issue on GitHub."]};window.TOPICS={"cybersecurity": "Cybersecurity", "networking": "Networking", "it-fundamentals": "IT fundamentals", "cloud": "Cloud", "identity-microsoft-365": "Identity & Microsoft 365", "infrastructure": "Infrastructure"};window.TOPIC_INTRO={"Cloud": "Cloud references for Azure, AWS, Kubernetes and Terraform: inventory, virtual networks, effective routes, security groups, pod readiness, workspaces and recorded infrastructure state, with practical investigation cases.", "Cybersecurity": "Security inspection references for FortiGate, Sophos and Kali Linux: firewall and cluster health, IPsec tunnels, session and traffic investigation, port discovery and packet analysis.", "IT fundamentals": "Everyday troubleshooting references for Windows and Linux hosts: addressing, DNS resolution, TCP reachability, systemd services, journals, event logs, time synchronization, Git changes and listening sockets.", "Identity & Microsoft 365": "Identity and Microsoft 365 references for Active Directory, Entra ID, Microsoft Graph and Exchange Online: users and groups, replication health, sign-in investigation, mailboxes, message tracing and Group Policy application.", "Infrastructure": "Infrastructure references for servers, storage, databases and automation: HPE and Dell health, Linux capacity, Windows DHCP and SMB, Docker, Ansible, Redis, PostgreSQL and MySQL investigations.", "Networking": "Network references for Cisco, Juniper, FortiGate, HPE Aruba, Ubiquiti, curl and NGINX: interfaces, VLANs, routes, neighbors, ARP, HTTP redirects, TLS certificates and reverse-proxy upstream investigation."};